		t.Fatalf("createWorktree: %v", err)
	}

	// The list command should work for external mode without errors
	// We can't easily capture stdout in a test, so just verify no error
	ws := internal.Workspace{MetadataRoot: internal.TwsRoot(), Mode: internal.ModeExternal}
	features, err := ws.ListFeaturesResolved()
	if err != nil {
		t.Fatalf("ListFeaturesResolved failed: %v", err)
	}
	if len(features) == 0 {
		t.Error("expected at least one feature for external mode")
	}
}

// ---------- External feature-dir doctor regression ----------

func TestExternalFeatureDir_DoctorRegression(t *testing.T) {
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)
	if err := createWorktree("ext-feat", "branch1", "master", repo, false); err != nil {
		t.Fatalf("createWorktree: %v", err)
	}

	// Override TWS_ROOT to feature-dir style
	featureDir := filepath.Join(t.TempDir(), "alt-features")
	if err := os.MkdirAll(featureDir, 0755); err != nil {
		t.Fatal(err)
	}
	oldRoot := os.Getenv("TWS_ROOT")
	// Copy feature to alt location
	origFP := filepath.Join(internal.TwsRoot(), "ext-feat")
	altFP := filepath.Join(featureDir, "ext-feat")
	cmd := exec.Command("cp", "-r", origFP, altFP)
	if err := cmd.Run(); err != nil {
		t.Fatalf("copy feature: %v", err)
	}
	t.Setenv("TWS_ROOT", featureDir)
	defer func() {
		if oldRoot == "" {
			t.Setenv("TWS_ROOT", "")
		}
	}()

	// Doctor should still work on external features
	ws, cfg := doctorFeatureContext(t)
	issues, err := checkFeatureE(ws, cfg, "ext-feat")
	if err != nil {
		t.Fatalf("checkFeatureE in feature-dir: %v", err)
	}
	_ = issues
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// runCheckoutSync is the checkout-mode arm of `tws sync`. It receives the
// workspace RunE already resolved — used only for ws.RepoRoot and the mode
// decision — and keeps its own internal.RequireFeaturePath call verbatim, so
// the guard, the layout resolution, and the error semantics are unchanged.
func runCheckoutSync(cmd *cobra.Command, ws internal.Workspace, opts internal.CheckoutSyncOpts) error {
	feature := opts.Feature
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return err
	}
	opts.FeaturePath = featurePath
	opts.RepoDir = ws.RepoRoot
	// Rule R-PUSH's record location. The command route owns the workspace, so
	// it resolves the location once and hands it down; package internal never
	// re-derives workspace identity inside a push loop.
	opts.Reparent = internal.ReparentLocationFor(ws, feature, featurePath)
	opts.ReparentProse = cmd.ErrOrStderr()

	// --plan describes the run this invocation would perform and exits
	// (spec §3.3 step 6): it is dispatched below RequireFeaturePath but
	// above the I19 containment refusal, since a plan never mutates and so
	// never needs the single-checkout containment guarantee a MUTATING
	// checkout route requires.
	if opts.PlanGuard.Plan {
		plan, planErr := internal.PlanCheckoutRebase(opts, internal.PlanWriters{Prose: cmd.ErrOrStderr()})
		if planErr != nil {
			return planGuardRefusal(cmd, planErr)
		}
		return renderPlanDocument(cmd, plan, opts.PlanGuard.JSON)
	}

	// I19 containment: checkout sync operates on the single checkout, never on
	// a linked worktree that merely happens to be the current directory.
	if err := checkoutContainmentGate(ws); err != nil {
		return err
	}

	if opts.Abort {
		if err := internal.AbortCheckoutSync(opts); err != nil {
			return err
		}
		fmt.Println("Checkout sync aborted, original branch restored.")
		return nil
	}

	if opts.Continue {
		tx, loadErr := internal.LoadCheckoutTransaction(featurePath)
		// I20 rule 0: trigger flags on --continue require v2 state. This
		// mirrors internal.CheckoutTriggersNeedV2 exactly —
		// route-aware, not a bare StateVersion compare — so a persisted
		// route:legacy transaction still refuses a new-mode trigger flag
		// even though its StateVersion alone would already satisfy the old
		// naive check.
		if opts.NewMode && internal.CheckoutTriggersNeedV2(tx, loadErr) {
			return fmt.Errorf("%s", errSyncModeFlagsNeedV2)
		}
		opts.PlanGuard.PersistedGuarded = internal.TransactionGuarded(tx)
		if err := internal.ContinueCheckoutSync(opts); err != nil {
			return planGuardRefusal(cmd, err)
		}
		fmt.Println("Checkout sync completed.")
		return nil
	}

	// Fresh sync
	if internal.HasCheckoutTransaction(featurePath) {
		return fmt.Errorf("previous checkout-sync incomplete; use --continue or --abort")
	}

	if err := internal.RunCheckoutSync(opts); err != nil {
		return planGuardRefusal(cmd, err)
	}
	fmt.Println("Checkout sync complete.")
	return nil
}

// checkoutContainmentGate is the I19 containment refusal, extracted so the
// plan-only dispatch above can bypass it without duplicating it.
func checkoutContainmentGate(ws internal.Workspace) error {
	cwd, err := os.Getwd()
	if err != nil {
		return err
	}
	top, topErr := internal.GitRepoRootIn(cwd)
	if topErr != nil || filepath.Clean(top) != filepath.Clean(ws.RepoRoot) {
		return fmt.Errorf("checkout sync operates on %s but the current directory belongs to working tree %s; run it from the repository checkout", ws.RepoRoot, top)
	}
	return nil
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func doctorCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "doctor [feature]",
		Short: "Run health checks on workspaces",
		Long: `Check workspace and stack health. With no args, checks all features.

Also reports stack ancestry for every configured parent-child edge: current,
stale, divergent, missing, cross-repo-unsupported, or unevaluated, each with its
reason and actionable guidance when available. Ancestry evaluation is strictly
read-only and never contacts a remote; when the source repository cannot be
determined the feature reports a single informational line and the remaining
checks still run.

Warnings such as a dirty checkout, active Git operation, stale ancestry, or
recoverable lock/session state are reported with exit 0 for interactive use.
Corrupt or unreadable persisted state returns a non-zero exit status.`,
		Args: cobra.MaximumNArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			// Checkout mode dispatch
			ws, wsErr := internal.RequireWorkspace()
			if wsErr != nil {
				// Fail closed on persisted-state errors. A workspace that
				// cannot be resolved from inside a Git repository means the
				// repo-local config is unusable (invalid workspace_mode, for
				// example) and doctor must report it instead of silently
				// continuing in external mode. Only a cwd with no repository
				// at all — an external workspace root or feature directory —
				// may fall through, which is the case ancestry then reports as
				// unevaluated.
				if _, repoErr := internal.MainRepoRoot(); repoErr == nil {
					return wsErr
				}
			} else if ws.Mode == internal.ModeCheckout {
				feature := ""
				if len(args) == 1 {
					feature = args[0]
				}
				return runCheckoutDoctor(cmd, ws, feature)
			}

			cfg := internal.LoadConfig()

			if len(args) == 1 {
				// §11.10 rule 1: the anchored line goes to stderr BEFORE any
				// ancestry output reaches stdout.
				if featurePath, rerr := internal.ResolveFeaturePathFor(ws, args[0]); rerr == nil {
					writeReparentNoticeFor(cmd.ErrOrStderr(), ws, args[0], featurePath)
				}
				_, err := checkFeatureE(ws, cfg, args[0])
				return err
			}

			// Check all features
			features, listErr := internal.ListFeaturesE()
			if listErr != nil {
				return listErr
			}
			if len(features) == 0 {
				fmt.Println("No features found.")
				return nil
			}

			writeReparentNoticesForAll(cmd.ErrOrStderr(), ws, features)

			totalIssues := 0
			for _, feature := range features {
				issues, err := checkFeatureE(ws, cfg, feature)
				if err != nil {
					return err
				}
				totalIssues += issues
			}

			if totalIssues == 0 {
				fmt.Println("\nAll healthy.")
			} else {
				fmt.Printf("\n%d issue(s) found.\n", totalIssues)
			}
			return nil
		},
	}
}

func checkFeatureE(ws internal.Workspace, cfg internal.Config, feature string) (int, error) {
	// Resolve from the workspace the command already resolved rather than
	// re-deriving one: doctor must still run from an external workspace root
	// or feature directory when the source repository is unavailable, which is
	// exactly the case ancestry then reports as unevaluated.
	featurePath, err := internal.ResolveFeaturePathFor(ws, feature)
	if err != nil {
		return 0, err
	}

	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("%s: not found\n", feature)
		return 0, nil
	}

	issues := internal.CheckFeatureHealth(featurePath)

	if stack, sErr := internal.LoadStack(featurePath); sErr == nil && len(stack.Branches) > 0 {
		edges, res := internal.FeatureStackEdges(ws, cfg, feature, featurePath, stack)
		// §11.10 rule 2: while a reparent artifact exists, doctor still reports
		// every ancestry status and reason and withholds only the repair
		// guidance, which names verbs §11.2 refuses.
		if internal.ReparentGuidanceSuppressed(ws, feature, featurePath) {
			edges = internal.SuppressReparentAncestryGuidance(edges)
		}
		issues = append(issues, internal.AncestryHealthIssues(res, edges)...)
	}

	counted := internal.CountHealthIssues(issues)

	if counted == 0 {
		// Count active worktrees
		wtDir := filepath.Join(featurePath, "worktrees")
		entries, _ := os.ReadDir(wtDir)
		active := 0
		for _, e := range entries {
			if e.IsDir() {
				active++
			}
		}
		fmt.Printf("%s: healthy (%d active worktree(s))\n", feature, active)
	} else {
		fmt.Printf("%s: %d issue(s)\n", feature, counted)
	}
	for _, issue := range issues {
		fmt.Println(issue)
	}

	return counted, nil
}

func runCheckoutDoctor(cmd *cobra.Command, ws internal.Workspace, feature string) error {
	report, err := internal.BuildCheckoutHealthReport(ws, nil)
	if err != nil {
		return err
	}
	if feature != "" {
		if err := report.FilterFeature(feature); err != nil {
			return err
		}
	}
	// §11.10 rule 1, checkout arm: the line precedes the stdout report.
	if feature != "" {
		if featurePath, rerr := ws.ResolveFeaturePath(feature); rerr == nil {
			writeReparentNoticeFor(cmd.ErrOrStderr(), ws, feature, featurePath)
		}
	} else {
		writeReparentNoticesForWorkspace(cmd.ErrOrStderr(), ws)
	}
	fmt.Print(internal.FormatCheckoutHealth(report))
	if report.HasErrors() {
		return fmt.Errorf("checkout workspace has corrupt or unreadable state")
	}
	return nil
}

package cli

import (
	"archive/tar"
	"compress/gzip"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func importCmd() *cobra.Command {
	var fromRepo string

	cmd := &cobra.Command{
		Use:   "import [file]",
		Short: "Import workspace from YAML or tarball",
		Long: `Recreate a workspace from an exported YAML or tarball.

  tws import auth-workspace.yaml           # from YAML file
  tws import auth-workspace.tar.gz         # from tarball (includes inject files)
  tws import --from-repo auth              # from .tws/workspaces/auth.yaml`,
		Args: cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}

			if fromRepo != "" {
				return importFromRepoE(fromRepo, ws)
			}

			if len(args) == 0 {
				return fmt.Errorf("usage: tws import <file> or tws import --from-repo <feature>")
			}

			file := args[0]
			if strings.HasSuffix(file, ".tar.gz") || strings.HasSuffix(file, ".tgz") {
				return importTarballE(file, ws)
			}
			return importYAMLE(file, ws)
		},
	}

	cmd.Flags().StringVar(&fromRepo, "from-repo", "", "Import from .tws/workspaces/<feature>.yaml")

	return cmd
}

func importFromRepoE(feature string, ws internal.Workspace) error {
	repoRoot, err := internal.MainRepoRoot()
	if err != nil {
		return fmt.Errorf("not inside a git repository")
	}

	path := filepath.Join(repoRoot, ".tws", "workspaces", feature+".yaml")
	return importYAMLE(path, ws)
}

func importYAMLE(file string, ws internal.Workspace) error {
	data, err := os.ReadFile(file)
	if err != nil {
		return fmt.Errorf("reading %s: %w", file, err)
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing %s: %w", file, err)
	}

	return recreateWorkspaceE(export, "", ws)
}

func importTarballE(file string, ws internal.Workspace) error {
	f, err := os.Open(file)
	if err != nil {
		return fmt.Errorf("opening %s: %w", file, err)
	}
	defer f.Close() //nolint:errcheck

	gr, err := gzip.NewReader(f)
	if err != nil {
		return fmt.Errorf("not a valid gzip file: %w", err)
	}
	defer gr.Close() //nolint:errcheck

	tmpDir, err := os.MkdirTemp("", "tws-import-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir) //nolint:errcheck

	tr := tar.NewReader(gr)
	for {
		header, err := tr.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("reading tarball: %w", err)
		}

		if isRuntimeState(header.Name) {
			continue
		}
		target, err := safeArchiveTarget(tmpDir, header.Name)
		if err != nil {
			return err
		}
		switch header.Typeflag {
		case tar.TypeDir:
			if err := os.MkdirAll(target, 0755); err != nil {
				return fmt.Errorf("creating archive directory %s: %w", header.Name, err)
			}
		case tar.TypeReg:
			if err := os.MkdirAll(filepath.Dir(target), 0755); err != nil {
				return fmt.Errorf("creating parent for %s: %w", header.Name, err)
			}
			outFile, err := os.OpenFile(target, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
			if err != nil {
				return fmt.Errorf("creating extracted file %s: %w", header.Name, err)
			}
			if _, copyErr := io.Copy(outFile, tr); copyErr != nil {
				_ = outFile.Close()
				return fmt.Errorf("extracting %s: %w", header.Name, copyErr)
			}
			if err := outFile.Close(); err != nil {
				return fmt.Errorf("closing extracted file %s: %w", header.Name, err)
			}
		default:
			return fmt.Errorf("unsupported archive entry %q (type %d)", header.Name, header.Typeflag)
		}
	}

	data, err := os.ReadFile(filepath.Join(tmpDir, "workspace.yaml"))
	if err != nil {
		return fmt.Errorf("tarball missing workspace.yaml")
	}

	export, err := internal.UnmarshalExport(data)
	if err != nil {
		return fmt.Errorf("parsing workspace.yaml: %w", err)
	}

	injectSrc := filepath.Join(tmpDir, "inject")
	return recreateWorkspaceE(export, injectSrc, ws)
}

func safeArchiveTarget(root, name string) (string, error) {
	if name == "" || filepath.IsAbs(name) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	clean := filepath.Clean(filepath.FromSlash(name))
	if clean == "." || clean == ".." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("unsafe archive path %q", name)
	}
	root = filepath.Clean(root)
	target := filepath.Join(root, clean)
	rel, err := filepath.Rel(root, target)
	if err != nil || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return "", fmt.Errorf("archive path escapes destination: %q", name)
	}
	return target, nil
}

// isRuntimeState returns true for explicit runtime-state paths.
//
// The list is exact-name only, with ONE deliberate prefix family: every
// `.reparent*` artifact of the safe-reparent transaction — the state file, the
// remote follow-up record and the `.reparent/` scratch tree — is runtime state
// that must never travel in an export or be recreated by an import. They are
// grouped by prefix rather than enumerated because the scratch tree's children
// are run-id-named and cannot be listed. No user file can collide: the whole
// family is dot-prefixed and tool-owned.
//
// Any other future runtime-state file MUST be added here explicitly.
func isRuntimeState(path string) bool {
	normalized := filepath.ToSlash(path)
	if reparentPathHasScratchComponent(normalized) {
		return true
	}
	return strings.HasPrefix(normalized, ".tws/state/") ||
		normalized == ".tws/state" ||
		normalized == ".sync-state.yaml" ||
		normalized == ".sync-state.v2.yaml" ||
		normalized == ".sync-run.lock"
}

func recreateWorkspaceE(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	if ws.Mode == internal.ModeCheckout {
		return recreateCheckout(export, injectSrc, ws)
	}
	return recreateExternal(export, injectSrc)
}

// recreateCheckout imports into checkout mode: restores under .tws/features/,
// creates/registers branches without linked worktrees, never imports runtime state.
func recreateCheckout(export internal.WorkspaceExport, injectSrc string, ws internal.Workspace) error {
	feature := export.Feature
	if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
		return err
	}

	featurePath := ws.FeaturePath(feature)

	if err := os.MkdirAll(featurePath, 0755); err != nil {
		return fmt.Errorf("creating feature directory: %w", err)
	}

	// FEATURE.md
	featureMD := filepath.Join(featurePath, "FEATURE.md")
	if _, err := os.Stat(featureMD); os.IsNotExist(err) {
		_ = os.WriteFile(featureMD, []byte("# "+feature+"\n"), 0644)
	}

	// Stack
	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			return fmt.Errorf("writing stack.yaml: %w", err)
		}
		fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
	}

	// Decisions
	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	// Inject files
	injectDir := internal.InjectPath(featurePath)
	if err := os.MkdirAll(injectDir, 0755); err != nil {
		return fmt.Errorf("creating inject directory: %w", err)
	}
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	// Register branches (no worktrees in checkout mode)
	for _, entry := range export.Stack.Branches {
		gitBranch := entry.GitBranch()
		if internal.VerifyGitRef(ws.RepoRoot, gitBranch) == nil {
			fmt.Printf("  [=] %s (branch exists: %s)\n", entry.Name, gitBranch)
		} else {
			fmt.Printf("  [-] %s (branch %s not found — fetch from remote first)\n", entry.Name, gitBranch)
		}
	}

	fmt.Printf("Imported feature: %s (checkout mode — no worktrees created)\n", feature)
	return nil
}

// recreateExternal imports into external mode (original behavior).
func recreateExternal(export internal.WorkspaceExport, injectSrc string) error {
	feature := export.Feature
	wsRoot := internal.TwsRoot()
	if err := internal.GuardFeatureName(wsRoot, feature); err != nil {
		return err
	}

	featurePath := internal.FeaturePath(feature)

	if err := internal.EnsureExternalWorkspaceMarker(wsRoot); err != nil {
		return err
	}
	os.MkdirAll(filepath.Join(featurePath, "worktrees"), 0755) //nolint:errcheck

	if _, err := os.Stat(filepath.Join(featurePath, "FEATURE.md")); os.IsNotExist(err) {
		os.WriteFile(filepath.Join(featurePath, "FEATURE.md"), []byte("# "+feature+"\n"), 0644) //nolint:errcheck
	}

	if len(export.Stack.Branches) > 0 {
		if err := internal.SaveStack(featurePath, export.Stack); err != nil {
			fmt.Printf("Warning: could not write stack.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored stack.yaml (%d branches)\n", len(export.Stack.Branches))
		}
	}

	if len(export.Decisions.Entries) > 0 {
		if err := internal.SaveDecisions(featurePath, export.Decisions); err != nil {
			fmt.Printf("Warning: could not write decisions.yaml: %v\n", err)
		} else {
			fmt.Printf("  Restored decisions.yaml (%d entries)\n", len(export.Decisions.Entries))
		}
	}

	injectDir := internal.InjectPath(featurePath)
	os.MkdirAll(injectDir, 0755) //nolint:errcheck
	if injectSrc != "" {
		if _, err := os.Stat(injectSrc); err == nil {
			count, _ := copyDir(injectSrc, injectDir)
			if count > 0 {
				fmt.Printf("  Restored %d inject file(s)\n", count)
			}
		}
	}

	for _, entry := range export.Stack.Branches {
		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			fmt.Printf("  [=] %s (already exists)\n", entry.Name)
			continue
		}

		if internal.BranchExists(entry.Name) {
			err := internal.RunSilent("git", "worktree", "add", "--force", path, entry.Name)
			if err != nil {
				fmt.Printf("  [x] %s (checkout failed)\n", entry.Name)
			} else {
				fmt.Printf("  [+] %s (checked out)\n", entry.Name)
			}
		} else {
			fmt.Printf("  [-] %s (branch not found — fetch from remote first)\n", entry.Name)
		}
	}

	target := internal.ResolveInjectInto("")
	count, _ := internal.InjectFilesForFeature(featurePath, target)
	if count > 0 {
		fmt.Printf("  Injected files into %d worktree(s)\n", count)
	}

	fmt.Printf("Imported feature: %s\n", feature)
	return nil
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func listCmd() *cobra.Command {
	return &cobra.Command{
		Use:     "list",
		Aliases: []string{"ls"},
		Short:   "List features and branches",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				// Fallback to legacy TwsRoot for external mode compat.
				wsRoot := internal.TwsRoot()
				if _, serr := os.Stat(wsRoot); os.IsNotExist(serr) {
					fmt.Println("No workspace found. Use 'tws init --mode checkout' or 'tws enable --mode checkout'.")
					return nil
				}
				// Build a minimal workspace for listing.
				ws = internal.Workspace{MetadataRoot: wsRoot, Mode: internal.ModeExternal}
			}

			// Checkout mode dispatch
			if ws.Mode == internal.ModeCheckout {
				return runCheckoutList(cmd, ws)
			}

			features, listErr := ws.ListFeaturesResolved()
			if listErr != nil {
				return listErr
			}

			if len(features) == 0 {
				fmt.Println("No features found. Use 'tws add <feature>' to create one.")
				return nil
			}

			// §11.10 rule 1: one anchored line per affected feature, on
			// stderr, before any of the listing below reaches stdout.
			writeReparentNoticesForAll(cmd.ErrOrStderr(), ws, features)

			fmt.Printf("Workspace: %s (mode: %s)\n\n", ws.MetadataRoot, ws.Mode)

			// Deliberately guard-free: ListFeaturesResolved has already removed
			// space-owned names, and an untrusted spaces.yaml aborted above.
			for _, feature := range features {
				featurePath, resolveErr := ws.ResolveFeaturePath(feature)
				if resolveErr != nil {
					// Ambiguity error — report it inline.
					fmt.Printf("%s\n  ERROR: %v\n\n", feature, resolveErr)
					continue
				}

				fmt.Printf("%s\n", feature)

				stack, serr := internal.LoadStack(featurePath)
				if serr == nil && len(stack.Branches) > 0 {
					for i, entry := range stack.Branches {
						wtPath := filepath.Join(featurePath, "worktrees", entry.Name)
						status := "active"
						if _, err := os.Stat(wtPath); os.IsNotExist(err) {
							if internal.IsPrunableWorktree(entry.Name) {
								status = "missing"
							} else {
								status = "archived"
							}
						}

						tmuxTag := ""
						session := sanitizeSessionName(feature + "/" + entry.Name)
						if sessionExists(session) {
							tmuxTag = " [tmux]"
						}

						healthTag := ""
						if status == "active" {
							if issue := internal.CheckWorktreeBranch(wtPath, entry.Name); issue != nil {
								healthTag = " [wrong-branch!]"
							}
						}

						connector := "├──"
						if i == len(stack.Branches)-1 {
							connector = "└──"
						}
						fmt.Printf("  %s %s (base: %s) [%s]%s%s\n", connector, entry.Name, entry.Base, status, tmuxTag, healthTag)
					}
				} else {
					wtDir := filepath.Join(featurePath, "worktrees")
					wts, rErr := os.ReadDir(wtDir)
					if rErr != nil || len(wts) == 0 {
						fmt.Println("  (no branches)")
					} else {
						for i, wt := range wts {
							if !wt.IsDir() {
								continue
							}
							connector := "├──"
							if i == len(wts)-1 {
								connector = "└──"
							}
							fmt.Printf("  %s %s\n", connector, wt.Name())
						}
					}
				}
				fmt.Println()
			}
			return nil
		},
	}
}

func runCheckoutList(cmd *cobra.Command, ws internal.Workspace) error {
	entries, err := internal.BuildCheckoutList(ws)
	if err != nil {
		return err
	}
	writeReparentNoticesForWorkspace(cmd.ErrOrStderr(), ws)
	fmt.Print(internal.FormatCheckoutList(ws, entries))
	return nil
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func openCmd() *cobra.Command {
	var useTmux bool
	var noTmux bool
	var noAgent bool
	var featureDir bool
	var all bool

	cmd := &cobra.Command{
		Use:   "open [feature] [branch]",
		Short: "Open worktree and run agent",
		Long: `Open a worktree and run the configured agent. With no args, shows an interactive picker.

Use --feature-dir to open the feature directory itself (orchestrator mode).
Use --all to create a tmux session with windows for every worktree in the feature.`,
		Args: cobra.RangeArgs(0, 2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// Checkout mode: delegate to checkout session flow
			if ws.Mode == internal.ModeCheckout {
				if all {
					return fmt.Errorf("--all not supported in checkout mode")
				}

				// --feature-dir handled before branch resolution
				if featureDir {
					if len(args) < 1 {
						return fmt.Errorf("usage: tws open <feature> --feature-dir")
					}
					feature := args[0]
					if gerr := internal.GuardFeatureName(ws.MetadataRoot, feature); gerr != nil {
						return gerr
					}
					fp, ferr := ws.ResolveFeaturePath(feature)
					if ferr != nil {
						return ferr
					}
					// §14.2a: no session, no terminal, while a reparent is
					// recorded for this feature.
					if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
						return rerr
					}
					if noAgent {
						fmt.Printf("cd %s\n", fp)
						return nil
					}
					fmt.Printf("Opening feature dir: %s\n", fp)
					// Untracked: a feature directory is not a logical branch,
					// so no direct session record is created.
					return openDirect(directOpenOpts{Path: fp})
				}

				return runCheckoutOpen(ws, args, useTmux, noTmux, noAgent, cmd.Flags())
			}

			// Handle --all: tmux session with all worktrees
			if all {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --all")
				}
				// Guarded because the feature name is joined under TwsRoot().
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
				if rerr := refuseOpenDuringReparent(ws, args[0]); rerr != nil {
					return rerr
				}
				openAll(args[0])
				return nil
			}

			// Handle --feature-dir: open the feature directory
			if featureDir {
				if len(args) < 1 {
					return fmt.Errorf("usage: tws open <feature> --feature-dir")
				}
				feature := args[0]
				// Guarded because the feature name is joined under TwsRoot().
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), feature); gerr != nil {
					return gerr
				}
				if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
					return rerr
				}
				path := internal.FeaturePath(feature)
				if _, err := os.Stat(path); os.IsNotExist(err) {
					return fmt.Errorf("feature not found: %s", feature)
				}
				if noAgent {
					fmt.Printf("cd %s\n", path)
					return nil
				}
				fmt.Printf("Opening feature dir: %s\n", path)
				// Untracked: see the checkout branch above.
				return openDirect(directOpenOpts{Path: path})
			}

			// Normal mode: open a specific worktree
			if len(args) >= 1 {
				// The 0-arg picker is covered by ListFeaturesE inside
				// resolveOpenArgs.
				if gerr := internal.GuardFeatureName(internal.TwsRoot(), args[0]); gerr != nil {
					return gerr
				}
			}
			feature, branch, err := resolveOpenArgs(args)
			if err != nil {
				return err
			}
			// §14.2a, after the picker has settled the identity: the exclusion
			// covers the 0-arg and 1-arg picker routes too.
			if rerr := refuseOpenDuringReparent(ws, feature); rerr != nil {
				return rerr
			}

			path := internal.WorktreePath(feature, branch)

			if _, err := os.Stat(path); os.IsNotExist(err) {
				return fmt.Errorf("worktree not found: %s", path)
			}

			// Re-sync inject files
			featurePath := internal.FeaturePath(feature)
			injectTarget := internal.ResolveInjectInto("")
			if err := internal.InjectFiles(featurePath, path, injectTarget); err != nil {
				fmt.Printf("Warning: inject sync failed: %v\n", err)
			}

			// Show unread decisions count
			unread := internal.UnreadDecisions(featurePath, branch)
			if len(unread) > 0 {
				targeted := 0
				for _, d := range unread {
					if d.To != "" {
						targeted++
					}
				}
				msg := fmt.Sprintf("  %d new decision(s)", len(unread))
				if targeted > 0 {
					msg += fmt.Sprintf(" (%d for you)", targeted)
				}
				msg += fmt.Sprintf(" (run: tws decisions show %s)", feature)
				fmt.Println(msg)
			}

			if noAgent {
				fmt.Printf("cd %s\n", path)
				fmt.Println("Run your agent manually from there.")
				return nil
			}

			// Resolve tmux preference
			tmux := useTmux
			if !cmd.Flags().Changed("tmux") && !noTmux {
				cfg := internal.LoadConfig()
				if cfg.UseTmux != nil {
					tmux = *cfg.UseTmux
				}
			}
			if noTmux {
				tmux = false
			}

			if tmux {
				openWithTmux(feature, branch, path)
			} else {
				// Warn if there's a stale tmux session
				session := sanitizeSessionName(feature + "/" + branch)
				if sessionExists(session) {
					fmt.Printf("Warning: tmux session %q exists for this worktree.\n", session)
					fmt.Printf("  Run 'tws close %s %s' to kill it, or use --tmux to attach.\n", feature, branch)
				}
				return openDirect(directOpenOpts{
					Path:        path,
					Feature:     feature,
					Name:        branch,
					GitBranch:   resolveDirectGitBranch(featurePath, branch),
					FeaturePath: featurePath,
				})
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&useTmux, "tmux", false, "Wrap in tmux session")
	cmd.Flags().BoolVar(&noTmux, "no-tmux", false, "Skip tmux even if configured")
	cmd.Flags().BoolVar(&noAgent, "no-agent", false, "Just print the worktree path")
	cmd.Flags().BoolVar(&featureDir, "feature-dir", false, "Open the feature directory (orchestrator mode)")
	cmd.Flags().BoolVar(&all, "all", false, "Create tmux session with windows for all worktrees")

	return cmd
}

func resolveOpenArgs(args []string) (string, string, error) {
	var feature, branch string
	var err error

	switch len(args) {
	case 2:
		return args[0], args[1], nil
	case 1:
		feature = args[0]
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	case 0:
		features, listErr := internal.ListFeaturesE()
		if listErr != nil {
			return "", "", listErr
		}
		if len(features) == 0 {
			return "", "", fmt.Errorf("no features found. Use 'tws add <feature>' to create one")
		}
		feature, err = pick("Select feature:", features)
		if err != nil {
			return "", "", err
		}
		branches := internal.ListBranches(feature)
		if len(branches) == 0 {
			return "", "", fmt.Errorf("no branches found for feature: %s", feature)
		}
		branch, err = pick("Select branch:", branches)
		if err != nil {
			return "", "", err
		}
		return feature, branch, nil
	}
	return "", "", fmt.Errorf("unexpected args")
}

// openAll creates a tmux session with the feature dir as the first window
// and one window per active worktree.
func openAll(feature string) {
	internal.RequireTool("tmux")

	featurePath := internal.FeaturePath(feature)
	if _, err := os.Stat(featurePath); os.IsNotExist(err) {
		fmt.Printf("Feature not found: %s\n", feature)
		os.Exit(1)
	}

	session := sanitizeSessionName(feature)

	// Kill existing session if any
	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	// Create session with feature dir as first window
	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", featurePath, "-n", "orchestrator"))

	// Add a window for each active worktree
	branches := internal.ListBranches(feature)
	for _, branch := range branches {
		wtPath := internal.WorktreePath(feature, branch)
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue // archived
		}
		windowName := sanitizeSessionName(branch)
		_ = internal.RunSilent("tmux", "new-window", "-t", session, "-n", windowName, "-c", wtPath)
	}

	// Select the orchestrator window
	_ = internal.RunSilent("tmux", "select-window", "-t", session+":orchestrator")

	// Attach
	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func openWithTmux(feature, branch, path string) {
	internal.RequireTool("tmux")

	session := sanitizeSessionName(feature + "/" + branch)

	if sessionExists(session) {
		fmt.Printf("Attaching to existing session: %s\n", session)
		internal.Must(internal.Run("tmux", "attach", "-t", session))
		return
	}

	cfg := internal.LoadConfig()
	agentCmd := cfg.GetAgentCommand()

	if isClaudeAgent(agentCmd) && hasClaudeSession(path) {
		agentCmd = agentCmd + " -c"
	}

	fmt.Printf("Creating tmux session: %s\n", session)
	internal.Must(internal.Run("tmux", "new-session", "-d", "-s", session, "-c", path))

	fmt.Printf("Running: %s\n", agentCmd)
	internal.Must(internal.Run("tmux", "send-keys", "-t", session, agentCmd, "Enter"))

	internal.Must(internal.Run("tmux", "attach", "-t", session))
}

func sessionExists(name string) bool {
	cmd := exec.Command("tmux", "has-session", "-t", name)
	err := cmd.Run()
	return err == nil
}

func sanitizeSessionName(s string) string {
	return internal.SanitizeTmuxName(s)
}

func isClaudeAgent(cmd string) bool {
	fields := strings.Fields(cmd)
	if len(fields) == 0 {
		return false
	}
	base := fields[0]
	return base == "claude" || base == "claude-dev" || base == "cc"
}

func hasClaudeSession(workdir string) bool {
	home, err := os.UserHomeDir()
	if err != nil {
		return false
	}

	absPath, err := filepath.Abs(workdir)
	if err != nil {
		return false
	}

	encoded := strings.ReplaceAll(absPath, string(filepath.Separator), "-")
	projectDir := filepath.Join(home, ".claude", "projects", encoded)

	info, err := os.Stat(projectDir)
	if err != nil {
		return false
	}
	return info.IsDir()
}

package cli

import (
	"fmt"
	"os"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func pushCmd() *cobra.Command {
	var dryRun bool

	cmd := &cobra.Command{
		Use:   "push <feature>",
		Short: "Push all branches in a feature with --force-with-lease",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			internal.RequireTool("git")
			feature := args[0]

			ws, err := internal.RequireWorkspace()
			if err != nil {
				return err
			}
			// The sibling-space guard used to arrive through
			// internal.RequireFeaturePath; the external arm no longer calls it,
			// so the command owns the guard explicitly, before any layout work.
			if err := internal.GuardFeatureName(ws.MetadataRoot, feature); err != nil {
				return err
			}
			if ws.Mode == internal.ModeCheckout {
				return pushFeatureCheckout(feature, dryRun)
			}
			layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), feature)
			if err != nil {
				return err
			}
			return pushFeature(feature, layout, dryRun)
		},
	}

	cmd.Flags().BoolVar(&dryRun, "dry-run", false, "Show what would be pushed without pushing")

	return cmd
}

// externalReparentLocation is the external push paths' record location. It is
// derived from the already-resolved layout and needs NO workspace probe: in
// external mode both the reparent state artifact and the §12.3 remote
// follow-up record live directly inside the feature directory, so FeaturePath
// and the mode are the whole identity.
func externalReparentLocation(feature string, layout externalSyncLayout) internal.ReparentLocation {
	return internal.ReparentLocation{
		Mode:        internal.ModeExternal,
		Feature:     feature,
		FeaturePath: layout.FeaturePath,
	}
}

// pushFeature pushes every entry of an external feature. It takes the resolved
// layout so the push half of a run can never target a different root than the
// rebase half.
func pushFeature(feature string, layout externalSyncLayout, dryRun bool) error {
	stack, err := internal.LoadStack(layout.FeaturePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}
	return pushEntries(feature, layout, stack.Branches, dryRun)
}

// pushScoped is the sync-side push of a new-mode run, for every scope. It is
// strict and payload-aware: it pushes only the entries this run selected AND
// successfully rebased, in selection order, records every success in the
// payload before the next push is attempted, and stops at the first failure so
// `--continue` can retry exactly the entries that were never pushed.
func pushScoped(feature string, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, completed []string, payload *internal.SyncRunState) error {
	if payload == nil {
		return fmt.Errorf("internal error: new-mode push without run state for %s", feature)
	}
	rebased := make(map[string]bool, len(completed))
	for _, name := range completed {
		rebased[name] = true
	}
	alreadyPushed := make(map[string]bool, len(payload.Pushed))
	for _, name := range payload.Pushed {
		alreadyPushed[name] = true
	}

	// Rule R-PUSH: the record is loaded ONCE and the preflight runs above the
	// loop, over exactly the entries this invocation would push. pushScoped
	// has no dry-run branch and gains none.
	env := internal.LoadReparentPushEnvelope(externalReparentLocation(feature, layout), "")
	var probes []internal.ReparentPushEntryProbe
	if env.Active() {
		for _, selected := range sel.Entries {
			if !rebased[selected.Name] || alreadyPushed[selected.Name] {
				continue
			}
			entry := internal.GetBranch(stack, selected.Name)
			if entry.Name == "" {
				continue
			}
			probes = append(probes, env.ProbeEntry(pushRepoDir(layout, entry), entry.Name))
		}
	}
	// The preflight is evaluated unconditionally: an envelope whose record
	// exists but could not be read is inactive AND untrusted, and that case
	// must refuse invocation-wide rather than fall through to today's argv.
	// pushScoped has no dry-run branch and gains none.
	if pre := env.PreflightProbes(probes); pre.Refuse {
		// The refusal escapes into `tws sync`'s own error rendering, so it
		// carries §13.2's marker with it: an operator must never see a bare
		// `remote-followup-unsafe-lease:` line with no idea which subsystem
		// refused.
		return internal.AnchorReparentRefusal(pre.Refusal())
	}

	// The §12.5 clearing pass runs in the first repository context this loop
	// actually pushed from; the feature directory is not a Git context.
	clearDir := ""
	for _, selected := range sel.Entries {
		if !rebased[selected.Name] || alreadyPushed[selected.Name] {
			continue
		}
		entry := internal.GetBranch(stack, selected.Name)
		if entry.Name == "" {
			continue
		}
		path := layout.WorktreePath(entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			// Same skip as the legacy loop: an archived entry has no worktree
			// and is never pushed by tws.
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}
		if clearDir == "" {
			clearDir = repoDir
		}
		decision := env.Decision(entry.Name)
		if decision.Applies && decision.WarnLine != "" {
			fmt.Fprintln(os.Stderr, decision.WarnLine) //nolint:errcheck
		}
		if err := internal.RunDirClean(repoDir, "git", pushArgv(decision, entry.GitBranch())...); err != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
			saveScopedPushFailure(layout.FeaturePath, payload, entry.Name)
			return fmt.Errorf("push failed for %s; fix the remote problem, then resume with: tws sync %s --continue", entry.Name, feature)
		}
		fmt.Printf("  [+] %s (pushed)\n", entry.Name)

		// The logical name is recorded only after Git succeeded, and the
		// payload is persisted before the next push is attempted.
		payload.Pushed = append(payload.Pushed, entry.Name)
		if err := internal.SaveSyncRunState(layout.FeaturePath, payload); err != nil {
			return fmt.Errorf("record pushed entry %s: %w", entry.Name, err)
		}
	}
	if env.Active() && clearDir != "" {
		env.WithRepoDir(clearDir).PersistClears(&stack)
	}
	return nil
}

// pushEntries is the legacy push loop of `tws push` and of every no-flag run:
// it prints per-entry failures and returns nil, which is exactly the
// compatibility behaviour a new-mode run must not have.
func pushEntries(feature string, layout externalSyncLayout, entries []internal.StackEntry, dryRun bool) error {
	// Rule R-PUSH loads the record ONCE, before the loop. Without a record the
	// envelope is inert and every byte below is today's.
	env := internal.LoadReparentPushEnvelope(externalReparentLocation(feature, layout), "")
	var probes []internal.ReparentPushEntryProbe
	if env.Active() {
		for _, entry := range entries {
			if _, err := os.Stat(layout.WorktreePath(entry.Name)); os.IsNotExist(err) {
				continue
			}
			probes = append(probes, env.ProbeEntry(pushRepoDir(layout, entry), entry.Name))
		}
	}
	preflight := env.PreflightProbes(probes)
	if preflight.Refuse && !dryRun {
		// The gate is invocation-wide: nothing is pushed at all, and the
		// refusal reaches `tws push`'s generic error printer anchored.
		return internal.AnchorReparentRefusal(preflight.Refusal())
	}
	if preflight.Refuse && dryRun {
		// §12.4a rule 2: in a dry run the same verdict is a diagnostic, never
		// a refusal, and the preview still exits 0.
		fmt.Fprintln(os.Stderr, preflight.DryRunLine()) //nolint:errcheck
	}

	pushed := false
	// The clearing pass of §12.5 must run in a real Git context. The feature
	// directory is not one, so the first materialized entry's own repository
	// context — the very context this loop pushes from — is what carries it.
	clearDir := ""
	for _, entry := range entries {
		path := layout.WorktreePath(entry.Name)

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		decision := env.Decision(entry.Name)
		if decision.Applies && decision.WarnLine != "" {
			fmt.Fprintln(os.Stderr, decision.WarnLine) //nolint:errcheck
		}

		if dryRun {
			// §12.4a rule 1: a pending entry's preview names the argv the real
			// run would use; rule 4 keeps every other entry's exact line and
			// stream. A dry run writes, marks and deletes nothing.
			suffix := "(would push --force-with-lease)"
			if decision.Applies && decision.DryRunSuffix != "" {
				suffix = decision.DryRunSuffix
			}
			fmt.Printf("  [~] %s %s\n", entry.Name, suffix)
			continue
		}

		// Determine repo context
		repoDir := pushRepoDir(layout, entry)
		if clearDir == "" {
			clearDir = repoDir
		}

		runErr := internal.RunDirClean(repoDir, "git", pushArgv(decision, entry.GitBranch())...)
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
			pushed = true
		}
	}
	if pushed && env.Active() && clearDir != "" {
		stack, err := internal.LoadStack(layout.FeaturePath)
		if err == nil {
			env.WithRepoDir(clearDir).PersistClears(&stack)
		}
	}
	return nil
}

// pushRepoDir is the per-entry Git context both external loops already use.
func pushRepoDir(layout externalSyncLayout, entry internal.StackEntry) string {
	if entry.Repo != "" {
		return entry.Repo
	}
	return layout.WorktreePath(entry.Name)
}

// pushArgv materializes rule R-PUSH step 4: the BARE lease, plus
// --force-if-includes for a pending published entry and nothing else. The zero
// decision reproduces the shipped argv exactly.
func pushArgv(d internal.ReparentPushDecision, branch string) []string {
	args := []string{"push", "--force-with-lease"}
	if d.ForceIfIncludes {
		args = append(args, "--force-if-includes")
	}
	return append(args, "origin", branch)
}

// pushFeatureCheckout holds the pre-sync-modes push body verbatim. Checkout
// mode keeps failing with ErrWorktreeUnsupported and a nonzero exit; neither
// the layout resolver nor the GitBranch() ref fix reaches it.
func pushFeatureCheckout(feature string, dryRun bool) error {
	featurePath, err := internal.RequireFeaturePath(feature)
	if err != nil {
		return err
	}

	stack, err := internal.LoadStack(featurePath)
	if err != nil {
		return fmt.Errorf("no stack.yaml found for feature: %s", feature)
	}

	for _, entry := range stack.Branches {
		path, err := internal.RequireWorktreePath(feature, entry.Name)
		if err != nil {
			return err
		}

		// Skip archived branches
		if _, err := os.Stat(path); os.IsNotExist(err) {
			fmt.Printf("  [-] %s (archived, skipped)\n", entry.Name)
			continue
		}

		if dryRun {
			fmt.Printf("  [~] %s (would push --force-with-lease)\n", entry.Name)
			continue
		}

		// Determine repo context
		repoDir := path
		if entry.Repo != "" {
			repoDir = entry.Repo
		}

		runErr := internal.RunDirClean(repoDir, "git", "push", "--force-with-lease", "origin", entry.Name)
		if runErr != nil {
			fmt.Printf("  [x] %s (push failed)\n", entry.Name)
		} else {
			fmt.Printf("  [+] %s (pushed)\n", entry.Name)
		}
	}
	return nil
}

package cli

import (
	"encoding/json"
