// TestReparentE2E_PlanJSONIsTheOnlyStdout is AC-012's stream contract at the
// CLI boundary: the JSON document is exactly one value plus exactly one
// newline on stdout, and every operational byte is on stderr.
func TestReparentE2E_PlanJSONIsTheOnlyStdout(t *testing.T) {
	f := newReparentCustomerExternal(t)
	stdout, _ := f.Plan(f.Feature, "pr2", "--onto", "master", "--no-fetch", "--json")

	if !strings.HasSuffix(stdout, "\n") {
		t.Fatalf("the JSON document must end with exactly one newline:\n%q", stdout)
	}
	if strings.HasSuffix(stdout, "\n\n") {
		t.Fatalf("the JSON document must not end with two newlines:\n%q", stdout)
	}
	var doc map[string]any
	if err := json.Unmarshal([]byte(stdout), &doc); err != nil {
		t.Fatalf("stdout is not exactly one JSON value: %v\n%s", err, stdout)
	}
	if got, ok := doc["schema_version"].(float64); !ok || int(got) != internal.ReparentPlanSchemaVersion {
		t.Fatalf("schema_version = %v, want %d", doc["schema_version"], internal.ReparentPlanSchemaVersion)
	}
	if _, ok := doc["reparent"]; ok {
		t.Fatal("the plan document must not carry a nested reparent key")
	}
}

// reparentIsAncestorOf answers the ancestry question with Git itself.
func reparentIsAncestorOf(t *testing.T, f *reparentFixture, ancestor, descendant string) bool {
	t.Helper()
	out, err := reparentRunAllowFail(f.Repo, "merge-base", "--is-ancestor", ancestor, descendant)
	_ = out
	return err == nil
}

// assertReparentResidueGone is §11.6a's cleanup contract: after a successful
// run nothing of the transaction survives — not the authoritative artifact,
// not the compatibility envelope, not the scratch tree.
func assertReparentResidueGone(t *testing.T, f *reparentFixture) {
	t.Helper()
	loc := f.Loc()
	if internal.HasReparentState(loc) {
		t.Fatalf("the authoritative artifact survived a successful run: %s", internal.ReparentStatePath(loc))
	}
	if f.Mode == internal.ModeExternal {
		if internal.HasSyncState(f.FeaturePath) {
			t.Fatal("the legacy sentinel survived a successful run")
		}
		if internal.HasSyncRunState(f.FeaturePath) {
			t.Fatal("the v4 compatibility payload survived a successful run")
		}
	} else if internal.HasCheckoutTransaction(f.FeaturePath) {
		t.Fatal("the compatibility transaction survived a successful run")
	}
}

// TestReparentE2E_NoRecordedCutoffRefusesThenAcceptsAnExplicitOne exercises
// §5.1's no-recorded-base rung end to end (AC-018). The ladder does NOT guess:
// with `last_base_sha` cleared it refuses `cutoff-absent` and names both
// remedies, and supplying --cutoff makes the identical run succeed.
func TestReparentE2E_NoRecordedCutoffRefusesThenAcceptsAnExplicitOne(t *testing.T) {
	f := newReparentNoCutoffExternal(t)
	if got := f.Entry("pr2").LastBaseSHA; got != "" {
		t.Fatalf("the fixture must clear the recorded cutoff, got %q", got)
	}

	// A plan still PRODUCES a document and exits 0 — exit status is never an
	// admission predicate — but it publishes the blocker and mints no token.
	human, prose := f.Plan(f.Feature, "pr2", "--onto", "master", "--no-fetch", "--max-replay-total", "50")
	if !strings.Contains(human, "cutoff-absent") {
		t.Fatalf("the plan must publish the cutoff-absent blocker:\n%s\n%s", human, prose)
	}
	if !strings.Contains(human, "--cutoff <ref>") {
		t.Fatalf("the blocker must name the explicit-cutoff remedy:\n%s", human)
	}
	if token := reparentApprovalToken(human); reparentFingerprintShape.MatchString(token) {
		t.Fatalf("an unrunnable plan must mint no usable fingerprint, got %q", token)
	}

	// The identical run succeeds once the operator authors the boundary.
	stdout, stderr, exit := reparentExecute(t, f, "pr2", "master", "--no-fetch", "--cutoff", f.B)
	if exit != 0 {
		t.Fatalf("an explicit cutoff must make the run admissible, exit = %d\nstdout:\n%s\nstderr:\n%s", exit, stdout, stderr)
	}
	master := f.SHA("master")
	if !reparentIsAncestorOf(t, f, master, f.SHA("feat-pr2")) {
		t.Fatal("the target must end up on the destination")
	}
	replayed := strings.Fields(f.reparentGit(f.Repo, "rev-list", master+"..feat-pr2"))
	if len(replayed) != 1 {
		t.Fatalf("the operator-authored cutoff must bound the replay to C, got %d: %v", len(replayed), replayed)
	}
	if got := f.Entry("pr2").LastBaseSHA; got != master {
		t.Fatalf("last_base_sha = %q, want the destination tip %s", got, master)
	}
	assertReparentResidueGone(t, f)
}

// TestReparentE2E_StaleDescendantCutoffPausesOnConflict is issue #4's
// stale-cutoff half (AC-021, AC-057). A cutoff older than the destination's own
// rewritten history widens the replay set until it genuinely conflicts, and
// that is a PAUSE, not a refusal: it carries no marker, prints the exact
// resume instructions, and leaves a run an --abort can roll back completely.
func TestReparentE2E_StaleDescendantCutoffPausesOnConflict(t *testing.T) {
	f := newReparentStaleDescendantExternal(t)
	root := f.reparentGit(f.Repo, "rev-list", "--max-parents=0", "HEAD")
	if got := f.Entry("pr2").LastBaseSHA; got != root {
		t.Fatalf("the fixture must record a stale cutoff, got %q", got)
	}
	refsBefore := f.reparentGit(f.Repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads/")

	_, stderr, exit := reparentExecute(t, f, "pr2", "master", "--no-fetch")
	if exit != 1 {
		t.Fatalf("a conflict pause must exit 1, got %d:\n%s", exit, stderr)
	}
	if reparentMarkerRe.MatchString(stderr) {
		t.Fatalf("a conflict is a PAUSE and must carry no reparent marker:\n%s", stderr)
	}
	for _, want := range []string{
		"reparent paused: conflict while computing pr2 (feat-pr2)",
		"resolve in: ",
		"rebase --continue",
		"tws stack reparent " + f.Feature + " --continue",
		"to discard the whole reparent: tws stack reparent " + f.Feature + " --abort",
	} {
		if !strings.Contains(stderr, want) {
			t.Fatalf("the pause must print %q:\n%s", want, stderr)
		}
	}
	if !internal.HasReparentState(f.Loc()) {
		t.Fatal("a paused run must leave a resumable artifact")
	}

	// The rollback is complete: every public ref returns to its pre-image.
	stdout, stderr, exit := f.Run(f.Feature, "--abort")
	if exit != 0 {
		t.Fatalf("--abort exit = %d\nstdout:\n%s\nstderr:\n%s", exit, stdout, stderr)
	}
	if after := f.reparentGit(f.Repo, "for-each-ref", "--format=%(refname) %(objectname)", "refs/heads/"); after != refsBefore {
		t.Fatalf("aborting a paused run must restore every ref:\n--- before ---\n%s\n--- after ---\n%s", refsBefore, after)
	}
	assertReparentResidueGone(t, f)
}

// TestReparentE2E_ReftableBackendIsReportedAndCrashAtomic is the reftable
// variant (AC-060). It SKIPS with a clear reason when the backend is
// unavailable; its files-backend twin — every other cell in this file — is
// mandatory and never skipped, because CI pins no Git version and a
// reftable-only assertion would silently vanish on the older matrix leg.
func TestReparentE2E_ReftableBackendIsReportedAndCrashAtomic(t *testing.T) {
	f := newReparentReftableCheckout(t)
	if f == nil {
		t.Skip("this git cannot create a reftable repository; the files-backend twin covers the same contract")
	}

	human, prose := f.Plan(f.Feature, "pr1", "--onto", "main", "--max-replay-total", "50")
	if !strings.Contains(human, "backend=reftable") {
		t.Fatalf("the plan must report the measured ref backend:\n%s\n%s", human, prose)
	}
	if !strings.Contains(human, "crash-atomic=yes") {
		t.Fatalf("a reftable transaction is crash-atomic and must say so:\n%s", human)
	}

	stdout, stderr, exit := reparentExecute(t, f, "pr1", "main")
	if exit != 0 {
		t.Fatalf("execution exit = %d\nstdout:\n%s\nstderr:\n%s", exit, stdout, stderr)
	}
	main := f.SHA("main")
	for _, branch := range []string{"pr1", "pr2"} {
		if !reparentIsAncestorOf(t, f, main, f.SHA(branch)) {
			t.Fatalf("%s must end up on the destination", branch)
		}
	}
	assertReparentResidueGone(t, f)
}

package cli

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"

	"gopkg.in/yaml.v3"
)

// Acceptance criteria carried by this file's cells: AC-038 (the scope
// refusals), AC-039 and AC-040 (same-parent no-work and the stale-edge
// guidance), AC-068 (the session launch exclusion), AC-079 (sync <-> reparent
// mutual exclusion in both modes), AC-080 (compat-artifact-missing and the
// §11.2a re-creation proofs), AC-083 (the external compat write order).

// ---------------------------------------------------------------------------
// T-027 — dirty / git-operation / holder refusals at the command boundary.
// T-029 — the no-work route.
// T-030 — the same-parent-stale route.
// T-056 — launch exclusion.
// T-067 — sync mutual exclusion on every verb.
// T-068 — the compatibility artifacts.
// T-071 — the compatibility write order and modes.
//
// These cells cover the two directions §11.2 and §14.2a define: a shipped verb
// must never reach a reparent run's compatibility artifacts, and a session must
// never start on top of a run that has detached holders and is about to move
// the very branches the session would sit on.
// ---------------------------------------------------------------------------

// reparentPlantState writes a realistic in-progress artifact for a feature
// without executing anything, so an exclusion cell costs one file write rather
// than a whole transaction. The stage is deliberately mid-run and the owner is
// this live process.
func reparentPlantState(t *testing.T, f *reparentFixture, stage internal.ReparentStage) *internal.ReparentState {
	t.Helper()
	loc := f.Loc()
	st := &internal.ReparentState{
		StateVersion:      internal.ReparentStateVersion,
		RunID:             strings.Repeat("b", 32),
		Feature:           f.Feature,
		TargetName:        "pr2",
		WorkspaceMode:     string(loc.Mode),
		WorkspaceStableID: loc.StableID,
		OwnerPID:          os.Getpid(),
	}
	st.SetStage(stage)
	if err := internal.SaveReparentState(loc, st); err != nil {
		t.Fatalf("planting the artifact: %v", err)
	}
	t.Cleanup(func() { _ = internal.RemoveReparentState(loc) })
	return st
}

// TestReparentExclusion_SyncRefusesEveryVerb is T-067 and AC-079. The
// pre-check sits above mode dispatch, above plan dispatch and above state
// classification, so all four sync routes refuse in BOTH modes — and they
// refuse with the reparent-aware sentence, not with a version or decode error
// about the compatibility files the run deliberately wrote.
func TestReparentExclusion_SyncRefusesEveryVerb(t *testing.T) {
	for _, mode := range []string{"external", "checkout"} {
		t.Run(mode, func(t *testing.T) {
			var f *reparentFixture
			if mode == "external" {
				f = newReparentCustomerExternal(t)
			} else {
				f = newReparentCustomerCheckout(t)
			}
			st := reparentPlantState(t, f, internal.ReparentStageComputing)

			for _, verb := range [][]string{
				{},
				{"--plan"},
				{"--continue"},
				{"--abort"},
			} {
				name := "plain"
				if len(verb) > 0 {
					name = verb[0]
				}
				t.Run(name, func(t *testing.T) {
					args := append([]string{f.Feature}, verb...)
					stdout, stderr := syncCaptureStreams(t, func() {
						if code := syncExecute(syncCmd, args...); code != 1 {
							t.Errorf("exit = %d, want 1", code)
						}
					})
					want := "a stack reparent is in progress for \"" + f.Feature + "\""
					if !strings.Contains(stderr, want) {
						t.Fatalf("stderr must carry the reparent-aware sentence, got:\n%s", stderr)
					}
					if !strings.Contains(stderr, "run "+st.RunID) || !strings.Contains(stderr, "stage "+string(st.Stage)) {
						t.Fatalf("the sentence must name the run and stage, got:\n%s", stderr)
					}
					if !strings.Contains(stderr, "tws stack reparent "+f.Feature+" --continue") {
						t.Fatalf("the sentence must name the recovery verb, got:\n%s", stderr)
					}
					for _, forbidden := range []string{
						"unsupported scoped sync state version",
						"no transaction to continue",
						"no transaction to abort",
					} {
						if strings.Contains(stderr, forbidden) {
							t.Fatalf("a lower-level compatibility error leaked: %q\n%s", forbidden, stderr)
						}
					}
					if stdout != "" {
						t.Fatalf("a refused sync must produce no document, got:\n%s", stdout)
					}
				})
			}
		})
	}
}

// TestReparentExclusion_SyncIsUnaffectedWithoutAnArtifact is AC-099's process
// half at this seam: with no reparent artifact the pre-check adds one os.Stat
// and no Git child, so a plain sync behaves exactly as it always did.
func TestReparentExclusion_SyncIsUnaffectedWithoutAnArtifact(t *testing.T) {
	f := newReparentCustomerExternal(t)
	stdout, stderr := syncCaptureStreams(t, func() {
		_ = syncExecute(syncCmd, f.Feature, "--no-fetch")
	})
	if strings.Contains(stdout+stderr, "a stack reparent is in progress") {
		t.Fatalf("the pre-check must be silent without an artifact:\n%s\n%s", stdout, stderr)
	}
}

// TestReparentExclusion_FreshRouteRefusesAnExistingRun is §11.2's own matrix
// row: on the fresh route ANY artifact refuses, and the refusal names both
// recovery verbs.
// The fresh route refuses a recorded run, a recovery verb refuses without one, and a no-work plan is still a produced plan (AC-039, AC-040, AC-079).
//
// §17.3 counts one t.Run leaf per real-Git cell. These assertions were
// separate leaves; each keeps its own fixture, scope and assertions verbatim
// inside its own closure — only the leaf boundary moved.
func TestReparentExclusion_RouteRefusals(t *testing.T) {
	// --- TestReparentExclusion_FreshRouteRefusesAnExistingRun ---
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		reparentPlantState(t, f, internal.ReparentStageComputing)

		_, stderr, exit := f.Run(f.Feature, "pr2", "--onto", "master", "--no-fetch",
			"--max-replay-total", "5", "--approve-plan", strings.Repeat("a", 64))
		if exit != 1 {
			t.Fatalf("exit = %d, want 1: %s", exit, stderr)
		}
		if !reparentMarkerRe.MatchString(stderr) {
			t.Fatalf("an execution refusal must be one anchored line:\n%s", stderr)
		}
		if !strings.Contains(stderr, "reparent: reparent-state-present: ") {
			t.Fatalf("stderr = %q, want the state-present refusal", stderr)
		}
	}(t)

	// --- TestReparentExclusion_RecoveryVerbsRefuseWithoutARun ---
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		for _, verb := range []string{"--continue", "--abort"} {
			t.Run(verb, func(t *testing.T) {
				_, stderr, exit := f.Run(f.Feature, verb)
				if exit != 1 {
					t.Fatalf("exit = %d, want 1: %s", exit, stderr)
				}
				if !strings.Contains(stderr, "no reparent run is recorded") {
					t.Fatalf("stderr = %q, want the no-run refusal", stderr)
				}
			})
		}
	}(t)

	// --- TestReparentExclusion_NoWorkPlanIsAProducedPlan ---
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		human, prose := f.Plan(f.Feature, "pr2", "--onto", "pr1", "--onto-kind", "entry", "--no-fetch")
		combined := human + prose
		if !strings.Contains(combined, "plannability=no-work") && !strings.Contains(combined, "same-parent") {
			t.Fatalf("reparenting onto the current parent must be a no-work or same-parent plan:\n%s", combined)
		}
		if strings.Contains(human, "fingerprint: ") && reparentFingerprintShape.MatchString(reparentApprovalToken(human)) {
			t.Fatalf("a no-work plan must mint no usable fingerprint:\n%s", human)
		}
	}(t)
}

// TestReparentExclusion_RecoveryVerbsRefuseWithoutARun is the mirror row: a
// recovery verb with nothing recorded refuses rather than inventing a run.

// TestReparentExclusion_CompatArtifactsMakeShippedBinariesFailClosed is T-068
// and T-071. It asserts the WRITE ORDER (§11.2) and the exact fail-closed
// shapes: the external v4 payload is a version a shipped loader rejects, and
// the checkout transaction is deliberately undecodable so AbortCheckoutSync —
// which performs no version check at all — cannot act on it.
func TestReparentExclusion_CompatArtifactsMakeShippedBinariesFailClosed(t *testing.T) {
	t.Run("external", func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		st := reparentPlantState(t, f, internal.ReparentStageComputing)
		if err := internal.WriteReparentCompatArtifacts(f.Loc(), st, []string{"pr2"}); err != nil {
			t.Fatal(err)
		}

		payload, err := os.ReadFile(internal.SyncRunStatePath(f.FeaturePath))
		if err != nil {
			t.Fatalf("the v4 payload must exist: %v", err)
		}
		var probe struct {
			StateVersion int    `yaml:"state_version"`
			Route        string `yaml:"route"`
		}
		if err := yaml.Unmarshal(payload, &probe); err != nil {
			t.Fatal(err)
		}
		if probe.StateVersion != 4 || probe.Route != "reparent" {
			t.Fatalf("payload = version %d route %q, want 4/reparent", probe.StateVersion, probe.Route)
		}
		// A shipped loader must refuse it, which is the whole point.
		if _, loadErr := internal.LoadSyncRunState(f.FeaturePath); loadErr == nil {
			t.Fatal("a shipped LoadSyncRunState must refuse state_version 4")
		}
		if info, statErr := os.Stat(internal.SyncRunStatePath(f.FeaturePath)); statErr != nil || info.Mode().Perm() != 0o600 {
			t.Fatalf("the v4 payload must be 0600, got %v (%v)", info.Mode().Perm(), statErr)
		}
		if info, statErr := os.Stat(internal.SyncStatePath(f.FeaturePath)); statErr != nil || info.Mode().Perm() != 0o644 {
			t.Fatalf("the legacy sentinel must keep its shipped 0644, got %v (%v)", info.Mode().Perm(), statErr)
		}
	})

	t.Run("checkout", func(t *testing.T) {
		f := newReparentCustomerCheckout(t)
		st := reparentPlantState(t, f, internal.ReparentStageComputing)
		if err := internal.WriteReparentCompatArtifacts(f.Loc(), st, []string{"pr2"}); err != nil {
			t.Fatal(err)
		}
		// HasCheckoutTransaction is a bare stat and must still see it.
		if !internal.HasCheckoutTransaction(f.FeaturePath) {
			t.Fatal("a shipped plain sync must still observe the transaction")
		}
		// LoadCheckoutTransaction must FAIL, so both ContinueCheckoutSync and
		// AbortCheckoutSync return before taking the lock or touching Git.
		if _, err := internal.LoadCheckoutTransaction(f.FeaturePath); err == nil {
			t.Fatal("the compatibility transaction must be deliberately undecodable")
		}
		if info, statErr := os.Stat(internal.CheckoutTransactionPath(f.FeaturePath)); statErr != nil || info.Mode().Perm() != 0o600 {
			t.Fatalf("the compatibility transaction must be 0600, got %v (%v)", info.Mode().Perm(), statErr)
		}
	})
}

// TestReparentExclusion_OpenRefusesWhileARunIsRecorded is T-056 / §14.2a's
// external half. `tws open` starts no session and attaches no terminal, and
// the refusal lifts the instant the artifact is gone.
// The launch exclusion, the checkout session preconditions, the runtime-state filters and the scratch's exclusion from every worktree inventory (AC-068, AC-056).
//
// §17.3 counts one t.Run leaf per real-Git cell. These assertions were
// separate leaves; each keeps its own fixture, scope and assertions verbatim
// inside its own closure — only the leaf boundary moved.
func TestReparentExclusion_SessionAndRuntimeState(t *testing.T) {
	// --- TestReparentExclusion_OpenRefusesWhileARunIsRecorded ---
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		reparentPlantState(t, f, internal.ReparentStageComputing)

		_, stderr := syncCaptureStreams(t, func() {
			if code := syncExecute(openCmd, f.Feature, "pr2", "--no-agent"); code != 1 {
				t.Errorf("exit = %d, want 1", code)
			}
		})
		if !strings.Contains(stderr, "a stack reparent is in progress for \""+f.Feature+"\"") {
			t.Fatalf("tws open must refuse with the §11.2 sentence, got:\n%s", stderr)
		}

		// The refusal lifts as soon as the artifact is gone.
		if err := internal.RemoveReparentState(f.Loc()); err != nil {
			t.Fatal(err)
		}
		stdout, stderr := syncCaptureStreams(t, func() {
			if code := syncExecute(openCmd, f.Feature, "pr2", "--no-agent"); code != 0 {
				t.Errorf("exit = %d, want 0 once the artifact is gone (%s)", code, stderr)
			}
		})
		if strings.Contains(stdout+stderr, "a stack reparent is in progress") {
			t.Fatalf("the refusal must lift with the artifact:\n%s\n%s", stdout, stderr)
		}
	}(t)

	// --- TestReparentExclusion_CheckoutSessionPreconditionsRefuse ---
	func(t *testing.T) {
		f := newReparentCustomerCheckout(t)
		ws, err := internal.RequireWorkspace()
		if err != nil {
			t.Fatal(err)
		}
		entry := f.Entry("pr2")

		if err := internal.CheckoutSessionPreconditions(ws, f.Feature, entry); err != nil {
			t.Fatalf("the fixture must be launchable before the artifact exists: %v", err)
		}
		reparentPlantState(t, f, internal.ReparentStageComputing)
		err = internal.CheckoutSessionPreconditions(ws, f.Feature, entry)
		if err == nil {
			t.Fatal("a checkout session must refuse while a reparent is recorded")
		}
		if !strings.Contains(err.Error(), "a stack reparent is in progress") {
			t.Fatalf("refusal = %q, want the §11.2 sentence", err)
		}
		if err := internal.RemoveReparentState(f.Loc()); err != nil {
			t.Fatal(err)
		}
		if err := internal.CheckoutSessionPreconditions(ws, f.Feature, entry); err != nil {
			t.Fatalf("the refusal must lift with the artifact: %v", err)
		}
	}(t)

	// --- TestReparentExclusion_ReparentArtifactsAreRuntimeState ---
	func(t *testing.T) {
		for _, path := range []string{
			".reparent-state.v1.yaml",
			".reparent-remote.v1.yaml",
			".reparent",
			".reparent/abc123/scratch/file.txt",
			"worktrees/x/.reparent/deep",
		} {
			if !isRuntimeState(path) {
				t.Fatalf("%q is reparent runtime state and must be filtered from an import", path)
			}
		}
		for _, path := range []string{
			"stack.yaml",
			"inject/CLAUDE.md",
			"worktrees/api/main.go",
			"my.reparenting/notes.md",
			"reparent-notes.md",
		} {
			if isRuntimeState(path) {
				t.Fatalf("%q is user content and must NOT be filtered", path)
			}
		}
	}(t)

	// --- TestReparentExclusion_ScratchIsExcludedFromWorktreeInventories ---
	func(t *testing.T) {
		f := newReparentCustomerExternal(t)
		scratch := filepath.Join(f.FeaturePath, ".reparent", "run-1", "scratch")
		f.reparentGit(f.Repo, "worktree", "add", "--detach", scratch, "master")

		raw := internal.BuildWorktreeInventory(f.Repo)
		if !raw.Available {
			t.Fatalf("the porcelain parser must stay available: %v", raw.Err)
		}
		found := false
		for _, rec := range raw.Records {
			if strings.Contains(filepath.ToSlash(rec.Path), "/.reparent/") {
				found = true
			}
		}
		if !found {
			t.Fatal("the unfiltered parser must still report the scratch worktree verbatim")
		}

		filtered := internal.ExcludeReparentScratchWorktrees(raw)
		for _, rec := range filtered.Records {
			if strings.Contains(filepath.ToSlash(rec.Path), "/.reparent/") {
				t.Fatalf("the scratch worktree must be excluded from observability inventories: %s", rec.Path)
			}
		}
		if len(filtered.Records) != len(raw.Records)-1 {
			t.Fatalf("exactly one record must be filtered, got %d of %d", len(filtered.Records), len(raw.Records))
		}
	}(t)
}

// TestReparentExclusion_CheckoutSessionPreconditionsRefuse is §14.2a's
// checkout half, asserted at the single insertion point both checkout open
// paths funnel through.

// TestReparentExclusion_NoWorkPlanIsAProducedPlan is T-029: reparenting an
// entry onto the parent it already has is a no-work plan, not a refusal. It
// exits 0, publishes no refusal kind, and mints no fingerprint.

// reparentApprovalToken reads the approval line without failing the test, so a
// negative assertion can be written about its absence.
func reparentApprovalToken(human string) string {
	const prefix = "  fingerprint: "
	for _, line := range strings.Split(human, "\n") {
		if strings.HasPrefix(line, prefix) {
			return strings.TrimSpace(strings.TrimPrefix(line, prefix))
		}
	}
	return ""
}

// TestReparentExclusion_ReparentArtifactsAreRuntimeState is §14.2a's
// import/runtime filter: every `.reparent*` artifact is runtime state that
// must never be recreated by an import, and no user path is filtered by
// accident.

// TestReparentExclusion_ScratchIsExcludedFromWorktreeInventories proves the
// third half of the same filter: a reparent scratch worktree never appears as
// a materialization of a logical branch on an observability surface.

package cli

import (
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strings"
	"testing"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// ---------------------------------------------------------------------------
// safe-reparent-restack — the package-cli fixture ledger (§17.1, exploration
// §7.1).
//
// Go test files compile into the package they declare, so an `internal` test
// can never call a builder declared here and vice versa. The eight §17.1
// shapes are therefore CONCEPTUAL shapes with two package-local realizations;
// this file owns the CLI-level realization, which every end-to-end, customer
// topology, issue-#4, remote, recovery, exclusion and observability cell uses.
//
// Every builder sets GIT_CONFIG_COUNT=0 and GIT_CONFIG_NOSYSTEM=1 through the
// shipped helpers, so a hostile host `git config` can never leak into a
// measurement — which matters most for the cells that deliberately set hostile
// `rebase.*` config of their own.
// ---------------------------------------------------------------------------

// reparentFixture is one CLI-level reparent subject: the repository, the
// feature identity, the resolved feature path, and the SHAs the assertions
// name.
type reparentFixture struct {
	t *testing.T

	Mode        internal.WorkspaceMode
	Repo        string
	Feature     string
	FeaturePath string

	// SHAs the customer topology names. Empty on shapes that do not define
	// them.
	B string // the ORIGINAL, rewritten parent commit — the recorded cutoff
	D string // the destination tip
	C string // the single commit that genuinely belongs to the target
}

// reparentGit runs one git command in the fixture and returns trimmed stdout.
func (f *reparentFixture) reparentGit(dir string, args ...string) string {
	f.t.Helper()
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Env = append(os.Environ(), "GIT_CONFIG_COUNT=0", "GIT_CONFIG_NOSYSTEM=1", "GIT_EDITOR=true", "GIT_SEQUENCE_EDITOR=true")
	out, err := cmd.CombinedOutput()
	if err != nil {
		f.t.Fatalf("git %s: %v\n%s", strings.Join(args, " "), err, out)
	}
	return strings.TrimSpace(string(out))
}

// SHA resolves one ref in the fixture repository.
func (f *reparentFixture) SHA(ref string) string {
	f.t.Helper()
	return f.reparentGit(f.Repo, "rev-parse", ref)
}

// Stack reloads the feature's stack.yaml from disk.
func (f *reparentFixture) Stack() internal.Stack {
	f.t.Helper()
	stack, err := internal.LoadStack(f.FeaturePath)
	if err != nil {
		f.t.Fatalf("load stack: %v", err)
	}
	return stack
}

// Entry returns one logical entry by name.
func (f *reparentFixture) Entry(name string) internal.StackEntry {
	f.t.Helper()
	for _, e := range f.Stack().Branches {
		if e.Name == name {
			return e
		}
	}
	f.t.Fatalf("entry %q is not in stack.yaml", name)
	return internal.StackEntry{}
}

// Loc is the fixture's reparent artifact location.
func (f *reparentFixture) Loc() internal.ReparentLocation {
	f.t.Helper()
	ws, err := internal.RequireWorkspace()
	if err != nil {
		f.t.Fatalf("resolve workspace: %v", err)
	}
	return internal.ReparentLocationFor(ws, f.Feature, f.FeaturePath)
}

// Run drives one `tws stack reparent …` invocation through the production
// command tree and captures both process streams.
func (f *reparentFixture) Run(args ...string) (stdout, stderr string, exit int) {
	f.t.Helper()
	full := append([]string{"reparent"}, args...)
	stdout, stderr = syncCaptureStreams(f.t, func() {
		exit = syncExecute(stackCmd, full...)
	})
	return stdout, stderr, exit
}

// Plan runs the plan route and fails the test when it does not exit 0: §13.3
// makes exit status meaningless as an admission predicate, so a non-zero exit
// on a plan route is always a defect.
func (f *reparentFixture) Plan(args ...string) (stdout, stderr string) {
	f.t.Helper()
	stdout, stderr, exit := f.Run(append(args, "--plan")...)
	if exit != 0 {
		f.t.Fatalf("a produced plan must exit 0, got %d\nstdout:\n%s\nstderr:\n%s", exit, stdout, stderr)
	}
	return stdout, stderr
}

// reparentFingerprintShape is the token's exact syntactic domain, so an
// extractor can never hand a blocker detail or a truncated line to
// --approve-plan.
var reparentFingerprintShape = regexp.MustCompile(`^[0-9a-f]{64}$`)

// reparentFingerprint extracts the approval fingerprint from a human plan by
// reading the `approval` section's own `fingerprint:` line — an anchored,
// prefix-matched extraction, never a `tail -1` pipe, which would silently pick
// up a blocker detail.
func reparentFingerprint(t *testing.T, human string) string {
	t.Helper()
	const prefix = "  fingerprint: "
	for _, line := range strings.Split(human, "\n") {
		if !strings.HasPrefix(line, prefix) {
			continue
		}
		token := strings.TrimSpace(strings.TrimPrefix(line, prefix))
		if reparentFingerprintShape.MatchString(token) {
			return token
		}
	}
	t.Fatalf("the plan minted no usable approval fingerprint:\n%s", human)
	return ""
}

// ---------------------------------------------------------------------------
// Shape 1/2 — the customer topology, extended with a real pr1
// ---------------------------------------------------------------------------

// newReparentCustomerExternal extends setupCustomerTopologyExternal with a
// real `pr1` entry and re-points `pr2` at it, which is what turns the shipped
// sync fixture into a REPARENT subject: `pr2`'s configured parent is now a
// sibling stack entry, and the reparent under test moves it back onto the
// default branch.
//
//	master = A - B' - D     (B rewritten into B'; B is NOT an ancestor of D)
//	pr1    = A - B  - P1
//	pr2    = A - B  - C     (configured parent pr1, recorded cutoff B)
func newReparentCustomerExternal(t *testing.T) *reparentFixture {
	t.Helper()
	reparentCountCLIGitLeaf(t)
	repo, bSHA, dSHA, cSHA := setupCustomerTopologyExternal(t)

	// pr1 forks at the ORIGINAL B, in its own worktree, and adds P1.
	pr1 := internal.WorktreePath("feature", "pr1")
	gitRun(t, repo, "worktree", "add", pr1, "-b", "feat-pr1", bSHA)
	writeAndCommit(t, pr1, "p1.txt", "P1\n", "P1")

	featurePath := internal.FeaturePath("feature")
	if err := internal.SaveStack(featurePath, internal.Stack{Branches: []internal.StackEntry{
		{Name: "pr1", Branch: "feat-pr1", Base: "master", LastBaseSHA: bSHA},
		{Name: "pr2", Branch: "feat-pr2", Base: "pr1", LastBaseSHA: bSHA},
	}}); err != nil {
		t.Fatal(err)
	}
	return &reparentFixture{
		t: t, Mode: internal.ModeExternal, Repo: repo,
		Feature: "feature", FeaturePath: featurePath,
		B: bSHA, D: dSHA, C: cSHA,
	}
}

// newReparentCustomerCheckout is the checkout twin of the shape above.
func newReparentCustomerCheckout(t *testing.T) *reparentFixture {
	t.Helper()
	reparentCountCLIGitLeaf(t)
	dir, featurePath, bSHA, dSHA, cSHA := setupCustomerTopologyCheckout(t)

	// pr1 forks at the ORIGINAL B and adds P1. The checkout is returned to
	// pr2 afterwards, for the default-branch-fallback reason
	// setupCustomerTopologyCheckout documents.
	gitRunCS(t, dir, "checkout", "-b", "pr1", bSHA)
	writeFileCS(t, dir, "p1.txt", "P1\n")
	gitRunCS(t, dir, "add", "p1.txt")
	gitRunCS(t, dir, "commit", "-m", "P1")
	gitRunCS(t, dir, "checkout", "pr2")

	saveTestStack(t, featurePath, []internal.StackEntry{
		{Name: "pr1", Base: "main", LastBaseSHA: bSHA},
		{Name: "pr2", Base: "pr1", LastBaseSHA: bSHA},
	})
	// Every checkout cell drives the PRODUCTION command tree, which resolves
	// its workspace from the current directory. Without this the run would
	// resolve the developer's own repository instead of the fixture.
	withCheckoutEnv(t, dir)
	return &reparentFixture{
		t: t, Mode: internal.ModeCheckout, Repo: dir,
		Feature: "test-feature", FeaturePath: featurePath,
		B: bSHA, D: dSHA, C: cSHA,
	}
}

// ---------------------------------------------------------------------------
// Shape 3/4 — issue #4's branching closure
// ---------------------------------------------------------------------------

// newReparentIssue4External builds issue #4's own stack shape:
//
//	master -> pr1 -> { pr2, pr3 -> pr5 -> pr6, pr4 }
//
// Reparenting pr1 moves a closure that BRANCHES twice and is three deep on one
// arm, which is the shape a linear fixture cannot exercise: it is the only way
// to prove the closure order is deterministic, that a descendant's cutoff is
// snapshotted per row rather than re-derived after its parent moved, and that
// one CAS transaction commits every branch of the fan-out together.
func newReparentIssue4External(t *testing.T) *reparentFixture {
	t.Helper()
	reparentCountCLIGitLeaf(t)
	t.Setenv("GIT_CONFIG_COUNT", "0")
	t.Setenv("GIT_CONFIG_NOSYSTEM", "1")
	repo := setupGitRepo(t, "master")
	withWorkspaceEnv(t, repo)

	masterTip := gitOutput(t, repo, "rev-parse", "HEAD")

	type node struct{ name, parent, base, lastBase string }
	order := []node{
		{"pr1", "", "master", masterTip},
		{"pr2", "pr1", "pr1", ""},
		{"pr3", "pr1", "pr1", ""},
		{"pr4", "pr1", "pr1", ""},
		{"pr5", "pr3", "pr3", ""},
		{"pr6", "pr5", "pr5", ""},
	}
	tips := map[string]string{"": masterTip}
	entries := make([]internal.StackEntry, 0, len(order))
	for i := range order {
		n := &order[i]
		branch := "feat-" + n.name
		wt := internal.WorktreePath("feature", n.name)
		gitRun(t, repo, "worktree", "add", wt, "-b", branch, tips[n.parent])
		writeAndCommit(t, wt, n.name+".txt", n.name+"\n", n.name)
		tips[n.name] = gitOutput(t, wt, "rev-parse", "HEAD")
		if n.lastBase == "" {
			n.lastBase = tips[n.parent]
		}
		entries = append(entries, internal.StackEntry{
			Name: n.name, Branch: branch, Base: n.base, LastBaseSHA: n.lastBase,
		})
	}

	// master advances, so reparenting pr1 onto master has real work to do.
	writeAndCommit(t, repo, "m2.txt", "M2\n", "M2")
	dSHA := gitOutput(t, repo, "rev-parse", "HEAD")
	gitRun(t, repo, "push", "--force", "origin", "master")
	gitRun(t, repo, "fetch", "origin")

	featurePath := internal.FeaturePath("feature")
	if err := os.MkdirAll(featurePath, 0755); err != nil {
		t.Fatal(err)
	}
	if err := internal.SaveStack(featurePath, internal.Stack{Branches: entries}); err != nil {
		t.Fatal(err)
	}
	return &reparentFixture{
