	"T-087": "reparent_source_audit_test.go",
}

// reparentCellRe matches a `T-nnn` citation in a comment.
var reparentCellRe = regexp.MustCompile(`\bT-\d{3}\b`)

// reparentACRe matches an `AC-nnn` citation in a comment.
var reparentACRe = regexp.MustCompile(`\bAC-\d{2,3}\b`)

// reparentSuiteFiles is every test file of this package that participates in
// the reparent matrix. It is derived, not hand-listed, so a new reparent test
// file cannot silently escape the self-checks.
func reparentSuiteFiles(t *testing.T) []string {
	t.Helper()
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, "_test.go") {
			continue
		}
		// The ledger below names every cell by construction; scanning this
		// file too would report every owner as a duplicate of itself.
		if name == "reparent_matrix_test.go" {
			continue
		}
		if strings.HasPrefix(name, "reparent_") ||
			name == "stack_reparent_cli_test.go" ||
			name == "sync_downgrade_test.go" ||
			name == "sync_plan_docs_test.go" {
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

// TestReparentMatrix_EveryCellHasExactlyOneOwner is the bidirectional mapping
// assertion. It is mechanical precisely because the supporting tests cite
// their AC directly and never re-claim a T id that another file owns.
func TestReparentMatrix_EveryCellHasExactlyOneOwner(t *testing.T) {
	claims := map[string][]string{}
	for _, name := range reparentSuiteFiles(t) {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		seen := map[string]bool{}
		for _, cell := range reparentCellRe.FindAllString(string(data), -1) {
			if seen[cell] {
				continue
			}
			seen[cell] = true
			claims[cell] = append(claims[cell], name)
		}
	}

	for cell, files := range claims {
		if len(files) != 1 {
			sort.Strings(files)
			t.Errorf("%s is claimed by %d files (%s); exactly one file may own a cell, supporting tests cite their AC instead",
				cell, len(files), strings.Join(files, ", "))
		}
	}

	for cell, want := range reparentCellOwner {
		files, ok := claims[cell]
		if !ok {
			t.Errorf("%s is declared owned by %s but is cited nowhere", cell, want)
			continue
		}
		if files[0] != want {
			t.Errorf("%s is owned by %s, but the ledger names %s", cell, files[0], want)
		}
	}

	for cell, files := range claims {
		if _, declared := reparentCellOwner[cell]; !declared {
			t.Errorf("%s is cited by %s but is not in the ownership ledger; add it or move the cell to its owning package",
				cell, files[0])
		}
	}
}

// TestReparentMatrix_OwnedCellsCiteAcceptanceCriteria requires every owning
// file to cite at least one AC, so a T cell can never drift into a test that
// asserts nothing the spec asked for.
func TestReparentMatrix_OwnedCellsCiteAcceptanceCriteria(t *testing.T) {
	owners := map[string]bool{}
	for _, file := range reparentCellOwner {
		owners[file] = true
	}
	for file := range owners {
		data, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		if len(reparentACRe.FindAllString(string(data), -1)) == 0 {
			t.Errorf("%s owns at least one matrix cell and must cite at least one AC-nnn", file)
		}
	}
}

// ReparentCLILeafBudget is this package's share of §17.3's 120-leaf total.
// The internal package declares its own share; the sum is asserted below, so
// neither package can quietly spend the other's.
const ReparentCLILeafBudget = 62

// reparentCLILeafNames records the DISTINCT t.Run leaves that built a real
// repository, which is exactly §17.3's unit: "one t.Run leaf that spawns at
// least one git process", with each sub-case of a table counting once. It is
// recorded by the fixtures themselves, so a table sub-case counts even though
// no static scan of call sites could see it.
var (
	reparentCLILeafMu    sync.Mutex
	reparentCLILeafNames = map[string]bool{}
)

func reparentCountCLIGitLeaf(t *testing.T) {
	t.Helper()
	reparentCLILeafMu.Lock()
	reparentCLILeafNames[t.Name()] = true
	reparentCLILeafMu.Unlock()
}

func reparentCLIMeasuredLeaves() int {
	reparentCLILeafMu.Lock()
	defer reparentCLILeafMu.Unlock()
	return len(reparentCLILeafNames)
}

// TestMain asserts the measured budget after the whole package has run.
func TestMain(m *testing.M) {
	code := m.Run()
	if dump := os.Getenv("REPARENT_DUMP_LEAVES_CLI"); dump != "" {
		reparentCLILeafMu.Lock()
		names := make([]string, 0, len(reparentCLILeafNames))
		for n := range reparentCLILeafNames {
			names = append(names, n)
		}
		reparentCLILeafMu.Unlock()
		sort.Strings(names)
		_ = os.WriteFile(dump, []byte(strings.Join(names, "\n")+"\n"), 0o644)
	}
	if used := reparentCLIMeasuredLeaves(); used > ReparentCLILeafBudget {
		fmt.Fprintf(os.Stderr, "reparent: package cli spawned %d real-Git leaves, over its budget of %d\n",
			used, ReparentCLILeafBudget)
		if code == 0 {
			code = 1
		}
	}
	os.Exit(code)
}

// TestReparentMatrix_RealGitLeafBudgetIsSharedAcrossBothPackages is §17.3's
// total. Each package measures its own leaves at runtime and fails its own
// ceiling in TestMain; this assertion pins the two ceilings to the one budget
// the spec sets, so the suite as a whole can never exceed it.
func TestReparentMatrix_RealGitLeafBudgetIsSharedAcrossBothPackages(t *testing.T) {
	const budget = 120
	total := ReparentCLILeafBudget + reparentInternalLeafBudget(t)
	if total > budget {
		t.Fatalf("the declared package budgets sum to %d, over §17.3's %d", total, budget)
	}
	if used := reparentCLIMeasuredLeaves(); used > ReparentCLILeafBudget {
		t.Fatalf("package cli already measured %d leaves, over its share of %d", used, ReparentCLILeafBudget)
	}
	t.Logf("leaf budget: cli<=%d + internal<=%d = %d of %d",
		ReparentCLILeafBudget, total-ReparentCLILeafBudget, total, budget)
}

// reparentInternalLeafBudget reads the sibling package's declared share from
// its own ledger file. A test-only constant is not importable across packages,
// and duplicating the number here would let the two drift apart silently; the
// regex fails loudly if that ledger is renamed or its constant removed.
func reparentInternalLeafBudget(t *testing.T) int {
	t.Helper()
	const ledger = "../reparent_matrix_test.go"
	data, err := os.ReadFile(ledger)
	if err != nil {
		t.Fatalf("the package-internal matrix ledger must exist at %s: %v", ledger, err)
	}
	m := regexp.MustCompile(`(?m)^const ReparentInternalLeafBudget = (\d+)$`).FindStringSubmatch(string(data))
	if m == nil {
		t.Fatalf("%s must declare `const ReparentInternalLeafBudget = <n>`", ledger)
	}
	n, err := strconv.Atoi(m[1])
	if err != nil {
		t.Fatal(err)
	}
	return n
}

// TestReparentMatrix_EveryCellIsOwnedExactlyOnceAcrossBothPackages is the
// GLOBAL ledger. Each package's own self-check proves its half is internally
// consistent; this one reads the sibling package's test sources as DATA and
// proves the union covers T-001..T-087 exactly once, and that every
// AC-001..AC-100 is cited by at least one of them — the bidirectional mapping
// §17.2 requires so the matrix cannot rot.
func TestReparentMatrix_EveryCellIsOwnedExactlyOnceAcrossBothPackages(t *testing.T) {
	claims := map[string][]string{}
	acs := map[string]bool{}
	for _, dir := range []string{".", ".."} {
		entries, err := os.ReadDir(dir)
		if err != nil {
			t.Fatal(err)
		}
		for _, e := range entries {
			name := e.Name()
			if e.IsDir() || !strings.HasSuffix(name, "_test.go") || name == "reparent_matrix_test.go" {
				continue
			}
			data, err := os.ReadFile(filepath.Join(dir, name))
			if err != nil {
				t.Fatal(err)
			}
			label := filepath.Join(dir, name)
			for _, cell := range dedupeStrings(reparentCellRe.FindAllString(string(data), -1)) {
				claims[cell] = append(claims[cell], label)
			}
			for _, ac := range reparentACRe.FindAllString(string(data), -1) {
				acs[normalizeACCitation(ac)] = true
			}
		}
	}

	for i := 1; i <= 87; i++ {
		cell := fmt.Sprintf("T-%03d", i)
		files := claims[cell]
		switch len(files) {
		case 0:
			t.Errorf("%s is cited by no test in either package", cell)
		case 1:
		default:
			sort.Strings(files)
			t.Errorf("%s is claimed by %d files (%s); exactly one file may own a cell",
				cell, len(files), strings.Join(files, ", "))
		}
	}
	for cell, files := range claims {
		n, err := strconv.Atoi(strings.TrimPrefix(cell, "T-"))
		if err != nil || n < 1 || n > 87 {
			t.Errorf("%s (cited by %s) is outside §17.2's closed 87-cell matrix", cell, files[0])
		}
	}
	for i := 1; i <= 100; i++ {
		ac := fmt.Sprintf("AC-%03d", i)
		if !acs[ac] {
			t.Errorf("%s is cited by no test in either package", ac)
		}
	}
}

// normalizeACCitation turns AC-1, AC-01 and AC-001 into one key, so a citation
// written naturally still counts.
func normalizeACCitation(raw string) string {
	n, err := strconv.Atoi(strings.TrimPrefix(raw, "AC-"))
	if err != nil {
		return raw
	}
	return fmt.Sprintf("AC-%03d", n)
}

func dedupeStrings(in []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range in {
		if seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
	}
	return out
}

// TestReparentMatrix_EveryRealGitLeafPinsGitConfigCount is §17.4's hygiene
// rule. A leaf that inherits a hostile host `git config` is not measuring what
// it claims, and T-040 deliberately sets hostile `rebase.*` values of its own.
func TestReparentMatrix_EveryRealGitLeafPinsGitConfigCount(t *testing.T) {
	for _, name := range []string{"reparent_fixtures_test.go"} {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		src := string(data)
		if !strings.Contains(src, `t.Setenv("GIT_CONFIG_COUNT", "0")`) {
			t.Fatalf("%s must pin GIT_CONFIG_COUNT=0 for every fixture it builds", name)
		}
		if !strings.Contains(src, `"GIT_CONFIG_COUNT=0"`) {
			t.Fatalf("%s must scrub GIT_CONFIG_COUNT in every subprocess form too", name)
		}
	}
}

// TestReparentMatrix_FrozenSurfacesStillExist re-asserts the frozen corpus is
// present and unmoved in shape: 126 no-flag artifacts, the sync help snapshot,
// and the two push goldens rule R-PUSH must leave byte-identical.
func TestReparentMatrix_FrozenSurfacesStillExist(t *testing.T) {
	count := 0
	err := filepath.WalkDir("testdata/sync_noflag", func(path string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if !d.IsDir() {
			count++
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	if count != 126 {
		t.Fatalf("the frozen no-flag corpus must hold exactly 126 files, found %d", count)
	}
	for _, rel := range []string{
		"testdata/rebase_plan/sync_help.txt",
		"testdata/sync_noflag/declared_c2/push",
		"testdata/sync_noflag/declared_c2/sync-push",
		"testdata/reparent/stack_help.txt",
		"testdata/reparent/reparent_help.txt",
	} {
		if _, err := os.Stat(rel); err != nil {
			t.Fatalf("the frozen surface %s must exist: %v", rel, err)
		}
	}
}

package cli

import (
	"fmt"
	"io"
	"sort"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

// ---------------------------------------------------------------------------
// §11.10 — the reparent observability line, owned by package cli
//
// While a reparent state artifact exists for a feature, `tws doctor`,
// `tws list`, `tws status` and `tws stack status` write EXACTLY ONE anchored
// line per affected feature on stderr, before any ancestry output is written
// to stdout. The requirement is a command WRITE ORDER, not a claim about how
// two streams interleave on a terminal.
//
// Every one of these surfaces stays strictly read-only: no fetch, no ref
// write, no state repair, and no marking or deletion of the §12.3 remote
// follow-up record. A pending remote record on its own changes NO output on
// any of them.
// ---------------------------------------------------------------------------

// reparentFeaturePathFor resolves the feature directory a reparent artifact
// would live in, using the SAME ladder `tws stack reparent` itself uses:
// ws.ResolveFeaturePath in checkout mode, and the external layout resolver in
// external mode — where a configured workspace root and TWS_ROOT may legitimately
// disagree and only the layout resolver reconciles them. Resolving it any
// other way would make a surface look in a directory the run never wrote to.
func reparentFeaturePathFor(ws internal.Workspace, feature string) (string, error) {
	if ws.Mode == internal.ModeCheckout {
		return ws.ResolveFeaturePath(feature)
	}
	layout, err := resolveExternalSyncLayout(ws, internal.TwsRoot(), feature)
	if err != nil {
		return "", err
	}
	return layout.FeaturePath, nil
}

// writeReparentNoticeFor writes the anchored line for one feature, if and only
// if that feature holds an artifact. It returns true when a line was written,
// so a caller can assert "exactly once".
func writeReparentNoticeFor(w io.Writer, ws internal.Workspace, feature, featurePath string) bool {
	if featurePath == "" {
		resolved, err := reparentFeaturePathFor(ws, feature)
		if err != nil {
			return false
		}
		featurePath = resolved
	}
	p := internal.BuildReparentProjection(internal.ReparentLocationFor(ws, feature, featurePath))
	if p == nil {
		return false
	}
	_, _ = fmt.Fprintln(w, p.ObservabilityLine())
	return true
}

// writeReparentNoticesForAll writes the anchored line for every feature of the
// workspace that holds an artifact, in sorted feature order, exactly once
// each. Resolution failures are skipped in silence: an unresolvable feature is
// already reported by the surface's own ladder.
func writeReparentNoticesForAll(w io.Writer, ws internal.Workspace, features []string) {
	names := make([]string, len(features))
	copy(names, features)
	sort.Strings(names)
	for _, feature := range names {
		featurePath, err := reparentFeaturePathFor(ws, feature)
		if err != nil {
			continue
		}
		writeReparentNoticeFor(w, ws, feature, featurePath)
	}
}

// writeReparentNoticesForWorkspace is the no-argument form used by `tws list`,
// `tws status` and `tws doctor` when they cover every feature.
func writeReparentNoticesForWorkspace(w io.Writer, ws internal.Workspace) {
	features, err := ws.ListFeaturesResolved()
	if err != nil {
		return
	}
	writeReparentNoticesForAll(w, ws, features)
}

// ---------------------------------------------------------------------------
// §14.2a — launch exclusion, external half
//
// The checkout half lives in internal.CheckoutSessionPreconditions, which both
// checkout open paths funnel through. `tws open`'s EXTERNAL arm has no such
// funnel, so it owns its own check — one per arm, each immediately after the
// arm's own GuardFeatureName, so no unguarded path join ever precedes it.
// ---------------------------------------------------------------------------

// refuseOpenDuringReparent refuses `tws open <feature> …` while a reparent
// artifact exists for that feature. It starts no session and attaches no
// terminal, and the refusal lifts the instant the artifact is gone.
func refuseOpenDuringReparent(ws internal.Workspace, feature string) error {
	featurePath, err := reparentFeaturePathFor(ws, feature)
	if err != nil {
		// An unresolvable feature is the arm's own error to report; the
		// exclusion has nothing to say about it.
		return nil
	}
	if !internal.HasReparentState(internal.ReparentLocationFor(ws, feature, featurePath)) {
		return nil
	}
	return internal.ReparentLaunchRefusal(feature)
}

