// TestSyncPlanDocs_PlanningProseSurfacesCarryShippedTargetAndNoFlagLiteral
// ---------------------------------------------------------------------------

// TestSyncPlanDocs_PlanningProseSurfacesCarryShippedTargetAndNoFlagLiteral
// implements spec.md §22.33-ii's two semantic predicates for docs/roadmap.md
// and docs/engineering-workflow.md — the planning-prose surfaces the
// documentation gate deliberately never grep for a flag literal: (1) the
// shipped feature names sit inside the shipped list/paragraph and strictly
// before the current-target sentence (never inside a backlog list or the
// current-target sentence itself), and (2) the NEXT target occupies that
// current-target position. It also asserts the negative half of §22.33-ii's
// own rule: neither file may carry any of the five flag literals.
//
// safe-reparent-restack T-086 / AC-100 retargets both predicates deliberately:
// "safe reparent/restack" has moved from the current target into the shipped
// list, "rebase plan guard" still precedes it there, and the current/next
// target is now "scoped status projection". The negative half is unchanged.
func TestSyncPlanDocs_PlanningProseSurfacesCarryShippedTargetAndNoFlagLiteral(t *testing.T) {
	literals := []string{"--plan", "--max-replay-per-entry", "--max-replay-total", "--approve-plan", "plan-guard:"}

	assertNoFlagLiteral := func(t *testing.T, rel, content string) {
		t.Helper()
		for _, lit := range literals {
			if strings.Contains(content, lit) {
				t.Errorf("%s is planning prose and must never contain the flag literal %q", rel, lit)
			}
		}
	}

	t.Run("docs/roadmap.md", func(t *testing.T) {
		content := readRepoDoc(t, "docs/roadmap.md")
		ci := strings.ToLower(content)

		if n := strings.Count(ci, "rebase plan guard"); n != 1 {
			t.Fatalf(`docs/roadmap.md must name "rebase plan guard" exactly once, found %d`, n)
		}
		guardIdx := strings.Index(ci, "rebase plan guard")
		reparentIdx := strings.Index(ci, "safe reparent/restack")
		targetIdx := strings.Index(ci, "current target:")
		backlogIdx := strings.Index(ci, "p1 stack safety and observability backlog")
		if guardIdx < 0 || reparentIdx < 0 || targetIdx < 0 || backlogIdx < 0 {
			t.Fatalf("docs/roadmap.md is missing one of the required anchors (guard=%d reparent=%d target=%d backlog=%d)", guardIdx, reparentIdx, targetIdx, backlogIdx)
		}
		if guardIdx >= reparentIdx || reparentIdx >= targetIdx || targetIdx >= backlogIdx {
			t.Fatalf("docs/roadmap.md must order: shipped \"rebase plan guard\" (%d) before shipped \"safe reparent/restack\" (%d) before \"Current target:\" (%d) before the P1 backlog heading (%d)", guardIdx, reparentIdx, targetIdx, backlogIdx)
		}

		targetTail := ci[targetIdx : targetIdx+min(80, len(ci)-targetIdx)]
		if !strings.Contains(targetTail, "scoped status projection") {
			t.Fatalf(`docs/roadmap.md's "Current target:" sentence must name "scoped status projection", got: %q`, targetTail)
		}

		assertNoFlagLiteral(t, "docs/roadmap.md", content)
	})

	t.Run("docs/engineering-workflow.md", func(t *testing.T) {
		content := readRepoDoc(t, "docs/engineering-workflow.md")
		ci := strings.ToLower(content)

		if n := strings.Count(ci, "rebase plan guard"); n != 1 {
			t.Fatalf(`docs/engineering-workflow.md must name "rebase plan guard" exactly once, found %d`, n)
		}
		if n := strings.Count(ci, "safe reparent/restack"); n != 1 {
			t.Fatalf(`docs/engineering-workflow.md must name "safe reparent/restack" exactly once, found %d`, n)
		}
		shippedIdx := strings.Index(ci, "current shipped checkout slices")
		guardIdx := strings.Index(ci, "rebase plan guard")
		reparentIdx := strings.Index(ci, "safe reparent/restack")
		nextFeatureIdx := strings.Index(ci, "next roadmap feature:")
		if shippedIdx < 0 || guardIdx < 0 || reparentIdx < 0 || nextFeatureIdx < 0 {
			t.Fatalf("docs/engineering-workflow.md is missing one of the required anchors (shipped=%d guard=%d reparent=%d next=%d)", shippedIdx, guardIdx, reparentIdx, nextFeatureIdx)
		}
		if shippedIdx >= guardIdx || guardIdx >= reparentIdx || reparentIdx >= nextFeatureIdx {
			t.Fatalf("docs/engineering-workflow.md must order: the shipped-slices heading (%d) before \"rebase plan guard\" (%d) before slice 13's \"safe reparent/restack\" (%d) before \"Next roadmap feature:\" (%d)", shippedIdx, guardIdx, reparentIdx, nextFeatureIdx)
		}

		nextTail := ci[nextFeatureIdx : nextFeatureIdx+min(80, len(ci)-nextFeatureIdx)]
		if !strings.Contains(nextTail, "scoped status projection") {
			t.Fatalf(`docs/engineering-workflow.md's "Next roadmap feature:" sentence must name "scoped status projection", got: %q`, nextTail)
		}

		assertNoFlagLiteral(t, "docs/engineering-workflow.md", content)
	})
}

// ---------------------------------------------------------------------------
// TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems
// ---------------------------------------------------------------------------

// changelogUnreleasedBullets splits CHANGELOG.md's "## Unreleased" section
// into its top-level "- " bulleted items, so callers can assert content
// scoped to one bullet rather than the whole section (which would let two
// merged cells masquerade as three).
func changelogUnreleasedBullets(t *testing.T) []string {
	t.Helper()
	content := readRepoDoc(t, "CHANGELOG.md")
	start := strings.Index(content, "## Unreleased")
	if start < 0 {
		t.Fatal("CHANGELOG.md must have an \"## Unreleased\" section")
	}
	rest := content[start:]
	headingRe := regexp.MustCompile(`(?m)^## `)
	headings := headingRe.FindAllStringIndex(rest, -1)
	block := rest
	if len(headings) >= 2 {
		block = rest[:headings[1][0]]
	}
	bulletRe := regexp.MustCompile(`(?m)^- `)
	locs := bulletRe.FindAllStringIndex(block, -1)
	if len(locs) == 0 {
		t.Fatal("no top-level bullets found in CHANGELOG.md's Unreleased section")
	}
	bullets := make([]string, 0, len(locs))
	for i, loc := range locs {
		end := len(block)
		if i+1 < len(locs) {
			end = locs[i+1][0]
		}
		bullets = append(bullets, block[loc[0]:end])
	}
	return bullets
}

// TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems implements
// spec.md §22.33-i-a: the CHANGELOG.md Unreleased entry must disclose all
// three no-flag recovery cells (cell 1, cell 7, cell 4 — sync_recovery_test.go's
// Case1/Case7/Cell4 coverage) as three separate bullets, each carrying its
// own required content. The spec states plainly that "a check that finds
// cell 1 and cell 7 but not cell 4 fails"; this test encodes that literally
// by asserting each cell's disclosure independently, so dropping any one
// cell's content — or merging two cells into one bullet — fails on its own,
// never masked by the other two passing.
func TestSyncPlanDocs_ChangelogRecoveryCellsAreSeparateItems(t *testing.T) {
	full := strings.ToLower(readRepoDoc(t, "CHANGELOG.md"))
	for _, marker := range []string{"recovery cell 1", "recovery cell 7", "recovery cell 4"} {
		if n := strings.Count(full, marker); n != 1 {
			t.Fatalf("CHANGELOG.md must name %q exactly once, found %d", marker, n)
		}
	}

	bullets := changelogUnreleasedBullets(t)
	find := func(marker string) (int, string) {
		for i, b := range bullets {
			if strings.Contains(strings.ToLower(b), marker) {
				return i, b
			}
		}
		t.Fatalf("no CHANGELOG.md bullet in ## Unreleased names %q", marker)
		return -1, ""
	}

	idx1, bullet1 := find("recovery cell 1")
	idx7, bullet7 := find("recovery cell 7")
	idx4, bullet4 := find("recovery cell 4")

	if idx1 == idx7 || idx1 == idx4 || idx7 == idx4 {
		t.Fatalf("recovery cells 1, 7 and 4 must be three separate CHANGELOG bullets; got bullet indices %d, %d, %d", idx1, idx7, idx4)
	}

	n1 := normalizeProse(bullet1)
	if !strings.Contains(n1, "nothing to abort") || !strings.Contains(n1, "no sync in progress") {
		t.Errorf("cell 1 bullet must disclose the previous \"Nothing to abort — no sync in progress.\" wording:\n%s", bullet1)
	}
	if !strings.Contains(n1, "stale sync guard from pid <pid> cleared; no sync state was present.") {
		t.Errorf("cell 1 bullet must quote the new stale-guard message (normalized):\n%s", bullet1)
	}

	n7 := normalizeProse(bullet7)
	if !strings.Contains(n7, "clears both") {
		t.Errorf("cell 7 bullet must disclose that --abort now clears both artefacts:\n%s", bullet7)
	}
	if !strings.Contains(n7, "sync state cleared; stale sync guard from pid <pid> cleared.") {
		t.Errorf("cell 7 bullet must quote the combined-clear message (normalized):\n%s", bullet7)
	}

	n4 := normalizeProse(bullet4)
	if !strings.Contains(n4, "--continue") || !strings.Contains(n4, "--abort") {
		t.Errorf("cell 4 bullet must name both recovery verbs, --continue and --abort:\n%s", bullet4)
	}
	if !strings.Contains(n4, "the interrupted guarded setup's backup of the previous sync state was discarded") {
		t.Errorf("cell 4 bullet must quote the discard sentence (normalized):\n%s", bullet4)
	}
	if !strings.Contains(n4, "refuses the same residue or discards the backup") {
		t.Errorf("cell 4 bullet must disclose the older-release downgrade note:\n%s", bullet4)
	}
}

// TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly pins the
// one attribution §13.6 rule 5's old-binary table makes and the CHANGELOG
// must not blur: the checkout version-comparison sentence
// `checkout sync transaction state version 3 is newer than 2; upgrade tws or
// remove <path>` is the OLD binary's `--continue` answer alone. A FRESH old
// binary run over the same transaction never reaches that comparison — it
// refuses earlier, at HasCheckoutTransaction, with the shipped
// `previous checkout-sync incomplete; use --continue or --abort`.
//
// A CHANGELOG that attributes the version sentence to "fresh/--continue"
// would tell an operator to expect words a fresh run never prints, so the
// two sentences are asserted to be attributed separately here, and the
// version sentence is asserted NOT to be attributed to a fresh run.
func TestSyncPlanDocs_ChangelogCheckoutDowngradeSentenceIsContinueOnly(t *testing.T) {
	const versionSentence = "checkout sync transaction state version 3 is newer than 2; upgrade tws or remove <path>"
	const freshSentence = "previous checkout-sync incomplete; use --continue or --abort"

	full := normalizeProse(readRepoDoc(t, "CHANGELOG.md"))
	if !strings.Contains(full, strings.ToLower(versionSentence)) {
		t.Fatalf("CHANGELOG.md must quote the checkout downgrade sentence %q", versionSentence)
	}

	bullets := changelogUnreleasedBullets(t)
	var owner string
	for _, b := range bullets {
		if strings.Contains(normalizeProse(b), strings.ToLower(versionSentence)) {
			if owner != "" {
				t.Fatalf("the checkout downgrade sentence must live in exactly one Unreleased bullet")
			}
			owner = normalizeProse(b)
		}
	}
	if owner == "" {
		t.Fatal("no ## Unreleased bullet quotes the checkout downgrade sentence")
	}

	// The version sentence must be attributed to --continue...
	idx := strings.Index(owner, strings.ToLower(versionSentence))
	lead := owner[:idx]
	if !strings.Contains(lead, "--continue") {
		t.Errorf("the checkout downgrade sentence must be attributed to --continue:\n%s", owner)
	}
	// ...and never jointly to a fresh run.
	for _, blurred := range []string{"fresh/--continue", "fresh/`--continue`", "fresh or --continue", "--continue/fresh"} {
		if strings.Contains(owner, blurred) {
			t.Errorf("the checkout downgrade sentence must not be attributed to %q: a fresh run never reaches the version comparison:\n%s", blurred, owner)
		}
	}
	// If the fresh cell is mentioned at all, it must carry its OWN sentence.
	if strings.Contains(owner, "fresh") && !strings.Contains(owner, strings.ToLower(freshSentence)) {
		t.Errorf("a bullet that mentions the fresh checkout cell must quote its own sentence %q:\n%s", freshSentence, owner)
	}
}

// ===========================================================================
// §22.34 — the gate suite is declared, runnable and non-vacuous.
// ===========================================================================

// criterion34GateCommands is §22.34's own list, verbatim: the full gate
// suite, in the spec's order.
var criterion34GateCommands = []string{
	"gofmt -l internal cmd",
	"go test ./... -count=1",
	"go vet ./...",
	"golangci-lint run ./...",
	"make build",
	"git diff --check",
	"tpatch feature deps --validate-all",
}

// criterion34FocusedSelectors is §22.34's "focused gates while implementing"
// block: the -run selectors an implementer is told to use. A selector that
// matches no declared test in the corpus is a documentation lie, so each is
// asserted non-vacuous below.
var criterion34FocusedSelectors = []string{
	"TestRebasePlan|TestPlanFingerprint|TestPlanSchema|TestRemainingRebaseEntries",
	"TestSyncPlan|TestPlanGuard|TestSyncNoFlag_",
	"TestSyncScoped_|TestCheckoutSyncModes_",
}

// declaredTestNames parses every `func TestXxx(` declaration under the two
// packages this feature touches, by scanning the source rather than by
// running anything.
func declaredTestNames(t *testing.T) []string {
	t.Helper()
	re := regexp.MustCompile(`(?m)^func (Test[A-Za-z0-9_]*)\(`)
	var names []string
	for _, dir := range []string{"internal", "internal/cli"} {
		entries, err := os.ReadDir(filepath.Join(docsRepoRoot, dir))
		if err != nil {
			t.Fatalf("read %s: %v", dir, err)
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), "_test.go") {
				continue
			}
			data, err := os.ReadFile(filepath.Join(docsRepoRoot, dir, e.Name()))
			if err != nil {
				t.Fatalf("read %s/%s: %v", dir, e.Name(), err)
			}
			for _, m := range re.FindAllStringSubmatch(string(data), -1) {
				names = append(names, m[1])
			}
		}
	}
	if len(names) == 0 {
		t.Fatal("found no declared test functions at all; the scan is broken")
	}
	return names
}

// TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous is
// §22.34's executable owner. The suite itself is run by the outer harness;
// what a test inside the repository can and must own is that every gate the
// criterion names really EXISTS here and that none of its selectors is
// vacuous:
//
//   - `gofmt -l internal cmd` is executed for real and must report nothing;
//   - `make build` names a real Makefile target, and the Makefile also
//     declares the `test` and `lint` targets the suite leans on;
//   - `git diff --check` is executed for real against the working tree;
//   - each focused `-run` selector matches at least one declared test in
//     `internal/` or `internal/cli/`;
//   - the frozen-path gate of criterion 1 still holds: `TestSyncNoFlag_`
//     matches, and the fixture directory still contains exactly 126 files.
//
// A gate command list that drifts from the spec's own block, or a selector
// that stops matching anything, fails here.
func TestSyncPlanDocs_Criterion22_34_GateSuiteIsDeclaredAndNonVacuous(t *testing.T) {
	if len(criterion34GateCommands) != 7 {
		t.Fatalf("§22.34 lists 7 gate commands, this table has %d", len(criterion34GateCommands))
	}

	t.Run("gofmt_reports_nothing", func(t *testing.T) {
		out, err := exec.Command("gofmt", "-l",
			filepath.Join(docsRepoRoot, "internal"), filepath.Join(docsRepoRoot, "cmd")).CombinedOutput()
		if err != nil {
			t.Fatalf("gofmt -l internal cmd: %v\n%s", err, out)
		}
		if strings.TrimSpace(string(out)) != "" {
			t.Fatalf("gofmt -l internal cmd reported unformatted files:\n%s", out)
		}
	})

	t.Run("make_targets_exist", func(t *testing.T) {
		makefile := readRepoDoc(t, "Makefile")
		for _, target := range []string{"build:", "test:", "lint:"} {
			if !regexp.MustCompile(`(?m)^` + regexp.QuoteMeta(target)).MatchString(makefile) {
				t.Fatalf("Makefile declares no %q target, but §22.34's suite invokes it", target)
			}
		}
	})

	t.Run("git_diff_check_is_clean", func(t *testing.T) {
		cmd := exec.Command("git", "diff", "--check")
		cmd.Dir = docsRepoRoot
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git diff --check failed: %v\n%s", err, out)
		}
	})

	t.Run("focused_selectors_are_non_vacuous", func(t *testing.T) {
		names := declaredTestNames(t)
		for _, selector := range criterion34FocusedSelectors {
			re, err := regexp.Compile(selector)
			if err != nil {
				t.Fatalf("selector %q does not compile: %v", selector, err)
			}
			matched := 0
			for _, n := range names {
				if re.MatchString(n) {
					matched++
				}
			}
			if matched == 0 {
				t.Fatalf("focused selector %q matches no declared test: the documented gate is vacuous", selector)
			}
		}
	})

	t.Run("frozen_path_gate_still_holds", func(t *testing.T) {
		names := declaredTestNames(t)
		noflag := 0
		for _, n := range names {
			if strings.HasPrefix(n, "TestSyncNoFlag_") {
				noflag++
			}
		}
		if noflag == 0 {
			t.Fatal("no TestSyncNoFlag_ test is declared; §22 criterion 1's frozen-path gate would be vacuous")
		}
		files := 0
		root := filepath.Join(docsRepoRoot, "internal", "cli", "testdata", "sync_noflag")
		if err := filepath.WalkDir(root, func(_ string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if !d.IsDir() {
				files++
			}
			return nil
		}); err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
		if files != 126 {
			t.Fatalf("internal/cli/testdata/sync_noflag holds %d files, want the frozen 126", files)
		}
	})
}

// ---------------------------------------------------------------------------
// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves
// ---------------------------------------------------------------------------

// bannedDocPhrases are the three substrings spec.md §22.33a forbids: an
// unqualified "--plan mutates nothing" claim, a bare `from` scope-value
// spelling, and a ninth warning kind. None of these are flag literals, so
// they are checked separately from TestSyncPlanDocs_FlagWorkflowSurfacesCarryAllFiveLiterals.
var bannedDocPhrases = []string{"without mutating anything", "scope=from", "nine warning"}

// TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves implements spec.md
// §22.33a's negative check exactly as scoped: "exactly two halves, and no
// third". Half (a) is a corpus grep over README.md, CHANGELOG.md, docs/ and
// assets/ only — never internal/, never cmd/, never a _test.go file, never
// a testdata directory — because tests legitimately contain every banned
// phrase as negative fixtures, so an unscoped grep would forbid the very
// tests that enforce this criterion. Half (b) is the exact tws sync --help
// output, asserted never to contain any of the three phrases as a
// substring.
func TestSyncPlanDocs_NegativeCheckHasExactlyTwoHalves(t *testing.T) {
	t.Run("prose-and-assets", func(t *testing.T) {
		// This walk is built to match the spec's corpus by construction: it
		// only ever reads README.md, CHANGELOG.md and files under docs/ and
		// assets/, and it skips any directory named "testdata" that it
		// encounters. It never touches internal/, cmd/, or any _test.go
		// file — those simply are not among the four roots below.
		roots := []string{
			filepath.Join(docsRepoRoot, "README.md"),
			filepath.Join(docsRepoRoot, "CHANGELOG.md"),
			filepath.Join(docsRepoRoot, "docs"),
			filepath.Join(docsRepoRoot, "assets"),
		}
		var files []string
		for _, root := range roots {
			info, err := os.Stat(root)
			if err != nil {
				t.Fatalf("stat %s: %v", root, err)
			}
			if !info.IsDir() {
				files = append(files, root)
				continue
			}
			if err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
				if err != nil {
					return err
				}
				if d.IsDir() {
					if d.Name() == "testdata" {
						return filepath.SkipDir
					}
					return nil
				}
				files = append(files, path)
				return nil
			}); err != nil {
				t.Fatalf("walking %s: %v", root, err)
			}
		}
		if len(files) < 5 {
			t.Fatalf("corpus walk found only %d files, expected the README, CHANGELOG and docs/+assets/ trees", len(files))
		}

		for _, path := range files {
			data, err := os.ReadFile(path)
			if err != nil {
				t.Fatalf("reading %s: %v", path, err)
			}
			content := string(data)
			for _, phrase := range bannedDocPhrases {
				if strings.Contains(content, phrase) {
					t.Errorf("%s must not contain the banned phrase %q", path, phrase)
				}
			}
		}

		// Positive control: the Go tree legitimately contains a banned
		// phrase as a negative-fixture string (internal/rebase_plan_render_test.go
		// asserts a rendered Policy line never prints "scope=from"). This
		// file is deliberately outside every root above; if it had been
		// included, this exact check would fail — which is the reason
		// spec.md §22.33a scopes the corpus away from the Go tree at all,
		// rather than an assumption this test takes on faith.
		goFixture := filepath.Join("..", "rebase_plan_render_test.go")
		data, err := os.ReadFile(goFixture)
		if err != nil {
			t.Fatalf("reading %s: %v", goFixture, err)
		}
		if !strings.Contains(string(data), "scope=from") {
			t.Fatalf("%s no longer contains the banned literal \"scope=from\" as a negative-fixture string; the corpus-exclusion rationale (spec.md §22.33a) has nothing left to guard against", goFixture)
		}
	})

	t.Run("help-output", func(t *testing.T) {
		stdout, _, exit := runSyncExecute(t, "--help")
		if exit != 0 {
			t.Fatalf("tws sync --help must exit 0, got %d", exit)
		}
		for _, phrase := range bannedDocPhrases {
			if strings.Contains(stdout, phrase) {
				t.Errorf("tws sync --help must not contain the banned phrase %q:\n%s", phrase, stdout)
			}
		}
	})
}

package cli

import (
	"errors"
	"fmt"
	"io"
	"regexp"
	"sort"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

// ---------------------------------------------------------------------------
// sync-plan-guard — the package-cli half of the rebase-plan-guard feature
// (spec §3): the five control flags, their §3.4 validation ladder, the
// external plan-only route (§13.7a), the guarded execution routes, and the
// writer-taking render/marker plumbing (§3.6) shared by both workspace
// modes.
// ---------------------------------------------------------------------------

// planGuardControlFlags is the closed key set of planGuardOptions.Present, in
// the source order of spec §3.1.
var planGuardControlFlags = []string{"plan", "json", "max-replay-per-entry", "max-replay-total", "approve-plan"}

// The six shared validation sentences this file owns. They are hoisted to
// package constants, with no byte changed, so a sibling command that tests
// the identical condition reuses the exact sentence rather than re-typing a
// literal that can drift. Every fmt.Errorf below now formats the constant
// with %s, which produces the same bytes as the literal it replaced and
// leaves every `tws sync` message, help string and golden untouched.
const (
	errMsgJSONRequiresPlan       = "--json requires --plan"
	errMsgPlanWithAbort          = "--plan cannot be combined with --abort"
	errMsgMaxPerEntryNonNegative = "--max-replay-per-entry must be zero or greater"
	errMsgMaxTotalNonNegative    = "--max-replay-total must be zero or greater"
	errMsgApproveTokenShape      = "--approve-plan requires a 64-character lowercase hex fingerprint"
	errMsgApproveRequiresLimits  = "--approve-plan requires --max-replay-per-entry or --max-replay-total"
)

// planGuardOptions is the control-flag envelope resolvePlanGuardOptions
// produces. It is a strict cli-side mirror of internal.CheckoutPlanGuard,
// minus the runtime-only PersistedGuarded field.
type planGuardOptions struct {
	Plan        bool
	JSON        bool
	MaxPerEntry *int // nil == absent; *v == 0 is a real limit
	MaxTotal    *int
	Approve     string
	Present     map[string]bool // "plan","json","max-replay-per-entry","max-replay-total","approve-plan"
}

// Armed reports whether this invocation armed something: at least one limit
// is present, or a token was supplied. It mirrors
// internal.CheckoutPlanGuard.Armed() exactly.
func (o planGuardOptions) Armed() bool {
	return o.MaxPerEntry != nil || o.MaxTotal != nil || o.Approve != ""
}

// checkoutGuard converts to the internal-owned type both executors and the
// plan builder require, so no cli type ever crosses the package boundary
// (§19.1, §19.2). PersistedGuarded always starts false here: only the
// checkout --continue dispatch (checkout_sync.go) and the external guarded
// continuation handlers set it, each from its own persisted-guarded fact.
func (o planGuardOptions) checkoutGuard() internal.CheckoutPlanGuard {
	return internal.CheckoutPlanGuard{
		Plan:        o.Plan,
		JSON:        o.JSON,
		MaxPerEntry: o.MaxPerEntry,
		MaxTotal:    o.MaxTotal,
		Approve:     o.Approve,
		Present:     o.Present,
	}
}

// checkoutGuardPersisted is checkoutGuard with PersistedGuarded set from the
// caller's own persisted-guarded fact — the external continuation handlers'
// own analogue of checkout_sync.go's opts.PlanGuard.PersistedGuarded
// assignment. Without it, EvaluatePlanGuard's own Guarded() gate would be a
// silent no-op on a --continue that re-supplies no limit flag of its own,
// even though the persisted run is already guarded.
func (o planGuardOptions) checkoutGuardPersisted(persisted bool) internal.CheckoutPlanGuard {
	g := o.checkoutGuard()
	g.PersistedGuarded = persisted
	return g
}

// resolvePlanGuardOptions performs the §3.4 incompatibility matrix in its
// exact evaluation order and returns byte-exact messages. It is called once,
// immediately after resolveSyncPolicy and before mode dispatch (§3.3 step 3),
// so both workspace modes reject identically. It reads only the five control
// flags plus cmd.Flags().Changed("continue")/("abort"): no state, no stack,
// no repository.
func resolvePlanGuardOptions(cmd *cobra.Command) (planGuardOptions, error) {
	present := make(map[string]bool, len(planGuardControlFlags))
	for _, name := range planGuardControlFlags {
		present[name] = cmd.Flags().Changed(name)
	}

	opts := planGuardOptions{Present: present}
	opts.Plan, _ = cmd.Flags().GetBool("plan")
	opts.JSON, _ = cmd.Flags().GetBool("json")
	opts.Approve, _ = cmd.Flags().GetString("approve-plan")

	// Row 1: --json requires --plan. Checked unconditionally, first, so a
	// --json --abort invocation (row 6 of the matrix) is refused with this
	// same message rather than the --abort combination message below.
	if present["json"] && !opts.Plan {
		return planGuardOptions{}, fmt.Errorf("%s", errMsgJSONRequiresPlan)
	}

	cont := syncBoolFlag(cmd, "continue")
	abort := syncBoolFlag(cmd, "abort")

	// Rows 2-5: every other control flag is incompatible with --abort.
	if abort {
		switch {
		case present["plan"]:
			return planGuardOptions{}, fmt.Errorf("%s", errMsgPlanWithAbort)
		case present["max-replay-per-entry"]:
			return planGuardOptions{}, fmt.Errorf("--max-replay-per-entry cannot be combined with --abort")
		case present["max-replay-total"]:
			return planGuardOptions{}, fmt.Errorf("--max-replay-total cannot be combined with --abort")
		case present["approve-plan"]:
			return planGuardOptions{}, fmt.Errorf("--approve-plan cannot be combined with --abort")
		}
	}

	// Rows 7-8: a supplied limit must be zero or greater. Row 9 (a
	// non-integer value) is pflag's own parse error and never reaches RunE.
	if present["max-replay-per-entry"] {
		v, _ := cmd.Flags().GetInt("max-replay-per-entry")
		if v < 0 {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgMaxPerEntryNonNegative)
		}
		opts.MaxPerEntry = &v
	}
	if present["max-replay-total"] {
		v, _ := cmd.Flags().GetInt("max-replay-total")
		if v < 0 {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgMaxTotalNonNegative)
		}
		opts.MaxTotal = &v
	}

	// Rows 10-11: --approve-plan's syntactic shape, then its presence-
	// requires-limits rule (never enforced on --continue, regardless of
	// --plan).
	if present["approve-plan"] {
		token := strings.TrimSpace(opts.Approve)
		if !planApproveTokenShape.MatchString(token) {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgApproveTokenShape)
		}
		opts.Approve = token
		if !cont && opts.MaxPerEntry == nil && opts.MaxTotal == nil {
			return planGuardOptions{}, fmt.Errorf("%s", errMsgApproveRequiresLimits)
		}
	}

	return opts, nil
}

// planApproveTokenShape is --approve-plan's exact syntactic domain,
// ^[0-9a-f]{64}$ (spec §3.1 rule 2). BuildRebasePlan itself performs the
// bytewise comparison against the computed fingerprint; this shape check is
// the only validation resolvePlanGuardOptions performs on the token.
var planApproveTokenShape = regexp.MustCompile(`^[0-9a-f]{64}$`)

// ---------------------------------------------------------------------------
// Render/marker/refusal plumbing (spec §3.6)
// ---------------------------------------------------------------------------

// renderPlanDocument is a one-line wrapper passing cmd.OutOrStdout() and
// cmd.ErrOrStderr() to renderPlanDocumentTo.
func renderPlanDocument(cmd *cobra.Command, plan internal.RebasePlan, jsonMode bool) error {
	return renderPlanDocumentTo(cmd.OutOrStdout(), cmd.ErrOrStderr(), plan, jsonMode)
}

// renderPlanDocumentTo is the writer-taking render dispatch: the sole caller
// of FormatRebasePlan/MarshalRebasePlan and the sole binder of document bytes
// to a stream anywhere in the tree. It performs exactly one stdout.Write of
// the complete buffer — no retry, no fallback stream — and returns the
// renderer's error without writing anything when encoding/formatting failed
// (§3.6 row 6). stderr is accepted for signature symmetry with this
// feature's other two-writer helpers; neither renderer emits an operational
// byte for this function to forward, so it is otherwise unused here.
func renderPlanDocumentTo(stdout, stderr io.Writer, plan internal.RebasePlan, jsonMode bool) error {
	_ = stderr
	var buf []byte
	var err error
	if jsonMode {
		buf, err = internal.MarshalRebasePlan(plan)
	} else {
		buf, err = internal.FormatRebasePlan(plan)
	}
	if err != nil {
		return err
	}
	_, err = stdout.Write(buf)
	return err
}

// writePlanGuardMarker prints the anchored guard marker line (§6.4) — the
// ONE format string `plan-guard: %s\n` of e.Error() — and nothing else.
func writePlanGuardMarker(w io.Writer, e *internal.PlanGuardRefusalError) {
	_, _ = fmt.Fprintf(w, "plan-guard: %s\n", e.Error())
}

// planGuardRefusal prints the anchored marker for a guard-owned refusal and
// returns err unchanged. Every other error passes through untouched and
// marker-free, exactly as spec §3.6 rows 4-7, 10 require. It is the single
// wrap point both the external and the checkout RunE dispatch apply to their
// own executing-route return.
func planGuardRefusal(cmd *cobra.Command, err error) error {
	var refusal *internal.PlanGuardRefusalError
	if errors.As(err, &refusal) {
		writePlanGuardMarker(cmd.ErrOrStderr(), refusal)
	}
	return err
}

// ---------------------------------------------------------------------------
// planGuardRun — the executor-side guard carrier (spec §12.2b, §12.3)
// ---------------------------------------------------------------------------

// planGuardRun is the guarded executor's own JIT revalidation state: the
// approved plan's per-entry rows (keyed by name), the effective limits, the
// running replay total THIS invocation has accumulated, and whether state
// has already been preserved by an earlier invocation's own progress. A nil
// *planGuardRun is the unguarded path throughout syncWithStackScoped: every
// JIT seam is itself gated on guard != nil, so a nil guard leaves every
// shipped byte and process untouched.
type planGuardRun struct {
	req            internal.RebasePlanRequest
	approved       map[string]internal.PlanEntry
	limits         internal.PlanGuardLimits
	replayedTotal  int
	statePreserved bool
}

// newPlanGuardRun builds the carrier from the already-built, already-
// evaluated plan. Its limits are the document's OWN plan.Guard.Limits — the
// same reconciled per-entry/total values RevalidatePlanGuardEntry must
// enforce against — never re-resolved a second time from opts/payload.
// statePreserved starts true only for a --continue that reclaimed an
// existing, already-guarded run: a branch may already have moved in a PRIOR
// invocation before this one's own first revalidation ever runs. It starts
// false for a fresh run and flips true after this invocation's own first
// successful revalidate (spec's Long text: "before any branch has moved
// unless that line says state-preserved:").
func newPlanGuardRun(req internal.RebasePlanRequest, plan internal.RebasePlan, statePreserved bool) *planGuardRun {
	approved := make(map[string]internal.PlanEntry, len(plan.Entries))
	for _, e := range plan.Entries {
		approved[e.Name] = e
	}
	limits := internal.PlanGuardLimits{PerEntry: plan.Guard.Limits.MaxReplayPerEntry, Total: plan.Guard.Limits.MaxReplayTotal}
	return &planGuardRun{req: req, approved: approved, limits: limits, statePreserved: statePreserved}
}

// revalidate re-verifies one entry immediately before its rebase runs
// (spec §12.2b/§12.3's JIT seam), through internal.RevalidatePlanGuardEntry
// alone — never internal.RevalidatePlanEntry directly. A name absent from
// the approved plan (never expected on a guarded route, since Remaining is
// always a subset of the approved entries) never blocks: there is nothing
// approved to compare against, so revalidation has nothing to say about it.
// The running replay total accumulates the count the seam FRESHLY resolved,
// never the approved row's own recorded value: an `upstream-deferred` row is
// approved with a null count, so accumulating the approved value would add
// zero for exactly the rows §10.4's deferral policy exists to re-measure and
// would let a run walk past max_replay_total unrefused.
func (g *planGuardRun) revalidate(name string) error {
	if g == nil {
		return nil
	}
	approved, ok := g.approved[name]
	if !ok {
		return nil
	}
	res, err := internal.RevalidatePlanGuardEntry(internal.RevalidatePlanGuardEntryRequest{
		Request:        g.req,
		Approved:       approved,
		Limits:         g.limits,
		ReplayedTotal:  g.replayedTotal,
		StatePreserved: g.statePreserved,
	})
	if err != nil {
		return err
	}
	g.replayedTotal += res.CandidateCount
	g.statePreserved = true
	return nil
}

// planLayout converts the external layout to the internal-owned
// RebasePlanLayout (§9.0): RepoRoot stays "" on the external route, exactly
// as the checkout twin leaves WorktreesRoot "".
func planLayout(l externalSyncLayout) internal.RebasePlanLayout {
	return internal.RebasePlanLayout{FeaturePath: l.FeaturePath, WorktreesRoot: l.WorktreesRoot}
}

// externalWorkspace projects internal.Workspace into the plan's display-only
// PlanWorkspace (§8.3). It re-derives no identity: ws is already this
// invocation's own single RequireWorkspace() result.
func externalWorkspace(ws internal.Workspace) internal.PlanWorkspace {
	var stableID *string
	if ws.StableID != "" {
		id := ws.StableID
		stableID = &id
	}
	return internal.PlanWorkspace{Mode: string(internal.ModeExternal), StableID: stableID, RepoRoot: ws.RepoRoot}
}

// ---------------------------------------------------------------------------
// External plan inspection (spec §13.7a) — the read-only measurement pass
// mirroring internal.InspectCheckoutPlan/CheckoutPlanInspectionRequest
// field-for-field, substituting the external state/selection/stage types.
// ---------------------------------------------------------------------------

// ExternalPlanInspectionRequest bundles InspectExternalPlan's inputs.
type ExternalPlanInspectionRequest struct {
	Feature string
	Layout  externalSyncLayout
	Ws      internal.Workspace
	Opts    planGuardOptions
	Policy  internal.SyncRunPolicy
	NewMode bool
	Push    bool
	Verbose bool
	Changed map[string]bool

	// Continue is this invocation's own --continue flag. It is supplied by
	// the caller (runExternalPlan), which already resolved it identically to
	// the executing dispatch.
	Continue bool

	// PersistedGuarded is the caller's own persisted-guarded fact (§13.6 rule
	// 4d): true whenever a --continue is resuming an already-guarded
	// persisted run (a scoped payload at state_version >= 3, or a guarded
	// legacy sentinel), independent of whether this invocation re-supplies
	// any limit flag of its own. It is never true on a fresh run.
	PersistedGuarded bool

	// Classified is classifySyncState's own already-produced verdict —
	// required, exactly mirroring InspectExternalPlanState's own contract:
	// never recomputed here.
	Classified internal.SyncExternalState

	// Sentinel is the ONE guarded-legacy sentinel view of §13.6 rule 2c,
	// evaluated by the §19.2 dispatch on cell 4 alone and threaded in. It is
	// the zero value (verdict "", i.e. not applicable) on every other cell,
	// which never consults it, and this pipeline never decodes a sentinel of
	// its own. On the cell-4 RECOVERY arm it is the resumed subject: its
	// intent block supplies the universe, the pending set, the effective
	// limits and the frozen validation command (§19.2, §12.8b).
	Sentinel internal.GuardedLegacySentinelView
}

// resumableSentinel is the cell-4 recovery arm's own subject, or nil on
// every other cell: the sentinel this invocation may resume, exactly as
// GuardedLegacySentinelResumable decided it.
func (req ExternalPlanInspectionRequest) resumableSentinel() *internal.GuardedLegacySentinel {
	if req.Classified.Cell != 4 || req.Sentinel.Verdict != internal.SentinelValid {
		return nil
	}
	return req.Sentinel.Sentinel
}

// checkoutGuard combines req.Opts' own control-flag mirror with req's own
// persisted-guarded fact, exactly as planGuardOptions.checkoutGuardPersisted
// does — the single conversion both externalPlanRequest's Guard field and
// buildGuardedExternalPlan's EvaluatePlanGuard call must use, so neither one
// can drift from the other.
func (req ExternalPlanInspectionRequest) checkoutGuard() internal.CheckoutPlanGuard {
	return req.Opts.checkoutGuardPersisted(req.PersistedGuarded)
}

// ExternalPlanInspection is InspectExternalPlan's own result: every fact
// externalPlanRequest needs to construct a RebasePlanRequest without
// re-probing Git state a second time.
type ExternalPlanInspection struct {
	Continue     bool
	Version      internal.GitVersion
	Capabilities internal.GitCapabilities

	State internal.ExternalPlanState

	Stack    internal.Stack
	StackErr error
	Order    []internal.StackEntry
	SortErr  error

	Selection         internal.SyncSelection
	SelectionResolved bool
	SelectionErr      error

	Remaining  []string
	StageFacts []internal.PlanStageFact

	BasePreflight internal.PlanBasePreflight
	FetchPlan     internal.PlanFetchPlan
	Gates         []internal.PlanGateResult

	Limits         internal.PlanGuardLimits
	LimitConflicts []internal.PlanGuardLimitConflict
}

// InspectExternalPlan is the external route's own read-only inspection,
// mirroring internal.InspectCheckoutPlan's ordered pass: version/
// capabilities, state, the fresh-run precondition gates, the reconciled
// guard limits, the stack/order/selection triple, and — continue route only
// — the remaining-entries projection, or — fresh route only — the I14 base
// preflight and the pre-fetch context enumeration.
func InspectExternalPlan(req ExternalPlanInspectionRequest) ExternalPlanInspection {
	var insp ExternalPlanInspection
	insp.Continue = req.Continue
	insp.Capabilities, insp.Version, _ = internal.ProbeGitCapabilities()
	insp.State = internal.InspectExternalPlanState(req.Layout.FeaturePath, internal.ExternalPlanStateOpts{Classified: req.Classified})
	// §16 rules 3a/3b, at their required position: immediately after the
	// version probe, ABOVE this route's own fetch and above every config
	// read. Rule 3b is argv-derived and decided from mode and scope here,
	// before any row is built: only an external UNSCOPED (scope=all) run
	// publishes a pass-1 `--update-refs` argv (§9.3).
	insp.Gates = append(
		internal.CapabilityGates(insp.Version, insp.Capabilities, externalArgvNeedsUpdateRefs(req)),
		externalPreconditionGates(req)...)

	payload := req.Classified.Payload
	sentinel := req.resumableSentinel()
	insp.Limits = resolveExternalGuardLimits(req.Opts, payload, sentinel)
	insp.LimitConflicts = resolveExternalLimitConflicts(payload, sentinel, req.Opts)

	stack, stackErr := internal.LoadStack(req.Layout.FeaturePath)
	if stackErr != nil {
		insp.StackErr = stackErr
		return insp
	}
	insp.Stack = stack

	order, sortErr := internal.TopoSort(stack)
	if sortErr != nil {
		insp.SortErr = sortErr
		return insp
	}
	insp.Order = order

	// A --continue with an existing scoped payload reflects the run's frozen
	// `selected` list (scopedSelectionFromPayloadOrder), exactly as the
	// executing continue routes do, rather than re-deriving scope from this
	// invocation's own flags: syncContinueMismatches only refuses an
	// *explicit* re-specification that disagrees with the payload, so an
	// unspecified flag's default must never silently re-scope the described
	// plan away from what execution will actually select.
	var sel internal.SyncSelection
	var selErr error
	switch {
	case req.Continue && payload != nil:
		sel, selErr = scopedSelectionFromPayloadOrder(stack, order, payload, req.Feature, req.Ws.Mode)
	case req.Continue && sentinel != nil:
		// §19.2's recovery arm: the resumed universe is the sentinel's own
		// intent block — the full-stack legacy selection the interrupted run
		// froze — never this invocation's flags, which the interception has
		// already refused if they carried a trigger.
		sel, selErr = legacySelectionFromOrder(stack, order, req.Policy, req.Feature, req.Ws.Mode)
	default:
		sel, selErr = internal.ResolveSyncSelectionFromOrder(stack, order, req.Policy, internal.SyncSelectionOpts{
			Mode:    internal.ModeExternal,
			NewMode: req.NewMode,
			Feature: req.Feature,
		})
	}
	if selErr != nil {
		insp.SelectionErr = selErr
		return insp
	}
	insp.Selection = sel
	insp.SelectionResolved = true

	route := externalEffectiveRoute(req, payload)
	if sentinel != nil {
		// The recovery arm's remaining set is the sentinel's OWN pending
		// intent (§12.8b, §19.2 step 4), narrowed to the entries the current
		// stack still has: the backup sentinel's `.sync-state.yaml` carries
		// empty pending/completed lists by construction, so the shipped
		// legacy projection would otherwise read "nothing is done" and
		// republish the entire universe.
		insp.Remaining = sentinelRemaining(sentinel, sel)
	} else {
		insp.Remaining = internal.RemainingRebaseEntries(
			route,
			planLayout(req.Layout),
			internal.RemainingEntriesState{Mode: internal.ModeExternal, External: insp.State},
			order, sel,
		)
	}

	if req.Continue {
		insp.StageFacts = externalStageFacts(insp.Remaining)
		return insp
	}

	insp.BasePreflight = externalBasePreflight(req.Layout, stack, sel)

	if req.Policy.Fetch == internal.SyncFetchEnabled {
		insp.FetchPlan = externalFetchPlan(req.Layout, stack, sel, req.NewMode, insp.Capabilities)
	}

	return insp
}

// externalEffectiveRoute derives this invocation's own effective route
// (§13.6 rule 4), mirroring internal's own checkout twin: a --continue of an
// already-persisted payload inherits ITS OWN route (PayloadNewMode, never
// re-derived from req.NewMode, which a continuation invocation need not even
// repeat); a fresh run's route is req.NewMode directly.
// externalArgvNeedsUpdateRefs is §16 rule 3b's argv-derived predicate,
// answered from mode and scope BEFORE any row is built, because the gate
// itself must sit above the fetch: the external pass-1 `scope=all` shapes are
// the only argv this feature ever publishes carrying `--update-refs`
// (`internal/cli/sync_helpers.go`'s unscoped rebase-arg construction, §9.3),
// so a SCOPED run (`--only`/`--from`) and every checkout run never need it.
func externalArgvNeedsUpdateRefs(req ExternalPlanInspectionRequest) bool {
	return !req.Policy.Scoped()
}

func externalEffectiveRoute(req ExternalPlanInspectionRequest, payload *internal.SyncRunState) string {
	if req.Continue && payload != nil {
		if internal.PayloadNewMode(payload) {
			return internal.RouteNewMode
		}
		return internal.RouteLegacy
	}
	if req.NewMode {
		return internal.RouteNewMode
	}
	return internal.RouteLegacy
}

// externalRequestedRoute is RebasePlanRequest.RequestedRoute: "" when the
// command line's own requested route equals the effective route, the
// requested route string otherwise.
func externalRequestedRoute(newMode bool, effective string) string {
	requested := internal.RouteLegacy
	if newMode {
		requested = internal.RouteNewMode
	}
	if requested == effective {
		return ""
	}
	return requested
}

// externalRouteTriggers is RebasePlanRequest.RouteTriggers: sorted Changed
// trigger names, mirroring internal's checkoutRouteTriggers exactly.
func externalRouteTriggers(changed map[string]bool) []string {
	names := make([]string, 0, len(changed))
	for _, name := range syncTriggerFlags {
		if changed[name] {
			names = append(names, name)
		}
	}
	sort.Strings(names)
	return names
}

// externalPreconditionGates evaluates the fresh-run, pre-lock precondition
// this invocation's own shipped executor would check before ever touching
// the filesystem for a run guard (spec §13.7a): syncCellRefusal's own
// verdict for this cell/verb is the single source of it, so this gate is a
// PROJECTION of that shipped ladder, never a second implementation of it. It
// is a silent no-op on --continue, which has already passed it by
// definition.
func externalPreconditionGates(req ExternalPlanInspectionRequest) []internal.PlanGateResult {
	if sentinel := req.resumableSentinel(); sentinel != nil {
		// §12.8b: a VALID guarded backup sentinel never reaches
		// syncCellRefusal, so the gate publishes the sentence the executing
		// twin raises for THIS verb instead of the shipped cell-4 one: the
		// plain-verb preservation sentence, and nothing at all on a
		// continuation, whose own flag validation the continuation gate
		// projects.
		if req.Continue {
			return nil
		}
		return []internal.PlanGateResult{{
			ID: "external-state-refused", Applies: true, Failed: true,
			Kind: internal.RefusalStateRefused,
			Detail: fmt.Sprintf(
				"a guarded sync was interrupted while recording state for %q; the previous sync state is preserved inside %s — use --continue to resume it, or --abort to discard it",
				req.Feature, req.Sentinel.Path),
		}}
	}
	if req.Continue {
		return nil
	}
	err := syncCellRefusal(syncVerbPlain, req.Feature, req.Layout, req.Classified)
	return []internal.PlanGateResult{{
		ID: "external-state-refused", Applies: true, Failed: err != nil,
		Kind:   internal.RefusalStateRefused,
		Detail: syncErrTextOrEmpty(err),
	}}
}

func syncErrTextOrEmpty(err error) string {
	if err == nil {
		return ""
	}
	return err.Error()
}

func externalGatesFailed(gates []internal.PlanGateResult) bool {
	for _, g := range gates {
		if g.Applies && g.Failed {
			return true
		}
	}
	return false
}

// externalBasePreflight is I14, projected: it calls firstUnresolvedSelectedBase
// (sync.go), the shipped verifySelectedBasesLocally's own locator, so the
// document publishes the identical verdict the executing route itself would
// reach — never a second implementation of the locator.
func externalBasePreflight(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) internal.PlanBasePreflight {
	if sel.Policy.Fetch != internal.SyncFetchDisabled {
		return internal.PlanBasePreflight{}
	}
	entry, ref, found := firstUnresolvedSelectedBase(layout, stack, sel)
	if !found {
		return internal.PlanBasePreflight{Applies: true}
	}
	return internal.PlanBasePreflight{
		Applies: true, Failed: true, Entry: entry, Ref: ref,
		Detail: fmt.Sprintf("base %q for stack entry %q does not resolve locally; drop --no-fetch or fetch manually first", ref, entry),
	}
}

// externalStageFacts derives StageFacts for the --continue route: one
// disclosure row per Remaining entry. External's continuation model has no
// per-entry Git-level "stage" the way a checkout transaction does — every
// remaining entry's own next command is always a rebase, since external
// never pauses mid-entry between a completed rebase and a still-pending
// validation/push the way a checkout transaction's Stage can.
func externalStageFacts(remaining []string) []internal.PlanStageFact {
	facts := make([]internal.PlanStageFact, 0, len(remaining))
	for _, name := range remaining {
		autostash := false
		facts = append(facts, internal.PlanStageFact{
			Entry: name, Stage: "planned", NextCommand: "git rebase",
			RebaseIsNext: true, AutostashApplies: &autostash,
		})
	}
	return facts
}

// ---------------------------------------------------------------------------
// Guard-limit reconciliation (external analogue of internal's
// resolveCheckoutGuardLimits/resolveCheckoutLimitConflicts)
// ---------------------------------------------------------------------------

// originLimit mirrors internal's own unexported helper of the same name: the
// unarmed value ({nil, "none"}) whenever v is nil, the supplied origin
// otherwise.
func originLimit(v *int, origin string) internal.PlanGuardLimit {
	if v == nil {
		return internal.PlanGuardLimit{Value: nil, Origin: "none"}
	}
	return internal.PlanGuardLimit{Value: v, Origin: origin}
}

// externalPersistedGuarded mirrors internal's checkoutRecoveryIsGuarded for
// the external payload: guarded exactly at state_version 3.
func externalPersistedGuarded(payload *internal.SyncRunState) bool {
	return payload != nil && payload.StateVersion >= internal.SyncRunStateGuardedVersion
}

// resolveExternalLimit mirrors internal.resolveCheckoutLimit for the
// external route's own persisted carrier, a *internal.SyncRunState rather
// than a *internal.CheckoutTransaction.
func resolveExternalLimit(payload *internal.SyncRunState, guarded bool, persisted, supplied *int) internal.PlanGuardLimit {
	switch {
	case payload == nil:
		return originLimit(supplied, "flags")
	case guarded && persisted != nil:
		return originLimit(persisted, "persisted-transaction")
	case guarded:
		return originLimit(supplied, "flags-persisted-continuation")
	default:
		return originLimit(supplied, "flags-legacy-continuation")
	}
}

func resolveExternalGuardLimits(opts planGuardOptions, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel) internal.PlanGuardLimits {
	if payload == nil && sentinel != nil {
		// §12.8b/§13.2: the cell-4 recovery arm inherits or confirms the
		// sentinel's persisted effective limits, published with the SAME
		// origin an envelope publishes, because the intent block IS the
		// payload the interrupted setup had already committed to. A
		// different supplied value never re-arms the run: it becomes a rank
		// 7 conflict row below, with the persisted value still effective.
		return internal.PlanGuardLimits{
			PerEntry: sentinelLimit(sentinel.MaxReplayPerEntry, opts.MaxPerEntry),
			Total:    sentinelLimit(sentinel.MaxReplayTotal, opts.MaxTotal),
		}
	}
	guarded := externalPersistedGuarded(payload)
	var perEntryPersisted, totalPersisted *int
	if payload != nil {
		perEntryPersisted, totalPersisted = payload.MaxReplayPerEntry, payload.MaxReplayTotal
	}
	return internal.PlanGuardLimits{
		PerEntry: resolveExternalLimit(payload, guarded, perEntryPersisted, opts.MaxPerEntry),
		Total:    resolveExternalLimit(payload, guarded, totalPersisted, opts.MaxTotal),
	}
}

// sentinelLimit is §13.2's per-key table over a sentinel's intent block: a
// persisted value is effective with origin persisted-payload whether this
// invocation confirmed it, supplied a different one (a conflict row, decided
// below) or supplied none at all; an unpersisted key falls back to this
// invocation's own flag.
func sentinelLimit(persisted, supplied *int) internal.PlanGuardLimit {
	if persisted != nil {
		return originLimit(persisted, "persisted-payload")
	}
	return originLimit(supplied, "flags")
}

func externalLimitConflict(key string, persisted *int, persistedOrigin string, supplied *int) *internal.PlanGuardLimitConflict {
	if supplied == nil || persisted == nil || *supplied == *persisted {
		return nil
	}
	return &internal.PlanGuardLimitConflict{Key: key, EffectiveValue: persisted, EffectiveOrigin: persistedOrigin, SuppliedValue: supplied}
}

func resolveExternalLimitConflicts(payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, opts planGuardOptions) []internal.PlanGuardLimitConflict {
	if payload == nil && sentinel != nil {
		var out []internal.PlanGuardLimitConflict
		if c := externalLimitConflict("max_replay_per_entry", sentinel.MaxReplayPerEntry, "persisted-payload", opts.MaxPerEntry); c != nil {
			out = append(out, *c)
		}
		if c := externalLimitConflict("max_replay_total", sentinel.MaxReplayTotal, "persisted-payload", opts.MaxTotal); c != nil {
			out = append(out, *c)
		}
		return out
	}
	if !externalPersistedGuarded(payload) {
		return nil
	}
	var out []internal.PlanGuardLimitConflict
	if c := externalLimitConflict("max_replay_per_entry", payload.MaxReplayPerEntry, "persisted-transaction", opts.MaxPerEntry); c != nil {
		out = append(out, *c)
	}
	if c := externalLimitConflict("max_replay_total", payload.MaxReplayTotal, "persisted-transaction", opts.MaxTotal); c != nil {
		out = append(out, *c)
	}
	return out
}

// externalValidationIdentity is RebasePlanRequest.Validation for the
// external route (§15): external never accepts a --test flag (that flag is
// checkout-only), so its effective command is always config's own
// TestCommand — the fresh route's own frozen-at-birth value, or the
// persisted payload's TestCommand on --continue, mirroring
// handleScopedSyncContinue's/runScopedSync's own "config today, frozen
// henceforth" rule (§7.7).
func externalValidationIdentity(payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, isContinue bool) internal.PlanValidationIdentity {
	command := internal.LoadConfig().TestCommand
	source := "config"
	switch {
	case isContinue && payload != nil:
		command = payload.TestCommand
		source = "persisted-transaction"
	case isContinue && sentinel != nil:
		// §19.2's recovery arm: the frozen validation command is the
		// sentinel's own intent block, never today's config.
		command = sentinel.TestCommand
		source = "persisted-transaction"
	}
	if command == "" {
		return internal.PlanValidationIdentity{Applies: false, Source: "none"}
	}
	return internal.PlanValidationIdentity{Applies: true, Command: command, Source: source, Digest: internal.ValidationDigest(command)}
}

// externalContinuationGate is RebasePlanRequest.ContinuationGate (§13.7a): a
// read-only projection of handleScopedSyncContinue's own dispatch gates,
// never a second implementation of them — the detail sentence comes from
// calling the shipped syncContinueMismatches directly.
func externalContinuationGate(req ExternalPlanInspectionRequest, state internal.ExternalPlanState, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel, stack internal.Stack) internal.PlanContinuationGate {
	policy, changed, push := req.Policy, req.Changed, req.Push
	if payload == nil {
		if !req.Continue {
			return internal.PlanContinuationGate{}
		}
		if sentinel == nil {
			// A continuation with no persisted subject at all: the gate
			// publishes the SHIPPED refusal its executing twin raises, so the
			// rows-less document always names its own cause (§13.7a rule 4).
			// The cell ladder answers first, exactly as the dispatch consults
			// it first; where it stays silent — cells 1 and 7, whose legacy
			// state this route has no payload for — the shipped continuation
			// handler's own sentence is the cause.
			if err := syncCellRefusal(syncVerbContinue, req.Feature, req.Layout, req.Classified); err != nil {
				return internal.PlanContinuationGate{Applies: true, Failed: true, Axis: "state", Detail: err.Error()}
			}
			if !internal.HasSyncState(req.Layout.FeaturePath) {
				return internal.PlanContinuationGate{
					Applies: true, Failed: true, Axis: "state",
					Detail: "nothing to continue — no sync in progress",
				}
			}
			// A `.sync-state.yaml` the classifier decoded but this
			// invocation's own inspector could NOT establish as a resumable
			// subject — a symlinked artefact, one past the read cap, an
			// empty or undecodable document, a non-regular file — leaves the
			// continuation with nothing to filter its remaining work
			// against. RowsAvailable already answers "no" there, so the gate
			// must answer "no" too and say exactly what it saw: a rows-less
			// document that named no cause is the one shape §13.7a rule 4
			// forbids.
			if !externalLegacySubject(state) {
				return internal.PlanContinuationGate{
					Applies: true, Failed: true, Axis: "state",
					Detail: legacySubjectUnavailableDetail(req.Layout, state),
				}
			}
			return internal.PlanContinuationGate{Applies: true}
		}
		// §12.8b: the cell-4 interception owns this document's flag
		// validation, because I20 can no longer see it. The projection
		// raises the SHIPPED I20 sentence its executing twin would raise —
		// composed here, exactly as there, and never a new sentence.
		if syncTriggerFlagSupplied(changed) {
			return internal.PlanContinuationGate{
				Applies: true, Failed: true, Axis: "mismatch", Detail: errSyncModeFlagsNeedV2,
			}
		}
		return internal.PlanContinuationGate{Applies: true}
	}
	if err := syncContinueMismatches(payload, policy, changed, push); err != nil {
		return internal.PlanContinuationGate{Applies: true, Failed: true, Axis: "mismatch", Detail: err.Error()}
	}
	for _, name := range payload.Selected {
		if !internal.HasBranch(stack, name) {
			return internal.PlanContinuationGate{
				Applies: true, Failed: true, Axis: "selection",
				Detail: fmt.Sprintf("selected stack entry %q no longer exists in stack; use --abort", name),
			}
		}
	}
	return internal.PlanContinuationGate{Applies: true}
}

// externalRowsAvailable is RebasePlanRequest.RowsAvailable for this route
// (§13.7a rule 4): the fresh arm needs stack/order/selection resolved; a
// continuation additionally needs a persisted subject to filter its
// remaining work against — the v2/v3 payload of cells 5/7, or the VALID
// guarded-legacy sentinel of the cell-4 recovery arm, whose intent block is
// the payload the interrupted setup had already committed to (§12.8b,
// §19.2). A continuation with neither is the one rows-less continuation
// shape, and its cause is published by the state gate above.
func externalRowsAvailable(insp ExternalPlanInspection, payload *internal.SyncRunState, sentinel *internal.GuardedLegacySentinel) bool {
	resolved := insp.StackErr == nil && insp.SortErr == nil && insp.SelectionErr == nil
	if !resolved {
		return false
	}
	if insp.Continue {
		return payload != nil || sentinel != nil || externalLegacySubject(insp.State)
	}
	return true
}

// legacySubjectUnavailableDetail names, precisely, why the legacy artefact
// beside this continuation is not a resumable subject: the path, the
// presence token this invocation measured, the unreadable reason where the
// presence has one, and the underlying error verbatim where the inspector
// captured one. It invents no verdict — every field is a value
// InspectExternalPlanState already published in state.files — so an operator
// reading blockers[] and state.files sees the same fact twice, never two
// different stories.
func legacySubjectUnavailableDetail(layout externalSyncLayout, state internal.ExternalPlanState) string {
	legacy := state.Files.LegacyState
	path := internal.SyncStatePath(layout.FeaturePath)
	detail := fmt.Sprintf("sync state at %s cannot be resumed: it is %s", path, legacyPresenceWord(legacy))
	if legacy.Err != nil {
		detail += fmt.Sprintf(": %v", legacy.Err)
	}
	return detail + "; inspect it and use --abort to discard it"
}

// legacyPresenceWord renders one presence/reason pair as the phrase the
// detail sentence needs, including the marker case — a backup sentinel this
// invocation could not verify is not a legacy subject either.
func legacyPresenceWord(legacy internal.PlanLegacySyncStateFile) string {
	switch legacy.Presence {
	case internal.PlanPresenceSymlink:
		return "a symlink, not a regular state document"
	case internal.PlanPresenceAbsent:
		return "absent"
	case internal.PlanPresenceNotApplicable:
		return "not applicable to this route"
	case internal.PlanPresenceUnreadable:
		if legacy.UnreadableReason != nil {
			return fmt.Sprintf("unreadable (%s)", *legacy.UnreadableReason)
		}
		return "unreadable"
	default:
		if legacy.MarkerPresent {
			return "an interrupted guarded setup's marker rather than a resumable legacy state"
		}
		return "not a resumable legacy state"
	}
}

// externalLegacySubject reports whether this continuation's subject is a real
// (non-sentinel) legacy `.sync-state.yaml` — the cell-7 arm of §19.2, whose
// resumed subject is the value the classifier already decoded. Its Completed
// list is exactly what RemainingRebaseEntries reads on the legacy route, so
// such a continuation has real remaining rows to publish and is never
// rows-less.
func externalLegacySubject(state internal.ExternalPlanState) bool {
	legacy := state.Files.LegacyState
	return state.Applicable && legacy.Presence == internal.PlanPresenceReadable &&
		legacy.State != nil && !legacy.MarkerPresent
}

// externalFetchPlan enumerates every repo the described route's own fetch
// loop would touch — the whole stack's repos on a legacy route, the
// selection's own repos on a new-mode route — and, per context, its measured
// fetch effect before any fetch runs. It then runs the SAME shared
// suppression ladder internal.checkoutFetchPlan runs
// (internal.ResolveFetchSuppression), so both modes model every §11.2 cause
// with identical row shapes and identical freshness tokens: cause 4
// (fetch-context-indeterminate, reachable here because an external run can
// enumerate several contexts), cause 5 (submodule-reach-indeterminate) and
// cause 6 (local-branch-checked-out). A context whose effect could not be
// established leaves Effect nil, which is disclosure — never a measured
// hazard — but does make a multi-context plan indeterminate, exactly as
// §11.4 requires.
func externalFetchPlan(layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection, newMode bool, caps internal.GitCapabilities) internal.PlanFetchPlan {
	var repos map[string]string
	if newMode {
		sub := internal.Stack{Branches: selectedRealEntries(stack, sel)}
		repos = internal.UniqueRepos(sub, layout.FeaturePath)
	} else {
		repos = internal.UniqueRepos(stack, layout.FeaturePath)
	}
	tokens := make([]string, 0, len(repos))
	for token := range repos {
		tokens = append(tokens, token)
	}
	sort.Strings(tokens)

	plan := internal.PlanFetchPlan{Applies: true}

	// Pass one: establish every context's roots, so the holder inventories
	// below can be built ONCE PER CANONICAL COMMON DIR through
	// internal.BuildPlanHolderIndex — the single holder-index producer — and
	// never once per repo token. Two tokens that are two linked worktrees of
	// one repository share one `git worktree list`.
	type fetchContext struct {
		ctx       internal.PlanFetchContext
		root      string
		commonDir string
		measured  bool
	}
	contexts := make([]fetchContext, 0, len(tokens))
	ids := internal.PlanContextIdentities{}
	need := make([]string, 0, len(tokens))
	for _, token := range tokens {
		root := token
		source := "entry-repo"
		if root == "" {
			root = repos[token]
			source = "worktree"
			if root == "" {
				root = layout.WorktreesRoot
				source = "workspace-repo-root"
			}
		}
		fc := fetchContext{
			ctx: internal.PlanFetchContext{
				RepoToken: token, Root: root, Source: source,
				Candidates: []internal.PlanFetchCandidate{{ContextRoot: root, ContextSource: source}},
			},
			root: root,
		}
		if _, commonDir, err := internal.MeasureContextRoots(root); err == nil {
			fc.ctx.CommonDir = commonDir
			fc.commonDir, fc.measured = commonDir, true
			if _, seen := ids[root]; !seen {
				ids[root] = internal.PlanContextIdentity{ContextID: root, RepoRoot: root, CommonDir: commonDir}
				need = append(need, root)
			}
		}
		contexts = append(contexts, fc)
	}
	holderIndex := internal.BuildPlanHolderIndex(ids, need)

	for _, fc := range contexts {
		if fc.measured {
			// §16 rule 3a: a host below 2.26 cannot produce the ordered
			// inventory at all, so it is never asked for — the capability
			// gate has already refused the document above this point.
			var inv internal.GitConfigInventory
			if caps.CapConfigShowScope {
				inv = internal.ProbeGitConfigInventory(fc.root)
			}
			effect := internal.ResolveFetchEffect(inv, fc.root, fc.commonDir, caps, holderIndex.ByContext[fc.root])
			fc.ctx.Effect = &effect
		}
		plan.Contexts = append(plan.Contexts, fc.ctx)
	}
	sup := internal.ResolveFetchSuppression(plan.Contexts)
	plan.Suppressed, plan.Controlled, plan.Blockers = sup.Suppressed, sup.Controlled, sup.Blockers
	return plan
}

// externalPushFacts is RebasePlanRequest.PushFacts for the external route,
// generalizing internal.checkoutPushFacts (exactly one repo) into N
// contexts, one per repo the selection's own materialized entries touch. It
// is a complete no-op, never touching Git, whenever this invocation does not
// intend to push at all.
func externalPushFacts(push bool, layout externalSyncLayout, stack internal.Stack, sel internal.SyncSelection) internal.PlanPushFacts {
	if !push {
		return internal.PlanPushFacts{}
	}
	sub := internal.Stack{Branches: selectedRealEntries(stack, sel)}
	repos := internal.UniqueRepos(sub, layout.FeaturePath)
	if len(repos) == 0 {
		return internal.PlanPushFacts{}
	}
	tokens := make([]string, 0, len(repos))
	for token := range repos {
		tokens = append(tokens, token)
	}
	sort.Strings(tokens)

	caps, _, _ := internal.ProbeGitCapabilities()
	facts := internal.PlanPushFacts{
		Applies: true, Phase: "plan-point",
		Identities:      internal.PlanContextIdentities{},
		Materialization: map[string]string{},
		Remotes:         map[string]internal.PlanPushRemoteFacts{},
	}
	for _, token := range tokens {
		root := token
		if root == "" {
			root = repos[token]
		}
		if root == "" {
			continue
		}
		// The ONE ordered inventory this push context reads (§14.1a rule 7,
		// §22.27a): ResolvePushContext's remote ladder and the mapping read
		// below both consume this single value, and MeasurePushRemoteFacts
		// never probes again. A host below 2.26 asks for nothing.
		var inv internal.GitConfigInventory
		if caps.CapConfigShowScope {
			inv = internal.ProbeGitConfigInventory(root)
		}
		_, commonDir, measureErr := internal.MeasureContextRoots(root)
		if measureErr != nil {
			continue
		}
		ctx, identity, remoteName, err := internal.ResolvePushContext(root, "workspace-repo-root", "materialized", inv, caps)
		if err != nil {
			continue
		}
		remoteFacts := internal.MeasurePushRemoteFacts(ctx.ContextID, commonDir, remoteName, inv, caps)
		facts.Contexts = append(facts.Contexts, ctx)
		facts.Identities[identity.ContextID] = identity
		facts.Materialization[token] = ctx.Materialization
		facts.Remotes[token] = remoteFacts
	}
	return facts
}

// externalPlanRequest is the shared assembly step runExternalPlan needs:
// every RebasePlanRequest member InspectExternalPlan's own measurement pass
// already settled, mirroring internal.checkoutPlanRequest's own assembly
// field-for-field for the external route.
func externalPlanRequest(req ExternalPlanInspectionRequest, insp ExternalPlanInspection, fetchOutcome internal.PlanFetchOutcome) internal.RebasePlanRequest {
	payload := req.Classified.Payload
	sentinel := req.resumableSentinel()
	route := externalEffectiveRoute(req, payload)
	rowsAvailable := externalRowsAvailable(insp, payload, sentinel)

	var stackPtr *internal.Stack
	if rowsAvailable {
		s := insp.Stack
		stackPtr = &s
	}

	push := req.Push
	pushSource := "flag"
	switch {
	case req.Continue && payload != nil:
		push = payload.Push
		pushSource = "persisted-transaction"
	case req.Continue && sentinel != nil:
		// The recovery arm's intent block is the run's own committed
		// provenance, exactly as a payload is on the envelope arm.
		push = sentinel.Push
		pushSource = "persisted-transaction"
	}

	return internal.RebasePlanRequest{
		Layout:                    planLayout(req.Layout),
		Mode:                      internal.ModeExternal,
		Feature:                   req.Feature,
		Workspace:                 externalWorkspace(req.Ws),
		Route:                     route,
		RequestedRoute:            externalRequestedRoute(req.NewMode, route),
		RouteTriggers:             externalRouteTriggers(req.Changed),
		Invocation:                "plan-only",
		Policy:                    req.Policy,
		PolicyFetchDefaultApplied: !req.Changed["fetch"] && !req.Changed["no-fetch"],
		Push:                      push,
		PushSource:                pushSource,
		Guard:                     req.checkoutGuard(),
		Limits:                    insp.Limits,
		LimitConflicts:            insp.LimitConflicts,
		Validation:                externalValidationIdentity(payload, sentinel, req.Continue),
		Approve:                   req.Opts.Approve,
		Stack:                     stackPtr,
		Order:                     insp.Order,
		SortErr:                   insp.SortErr,
		StackErr:                  insp.StackErr,
		Selection:                 insp.Selection,
		SelectionResolved:         insp.SelectionResolved,
		SelectionErr:              insp.SelectionErr,
		RowsAvailable:             rowsAvailable,
		Continue:                  req.Continue,
		Remaining:                 insp.Remaining,
		StageFacts:                insp.StageFacts,
		Changed:                   req.Changed,
		ContinuationGate:          externalContinuationGate(req, insp.State, payload, sentinel, insp.Stack),
		Fetch:                     fetchOutcome,
		FetchPlan:                 insp.FetchPlan,
		PushFacts:                 internal.RefreshPushTrackingRefs(externalPushFacts(push, req.Layout, insp.Stack, insp.Selection), fetchOutcome),
		BasePreflight:             externalPreflightWithCompletionGate(req, insp, push, rowsAvailable),
		Version:                   insp.Version,
		Capabilities:              insp.Capabilities,
		ExternalState:             insp.State,
		Gates:                     insp.Gates,
	}
}

// externalBasePreflight is insp.BasePreflight, plus the ONE cell §7.1's rank-4
// rule 2 adds for the external completion gate (§13.5, §13.7a rule 15,
// §22.12b (iii)).
//
// The gate `Sync incomplete; stale stack edges remain:` is a POSTCONDITION:
// it runs AFTER the executor's rebases, so on any document that still has a
// rebase row the answer this invocation would give is not yet decided and the
// stale edge is published as the row's own `ancestry` and nothing more. In
// exactly one cell — a ROWS-LESS PUSH-ONLY continuation, where no rebase of
// this invocation can change the answer — the projection is total, and the
// document publishes it as rank 4 `preflight-refused` with the shipped
// sentences byte for byte.
//
// staleStackEdgesFiltered is evaluated in no other cell of this route.
func externalPreflightWithCompletionGate(req ExternalPlanInspectionRequest, insp ExternalPlanInspection, push, rowsAvailable bool) internal.PlanBasePreflight {
	if insp.BasePreflight.Failed || !req.Continue || !push {
		return insp.BasePreflight
	}
	if rowsAvailable && len(insp.Remaining) > 0 {
		return insp.BasePreflight // a rebase row remains: the postcondition is not yet decided
	}
	stale := staleStackEdgesFiltered(req.Layout.WorktreesRoot, insp.Stack, nil)
	if len(stale) == 0 {
		return insp.BasePreflight
	}
	detail := "Sync incomplete; stale stack edges remain:"
	for _, edge := range stale {
		detail += "\n  [!] " + edge
	}
	return internal.PlanBasePreflight{Applies: true, Failed: true, Detail: detail}
}

// externalPlanArgs bundles the measurement inputs both runExternalPlan and
// buildGuardedExternalPlan share, so a guarded execution's own admission
// plan (built to feed internal.EvaluatePlanGuard) and its --plan twin are
// always the product of the identical pipeline.
type externalPlanArgs struct {
	Feature  string
	Layout   externalSyncLayout
	Ws       internal.Workspace
	Policy   internal.SyncRunPolicy
	NewMode  bool
	Push     bool
	Verbose  bool
	Changed  map[string]bool
	Opts     planGuardOptions
	State    internal.SyncExternalState
	Continue bool

	// Sentinel is the §19.2 dispatch's own cell-4 sentinel view, threaded
	// straight into ExternalPlanInspectionRequest.Sentinel. It is the zero
	// value everywhere else.
	Sentinel internal.GuardedLegacySentinelView

	// PersistedGuarded is threaded straight into
	// ExternalPlanInspectionRequest.PersistedGuarded (§13.6 rule 4d). It is
	// false on every fresh route and on the plan-only route's own
	// measurement (a --plan never adjudicates; it only describes), and true
	// only when a guarded executor is resuming an already-guarded persisted
	// run.
	PersistedGuarded bool
}

// buildExternalPlan runs InspectExternalPlan, fetches wherever the described
// route's own policy would (writing every prose/child byte to prose, which
// callers already route to cmd.ErrOrStderr() on the plan-only route or to
// the shipped stdout/stderr pair on a guarded execution's own admission
// pass), and returns the fully built document. It never renders and never
// evaluates the guard: both are the caller's own responsibility.
func externalPlanInspectionRequest(args externalPlanArgs) ExternalPlanInspectionRequest {
	return ExternalPlanInspectionRequest{
		Feature: args.Feature, Layout: args.Layout, Ws: args.Ws, Opts: args.Opts, Policy: args.Policy,
		NewMode: args.NewMode, Push: args.Push, Verbose: args.Verbose, Changed: args.Changed,
		Continue: args.Continue, Classified: args.State, PersistedGuarded: args.PersistedGuarded,
		Sentinel: args.Sentinel,
	}
}

// inspectExternalPlanFor is the ONE InspectExternalPlan call an invocation
// makes (§10.7 rule 1a, §16.1): every consumer below — the shipped I14
// refusal composer, the guard seam, the document build and the executor —
// reads the value it returns instead of re-probing. It is the reason a
// guarded route's own prelude no longer re-loads the stack or re-sorts it.
func inspectExternalPlanFor(args externalPlanArgs) ExternalPlanInspection {
	return InspectExternalPlan(externalPlanInspectionRequest(args))
}

// buildExternalPlanFrom performs the fetch (where the described route
// fetches) and the document build over an ALREADY-produced inspection, so
// no caller inspects twice.
func buildExternalPlanFrom(args externalPlanArgs, insp ExternalPlanInspection, prose io.Writer) (internal.RebasePlan, internal.RebasePlanRequest, error) {
	req := externalPlanInspectionRequest(args)

	var fetchOutcome internal.PlanFetchOutcome
	if !args.Continue && args.Policy.Fetch == internal.SyncFetchEnabled && insp.FetchPlan.Applies &&
		len(insp.FetchPlan.Blockers) == 0 && externalRowsAvailable(insp, args.State.Payload, req.resumableSentinel()) &&
		!externalGatesFailed(insp.Gates) && !insp.BasePreflight.Failed {
		if args.NewMode {
			fetchOutcome = fetchScopedReposTo(prose, prose, args.Layout, insp.Stack, insp.Selection, args.Verbose, insp.FetchPlan)
		} else {
			fetchOutcome = fetchStackReposTo(prose, prose, args.Layout, insp.Stack, args.Verbose, insp.FetchPlan)
		}
	}

	planReq := externalPlanRequest(req, insp, fetchOutcome)
	plan, err := internal.BuildRebasePlan(planReq)
	return plan, planReq, err
}

// buildExternalPlan is the plan-only route's one-shot inspect-then-build.
func buildExternalPlan(args externalPlanArgs, prose io.Writer) (internal.RebasePlan, internal.RebasePlanRequest, ExternalPlanInspection, error) {
	insp := inspectExternalPlanFor(args)
	plan, planReq, err := buildExternalPlanFrom(args, insp, prose)
	return plan, planReq, insp, err
}

// runExternalPlan is the external route's plan-only dispatch (spec §13.7a):
// it never mutates, describes either the fresh or the --continue route
// depending on cont, and fetches wherever that described route's own policy
// would fetch — writing every fetch/prose byte to cmd.ErrOrStderr(), never
// cmd.OutOrStdout(), so stdout carries the document alone.
func runExternalPlan(cmd *cobra.Command, feature string, layout externalSyncLayout, ws internal.Workspace, policy internal.SyncRunPolicy, newMode, push, verbose bool, changed map[string]bool, opts planGuardOptions, state internal.SyncExternalState, cont bool) error {
	prose := cmd.ErrOrStderr()
	printSyncModeHeaderTo(prose, policy)

	plan, _, _, err := buildExternalPlan(externalPlanArgs{
		Feature: feature, Layout: layout, Ws: ws, Policy: policy, NewMode: newMode,
		Push: push, Verbose: verbose, Changed: changed, Opts: opts, State: state, Continue: cont,
		Sentinel: externalPlanSentinelView(layout, feature, state),
	}, prose)
	if err != nil {
		return err
	}
	return renderPlanDocument(cmd, plan, opts.JSON)
}

// externalPlanSentinelView is the plan route's own ONE read of the §13.6
// rule 2c sentinel view, taken only on cell 4 — the single cell §19.2 lets
// anything consult it — so a --plan describes the same subject its executing
// twin would resume. It adjudicates nothing: the value is threaded into the
// inspection exactly as the executing dispatch threads its own already-read
// view, and no other cell reads a sentinel at all.
func externalPlanSentinelView(layout externalSyncLayout, feature string, state internal.SyncExternalState) internal.GuardedLegacySentinelView {
	if state.Cell != 4 {
		return internal.GuardedLegacySentinelView{}
	}
	return internal.InspectGuardedLegacySentinel(layout.FeaturePath, feature)
}

// buildGuardedExternalPlan is a guarded execution's own pre-mutation
// admission pass (spec §4.6, §7): the identical InspectExternalPlan +
// externalPlanRequest + BuildRebasePlan pipeline runExternalPlan itself
// uses, so a guarded execution is refused by exactly the verdict its own
// --plan twin would report, followed by internal.EvaluatePlanGuard's own
// admission predicate. Unlike the plan-only route it writes its prose
// straight to the shipped stdout/stderr pair (out/errw), since a guarded
// execution that passes admission goes on to print the identical shipped
// bytes an unguarded run would. The returned RebasePlanRequest is
// newPlanGuardRun's own frozen-at-birth request: a guarded executor never
// rebuilds it a second time.
func buildGuardedExternalPlan(out, errw io.Writer, args externalPlanArgs, insp ExternalPlanInspection) (internal.RebasePlan, internal.RebasePlanRequest, error) {
	plan, planReq, err := buildExternalPlanFrom(args, insp, errw)
	if err != nil {
		return internal.RebasePlan{}, planReq, err
	}
	if err := syncSnapshotBarrier(args.Layout.FeaturePath); err != nil {
		return plan, planReq, err
	}
	if err := internal.EvaluatePlanGuard(plan, args.Opts.checkoutGuardPersisted(args.PersistedGuarded)); err != nil {
		return plan, planReq, err
	}
	return plan, planReq, nil
}

// legacySelectionFromOrder is the FULL-STACK legacy universe of §13.3: every
// entry of the current stack, in this invocation's one TopoSort order. It is
// the selection the cell-4 recovery arm resumes, because a legacy run never
// narrowed its universe in the first place — the shipped legacy executor
// selects every name — and the sentinel's own intent block is a full-stack
// universe by construction (§13.6 rule 2c).
func legacySelectionFromOrder(stack internal.Stack, order []internal.StackEntry, policy internal.SyncRunPolicy, feature string, mode internal.WorkspaceMode) (internal.SyncSelection, error) {
	return internal.ResolveSyncSelectionFromOrder(stack, order, policy, internal.SyncSelectionOpts{
		Mode:    mode,
		NewMode: false,
		Feature: feature,
	})
}

// sentinelRemaining projects the cell-4 recovery arm's remaining work: the
// sentinel's own PendingIntent, in the selection's execution order, keeping
// only names the current stack still carries. A name the operator removed
// from stack.yaml between the crash and the resume is silently absent from
// the remaining set — it is not a rebase this invocation can perform — and
// is never invented back into the plan.
func sentinelRemaining(sentinel *internal.GuardedLegacySentinel, sel internal.SyncSelection) []string {
	pending := make(map[string]bool, len(sentinel.PendingIntent))
	for _, name := range sentinel.PendingIntent {
		pending[name] = true
	}
	out := make([]string, 0, len(sentinel.PendingIntent))
	for _, e := range sel.Entries {
		if pending[e.Name] {
			out = append(out, e.Name)
		}
	}
	return out
}

package internal

import (
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

// ============================================================================
// GitVersion and the locked §16 rule 2 parser
// ============================================================================

// GitVersion is the locked §16 rule 2 probe result. Probed is always true
// once ProbeGitVersion has run — the act of asking is itself the fact — and
// OK is true only when a version could be parsed from the first line of
// `git --version`. Raw is that first line, verbatim, kept so a rank 5.9
// probe-failed detail can quote exactly what the host printed even when
// parsing fails.
type GitVersion struct {
	Probed bool
	OK     bool
	Raw    string
	Major  int
	Minor  int
	Patch  int
}

// gitVersionPattern is the locked parser. Git's own first line has always
// been "git version X.Y[.Z]" followed by an arbitrary packager suffix on the
// same line — "git version 2.39.5 (Apple Git-154)", "2.30.1.windows.1", a
// Debian/Homebrew build tag, or nothing at all. Only the leading numeric
// major.minor[.patch] token is consumed; anything after it is intentionally
// left unmatched rather than rejected, so a real host is never misclassified
// as unparseable merely because its packager appended free text.
var gitVersionPattern = regexp.MustCompile(`^git version (\d+)\.(\d+)(?:\.(\d+))?`)

// ProbeGitVersion runs `git --version` once and applies the locked parser to
// its first line. An exec failure or an unparseable first line both yield
// Probed: true, OK: false, every Major/Minor/Patch left at zero — the caller
// (§16 rule 1) is the one that raises the document-level rank 5.9
// probe-failed blocker and treats every capability gate as unknown; this
// function only reports what it observed and never performs that
// classification itself.
func ProbeGitVersion() (GitVersion, error) {
	out, err := exec.Command("git", "--version").Output()
	if err != nil {
		return GitVersion{Probed: true, OK: false}, err
	}

	text := string(out)
	if idx := strings.IndexByte(text, '\n'); idx >= 0 {
		text = text[:idx]
	}
	raw := strings.TrimRight(text, "\r")

	v := GitVersion{Probed: true, Raw: raw}
	m := gitVersionPattern.FindStringSubmatch(raw)
	if m == nil {
		return v, nil
	}

	major, majErr := strconv.Atoi(m[1])
	minor, minErr := strconv.Atoi(m[2])
	if majErr != nil || minErr != nil {
		// Unreachable for the pattern's own \d+ groups, but guarded anyway so
		// a malformed match can never silently masquerade as OK: true.
		return v, nil
	}
	patch := 0
	if m[3] != "" {
		if p, patchErr := strconv.Atoi(m[3]); patchErr == nil {
			patch = p
		}
	}

	v.OK = true
	v.Major = major
	v.Minor = minor
	v.Patch = patch
	return v, nil
}

// ============================================================================
// GitCapabilities — the closed §16 rule 3 six-gate table
// ============================================================================

// GitCapabilities is the closed §16 rule 3 six-gate table, one bool per gate,
// each named for the Git version at which this feature's own behaviour
// changes. An unknown GitVersion (Probed && !OK) yields every gate false via
// GitCapabilitiesForVersion; a caller MUST read that as "unknown", never as
// "absent on this host" — §16 rule 1 already raises the document-level rank
// 5.9 probe-failed blocker in that case, so no gate here is ever consulted
// for a real decision once that blocker has fired.
type GitCapabilities struct {
	// CapPruneTags is `fetch --prune-tags`, Git >= 2.17.
	CapPruneTags bool

	// CapConfigShowScope is `git config --list --show-scope`, Git >= 2.26.
	// Below this gate — or with an unknown version — the plan/guard route
	// cannot tell a key's scope apart from its value at all, so it refuses
	// with rank 5.9 probe-failed rather than publish a scope-less inventory
	// as though it were scoped, and rather than silently drop
	// config_issues[].source (§11.7).
	CapConfigShowScope bool

	// CapDefaultBackendMerge is Git >= 2.26, the version at which
	// rebase.backend — and the merge-backed default effective_backend row 3-5
	// model when it is set or absent — first exists. Kept as its own field,
	// never collapsed with CapConfigShowScope even though both gate at 2.26,
	// because the two have opposite consequences: one refuses the
	// invocation outright, the other only changes how an older host's
	// built-in apply-backend default is modelled (§16 rule 3a).
	CapDefaultBackendMerge bool

	// CapSoleRemoteFallback is Git's own "exactly one configured remote"
	// rung of the remote-resolution ladder (§11.4), Git >= 2.37.
	CapSoleRemoteFallback bool

	// CapRebaseUpdateRefs is `git rebase --update-refs`, Git >= 2.38. Its
	// predicate is argv-derived (§16 rule 3b): a row is gated on it only
	// where the argv THAT ROW publishes actually carries --update-refs, so a
	// host below this gate cannot run that specific argv at all and the
	// controlled route refuses with rank 5.9 probe-failed above any
	// effective_backend classification of it.
	CapRebaseUpdateRefs bool

	// CapFetchAll is `fetch.all`, Git >= 2.44.
	CapFetchAll bool
}

// atLeast reports whether v is a known version at or above major.minor.
// Patch is deliberately excluded: none of the six §16 gates are patch-level,
// so comparing it would let a distro's backport patch release
// (2.25.<huge>, say) masquerade as meeting a minor-level gate it does not.
func (v GitVersion) atLeast(major, minor int) bool {
	if !v.OK {
		return false
	}
	if v.Major != major {
		return v.Major > major
	}
	return v.Minor >= minor
}

// GitCapabilitiesForVersion derives the six §16 rule 3 gates from a probed
// GitVersion. An unknown version (Probed && !OK, or Probed: false) yields the
// zero value — every gate false — which callers must read as "unknown", not
// "confirmed absent".
func GitCapabilitiesForVersion(v GitVersion) GitCapabilities {
	return GitCapabilities{
		CapPruneTags:           v.atLeast(2, 17),
		CapConfigShowScope:     v.atLeast(2, 26),
		CapDefaultBackendMerge: v.atLeast(2, 26),
		CapSoleRemoteFallback:  v.atLeast(2, 37),
		CapRebaseUpdateRefs:    v.atLeast(2, 38),
		CapFetchAll:            v.atLeast(2, 44),
	}
}

// ============================================================================
// ReparentGitCapabilities — safe-reparent's additive gate pair (§9.10)
//
// The six-gate GitCapabilities table above is frozen and MUST NOT be
// extended. The two facts below sit BESIDE it because neither is part of
// safe-reparent's required minimum: that minimum is the existing
// GitCapabilities.CapRebaseUpdateRefs gate (Git >= 2.38), which is already a
// sufficient floor for every core requirement — update-ref --stdin's
// start/prepare/commit verbs (2.27), --end-of-options (2.24),
// --no-rebase-merges (2.34), --disambiguate (long-standing), git switch
// (2.23) and the merge backend default (2.26) are all older — so no new
// version gate is invented for them.
// ============================================================================

// ReparentGitCapabilities is safe-reparent's own two-fact table. Each field
// gates exactly one optional behaviour and never the run as a whole:
// CapForceIfIncludes gates only the remote follow-up lease rule, and
// CapRefBackendKnown gates only which probe the ref-backend question uses.
// An unknown GitVersion yields the zero value — both false — which callers
// MUST read as "unknown" and resolve by taking the conservative branch, never
// by assuming absence and never by refusing.
type ReparentGitCapabilities struct {
	// CapForceIfIncludes is `git push --force-if-includes`, Git >= 2.30.
	CapForceIfIncludes bool

	// CapRefBackendKnown is `git rev-parse --show-ref-format`, Git >= 2.45.
	// When it is false the ref backend is probed with
	// `git config --get extensions.refStorage` instead, and an unresolved
	// answer is reported as "unknown" and treated exactly as "files".
	CapRefBackendKnown bool
}

// ReparentGitCapabilitiesForVersion derives the two additive gates from a
// probed GitVersion, reusing the same deliberately patch-blind atLeast
// comparison the frozen table uses. It never consults, changes or shadows
// GitCapabilitiesForVersion.
func ReparentGitCapabilitiesForVersion(v GitVersion) ReparentGitCapabilities {
	return ReparentGitCapabilities{
		CapForceIfIncludes: v.atLeast(2, 30),
		CapRefBackendKnown: v.atLeast(2, 45),
	}
}

// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion,
// the one call a controlled route needs to obtain both the raw probe (for its
// own rank 5.9 probe-failed detail, §16 rule 1) and the derived gate table in
// a single step.
func ProbeGitCapabilities() (GitCapabilities, GitVersion, error) {
	v, err := ProbeGitVersion()
	return GitCapabilitiesForVersion(v), v, err
}

package internal

import (
	"os"
	"path/filepath"
	"testing"
)

// ============================================================================
// git_capability_test.go — TestGitCapability*
//
// The locked §16 rule 2 version parser over real-world version strings,
// ProbeGitVersion's Probed/OK semantics (successful probe, exec failure,
// unparseable output), and the six independent §16 rule 3 capability gates
// at their exact boundaries (2.17, 2.26, 2.26, 2.37, 2.38, 2.44).
// ============================================================================

// ---------------------------------------------------------------------------
// The locked parser (gitVersionPattern), exercised directly against
// real-world `git --version` first lines without shelling out — this is the
// pure-function half of "the locked parser over real-world version strings".
// ---------------------------------------------------------------------------

func TestGitCapability_VersionPatternRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		raw       string
		wantMatch bool
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{name: "macOS Xcode packager suffix", raw: "git version 2.39.5 (Apple Git-154)", wantMatch: true, wantMajor: 2, wantMinor: 39, wantPatch: 5},
		{name: "plain three-component", raw: "git version 2.43.0", wantMatch: true, wantMajor: 2, wantMinor: 43, wantPatch: 0},
		{name: "Git-for-Windows four-component", raw: "git version 2.30.1.windows.1", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 1},
		{name: "minor-only, no patch component", raw: "git version 2.17", wantMatch: true, wantMajor: 2, wantMinor: 17, wantPatch: 0},
		{name: "Debian packager suffix", raw: "git version 2.30.2", wantMatch: true, wantMajor: 2, wantMinor: 30, wantPatch: 2},
		{name: "release-candidate patch suffix", raw: "git version 3.0.0-rc1", wantMatch: true, wantMajor: 3, wantMinor: 0, wantPatch: 0},
		{name: "future major version", raw: "git version 3.1.4", wantMatch: true, wantMajor: 3, wantMinor: 1, wantPatch: 4},
		{name: "empty string", raw: "", wantMatch: false},
		{name: "wrong case", raw: "GIT VERSION 2.30.0", wantMatch: false},
		{name: "non-numeric version", raw: "git version abc.def", wantMatch: false},
		{name: "unrelated program", raw: "some other program 2.3.4", wantMatch: false},
		{name: "missing minor component", raw: "git version 2", wantMatch: false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := gitVersionPattern.FindStringSubmatch(tc.raw)
			if tc.wantMatch != (m != nil) {
				t.Fatalf("gitVersionPattern.FindStringSubmatch(%q) match = %v, want %v", tc.raw, m != nil, tc.wantMatch)
			}
			if !tc.wantMatch {
				return
			}
			gotMajor, gotMinor, gotPatch := parseCapturedVersionGroups(t, m)
			if gotMajor != tc.wantMajor || gotMinor != tc.wantMinor || gotPatch != tc.wantPatch {
				t.Errorf("%q parsed as %d.%d.%d, want %d.%d.%d", tc.raw, gotMajor, gotMinor, gotPatch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// parseCapturedVersionGroups mirrors ProbeGitVersion's own group-to-int
// conversion (major/minor required, patch defaults to 0 when the optional
// third group did not participate), so this test exercises the same
// conversion rule the shipped function applies, not a reinvented one.
func parseCapturedVersionGroups(t *testing.T, m []string) (major, minor, patch int) {
	t.Helper()
	atoi := func(s string) int {
		if s == "" {
			return 0
		}
		n := 0
		for _, r := range s {
			n = n*10 + int(r-'0')
		}
		return n
	}
	return atoi(m[1]), atoi(m[2]), atoi(m[3])
}

// ---------------------------------------------------------------------------
// ProbeGitVersion's Probed/OK semantics, end to end (real exec.Command, no
// regex bypass) — successful real-host probe, exec failure (git not on
// PATH), and unparseable-but-successful output (a shimmed fake git).
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitVersion_RealHost(t *testing.T) {
	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion on the real host git: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false after a successful invocation, want true")
	}
	if !v.OK {
		t.Errorf("OK = false for real host git, want true (Raw=%q)", v.Raw)
	}
	if v.Major < 2 {
		t.Errorf("Major = %d, want >= 2 for any git installation this suite can run against", v.Major)
	}
	wantPrefix := "git version "
	if len(v.Raw) < len(wantPrefix) || v.Raw[:len(wantPrefix)] != wantPrefix {
		t.Errorf("Raw = %q, want it to start with %q", v.Raw, wantPrefix)
	}
}

func TestGitCapability_ProbeGitVersion_ExecFailure(t *testing.T) {
	// An empty PATH directory has no git binary at all: exec.Command itself
	// fails to start the process, which must still yield Probed:true (the
	// act of asking is itself the fact) alongside OK:false and a non-nil
	// error.
	t.Setenv("PATH", t.TempDir())

	v, err := ProbeGitVersion()
	if err == nil {
		t.Fatal("ProbeGitVersion with no git on PATH: want a non-nil error")
	}
	if !v.Probed {
		t.Error("Probed = false after an exec failure, want true")
	}
	if v.OK {
		t.Error("OK = true after an exec failure, want false")
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d after an exec failure, want all zero", v.Major, v.Minor, v.Patch)
	}
}

// installFakeGit points PATH at a directory containing only a `git` shell
// script that prints firstLine (optionally followed by more lines) to
// stdout and exits 0 — a real external process (never a Go-level mock of
// exec.Command), used only to observe ProbeGitVersion's own line-splitting
// and \r-trimming against output the real host's git cannot be made to
// produce on demand (an unparseable line, or a CRLF line ending).
func installFakeGit(t *testing.T, output string) {
	t.Helper()
	binDir := t.TempDir()
	outFile := filepath.Join(binDir, "version-output.txt")
	if err := os.WriteFile(outFile, []byte(output), 0o644); err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\ncat '" + outFile + "'\n"
	if err := os.WriteFile(filepath.Join(binDir, "git"), []byte(script), 0o755); err != nil {
		t.Fatal(err)
	}
	// Prepend, never replace: the script's own shebang needs the rest of
	// PATH to resolve `cat`. Only the git *lookup* itself needs binDir to
	// win, which prepending guarantees.
	t.Setenv("PATH", binDir+string(os.PathListSeparator)+os.Getenv("PATH"))
}

func TestGitCapability_ProbeGitVersion_UnparseableOutput(t *testing.T) {
	installFakeGit(t, "not a git version string at all\n")

	v, err := ProbeGitVersion()
	if err != nil {
		t.Fatalf("ProbeGitVersion: %v", err)
	}
	if !v.Probed {
		t.Error("Probed = false, want true (the invocation itself succeeded)")
	}
	if v.OK {
		t.Error("OK = true for an unparseable first line, want false")
	}
	if v.Raw != "not a git version string at all" {
		t.Errorf("Raw = %q, want the verbatim (newline-stripped) first line", v.Raw)
	}
	if v.Major != 0 || v.Minor != 0 || v.Patch != 0 {
		t.Errorf("Major/Minor/Patch = %d/%d/%d, want all zero when unparseable", v.Major, v.Minor, v.Patch)
	}
}

func TestGitCapability_ProbeGitVersion_FakeRealWorldStrings(t *testing.T) {
	cases := []struct {
		name      string
		output    string // full fake stdout, CRLF/multi-line included
		wantRaw   string
		wantMajor int
		wantMinor int
		wantPatch int
	}{
		{
			name:      "CRLF line ending is trimmed from Raw",
			output:    "git version 2.40.0\r\n",
			wantRaw:   "git version 2.40.0",
			wantMajor: 2, wantMinor: 40, wantPatch: 0,
		},
		{
			name:      "only the first line is consulted",
			output:    "git version 2.41.0\nsome other trailer line\n",
			wantRaw:   "git version 2.41.0",
			wantMajor: 2, wantMinor: 41, wantPatch: 0,
		},
		{
			name:      "Apple packager suffix survives end to end",
			output:    "git version 2.39.5 (Apple Git-154)\n",
			wantRaw:   "git version 2.39.5 (Apple Git-154)",
			wantMajor: 2, wantMinor: 39, wantPatch: 5,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			installFakeGit(t, tc.output)
			v, err := ProbeGitVersion()
			if err != nil {
				t.Fatalf("ProbeGitVersion: %v", err)
			}
			if !v.Probed || !v.OK {
				t.Fatalf("Probed/OK = %v/%v, want true/true (Raw=%q)", v.Probed, v.OK, v.Raw)
			}
			if v.Raw != tc.wantRaw {
				t.Errorf("Raw = %q, want %q", v.Raw, tc.wantRaw)
			}
			if v.Major != tc.wantMajor || v.Minor != tc.wantMinor || v.Patch != tc.wantPatch {
				t.Errorf("parsed %d.%d.%d, want %d.%d.%d", v.Major, v.Minor, v.Patch, tc.wantMajor, tc.wantMinor, tc.wantPatch)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// The six independent §16 rule 3 gate calculations, at their exact
// major.minor boundaries. Constructed GitVersion values are used directly
// (no exec needed) so every boundary — including ones this host's own
// installed git may not straddle — is covered deterministically.
// ---------------------------------------------------------------------------

func TestGitCapability_GateBoundaries(t *testing.T) {
	below := func(major, minor int) GitVersion {
		return GitVersion{Probed: true, OK: true, Major: major, Minor: minor}
	}

	cases := []struct {
		name string
		v    GitVersion
		gate func(GitCapabilities) bool
		want bool
	}{
		{"prune-tags below 2.17", below(2, 16), func(c GitCapabilities) bool { return c.CapPruneTags }, false},
		{"prune-tags at 2.17", below(2, 17), func(c GitCapabilities) bool { return c.CapPruneTags }, true},

		{"config-show-scope below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapConfigShowScope }, false},
		{"config-show-scope at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapConfigShowScope }, true},

		{"default-backend-merge below 2.26", below(2, 25), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, false},
		{"default-backend-merge at 2.26", below(2, 26), func(c GitCapabilities) bool { return c.CapDefaultBackendMerge }, true},

		{"sole-remote-fallback below 2.37", below(2, 36), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, false},
		{"sole-remote-fallback at 2.37", below(2, 37), func(c GitCapabilities) bool { return c.CapSoleRemoteFallback }, true},

		{"rebase-update-refs below 2.38", below(2, 37), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, false},
		{"rebase-update-refs at 2.38", below(2, 38), func(c GitCapabilities) bool { return c.CapRebaseUpdateRefs }, true},

		{"fetch-all below 2.44", below(2, 43), func(c GitCapabilities) bool { return c.CapFetchAll }, false},
		{"fetch-all at 2.44", below(2, 44), func(c GitCapabilities) bool { return c.CapFetchAll }, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := tc.gate(GitCapabilitiesForVersion(tc.v))
			if got != tc.want {
				t.Errorf("gate(%d.%d) = %v, want %v", tc.v.Major, tc.v.Minor, got, tc.want)
			}
		})
	}
}

func TestGitCapability_GateBoundaries_ConfigShowScopeAndDefaultBackendAreIndependentFields(t *testing.T) {
	// Both CapConfigShowScope and CapDefaultBackendMerge gate at the same
	// 2.26 boundary, but the doc comment on GitCapabilities is explicit that
	// they must never be collapsed into a shared field: assert both are
	// present and both actually equal true at 2.26, as two distinct
	// observations, not one.
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 26})
	if !caps.CapConfigShowScope {
		t.Error("CapConfigShowScope = false at 2.26, want true")
	}
	if !caps.CapDefaultBackendMerge {
		t.Error("CapDefaultBackendMerge = false at 2.26, want true")
	}
}

func TestGitCapability_GateBoundaries_PatchLevelNeverConsulted(t *testing.T) {
	// atLeast compares major.minor only: a huge patch on a version one minor
	// below a gate's threshold must not let that gate fire (no distro
	// backport can masquerade as meeting a minor-level gate).
	v := GitVersion{Probed: true, OK: true, Major: 2, Minor: 16, Patch: 999}
	if GitCapabilitiesForVersion(v).CapPruneTags {
		t.Errorf("CapPruneTags = true for 2.16.999, want false (patch must never bridge a minor gate)")
	}
}

func TestGitCapability_GateBoundaries_UnknownVersionYieldsAllGatesFalse(t *testing.T) {
	// An unknown version (Probed && !OK, or the zero value) yields every
	// gate false, which callers must read as "unknown", never "confirmed
	// absent" — GitCapabilitiesForVersion itself has no way to encode that
	// distinction, so this test only proves the all-false shape.
	for _, v := range []GitVersion{
		{},                                  // never probed
		{Probed: true, OK: false},           // probed, unparseable
		{Probed: true, OK: false, Major: 9}, // OK false must dominate even if Major/Minor were somehow set
	} {
		caps := GitCapabilitiesForVersion(v)
		if caps != (GitCapabilities{}) {
			t.Errorf("GitCapabilitiesForVersion(%+v) = %+v, want the all-false zero value", v, caps)
		}
	}
}

func TestGitCapability_GateBoundaries_VersionWellAboveAllGates(t *testing.T) {
	caps := GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 3, Minor: 0})
	want := GitCapabilities{
		CapPruneTags:           true,
		CapConfigShowScope:     true,
		CapDefaultBackendMerge: true,
		CapSoleRemoteFallback:  true,
		CapRebaseUpdateRefs:    true,
		CapFetchAll:            true,
	}
	if caps != want {
		t.Errorf("GitCapabilitiesForVersion(3.0) = %+v, want every gate true (%+v)", caps, want)
	}
}

// ---------------------------------------------------------------------------
// ProbeGitCapabilities composes ProbeGitVersion and GitCapabilitiesForVersion.
// ---------------------------------------------------------------------------

func TestGitCapability_ProbeGitCapabilities_ComposesProbeAndDerive(t *testing.T) {
	caps, v, err := ProbeGitCapabilities()
	if err != nil {
		t.Fatalf("ProbeGitCapabilities on the real host git: %v", err)
	}
	if !v.Probed || !v.OK {
		t.Fatalf("ProbeGitCapabilities returned Probed=%v OK=%v for the real host git, want true/true", v.Probed, v.OK)
	}
	want := GitCapabilitiesForVersion(v)
	if caps != want {
		t.Errorf("ProbeGitCapabilities capabilities = %+v, want GitCapabilitiesForVersion(returned version) = %+v", caps, want)
	}
}

// ---------------------------------------------------------------------------
// ReparentGitCapabilities — safe-reparent's additive gate pair (§9.10).
//
// The six-gate table above is frozen; these cells assert the new pair sits
// BESIDE it, gates at its own versions, and changes nothing about it.
// ---------------------------------------------------------------------------

func TestReparentGitCapabilities_GateBoundaries(t *testing.T) {
	cases := []struct {
		name           string
		version        GitVersion
		forceIfInclude bool
		refBackend     bool
	}{
		{"2.29 is below force-if-includes", GitVersion{Probed: true, OK: true, Major: 2, Minor: 29}, false, false},
		{"2.30 is exactly force-if-includes", GitVersion{Probed: true, OK: true, Major: 2, Minor: 30}, true, false},
		{"2.44 is below show-ref-format", GitVersion{Probed: true, OK: true, Major: 2, Minor: 44}, true, false},
		{"2.45 is exactly show-ref-format", GitVersion{Probed: true, OK: true, Major: 2, Minor: 45}, true, true},
		{"3.0 is above both", GitVersion{Probed: true, OK: true, Major: 3, Minor: 0}, true, true},
		{"1.99 is below both", GitVersion{Probed: true, OK: true, Major: 1, Minor: 99}, false, false},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			caps := ReparentGitCapabilitiesForVersion(tc.version)
			if caps.CapForceIfIncludes != tc.forceIfInclude {
				t.Errorf("CapForceIfIncludes = %v, want %v", caps.CapForceIfIncludes, tc.forceIfInclude)
			}
			if caps.CapRefBackendKnown != tc.refBackend {
				t.Errorf("CapRefBackendKnown = %v, want %v", caps.CapRefBackendKnown, tc.refBackend)
			}
		})
	}
}

func TestReparentGitCapabilities_UnknownVersionYieldsAllFalse(t *testing.T) {
	for _, v := range []GitVersion{
		{},
		{Probed: true, OK: false, Raw: "git version (unparseable)"},
	} {
		caps := ReparentGitCapabilitiesForVersion(v)
		if caps != (ReparentGitCapabilities{}) {
			t.Fatalf("ReparentGitCapabilitiesForVersion(%+v) = %+v, want the zero value read as unknown", v, caps)
		}
	}
}

func TestReparentGitCapabilities_PatchLevelNeverConsulted(t *testing.T) {
	low := ReparentGitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 44, Patch: 9999})
	if low.CapRefBackendKnown {
		t.Fatal("a 2.44 patch release must not satisfy the 2.45 gate")
	}
}

func TestReparentGitCapabilities_FrozenSixGateTableIsUnchanged(t *testing.T) {
	v := GitVersion{Probed: true, OK: true, Major: 2, Minor: 45}
	before := GitCapabilities{
		CapPruneTags:           true,
		CapConfigShowScope:     true,
		CapDefaultBackendMerge: true,
		CapSoleRemoteFallback:  true,
		CapRebaseUpdateRefs:    true,
		CapFetchAll:            true,
	}
	if got := GitCapabilitiesForVersion(v); got != before {
		t.Fatalf("GitCapabilitiesForVersion(2.45) = %+v, want the frozen %+v", got, before)
	}
	// The required minimum is the existing 2.38 gate, not a new one.
	if GitCapabilitiesForVersion(GitVersion{Probed: true, OK: true, Major: 2, Minor: 37}).CapRebaseUpdateRefs {
		t.Fatal("2.37 must not satisfy the CapRebaseUpdateRefs floor safe-reparent requires")
	}
}

package internal

import (
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// ============================================================================
// Destination and cutoff resolution (§4.1–§4.3c, §5.1–§5.3)
//
// Every probe in this file goes through runReparentGit, so every argv it
// emits selects its directory with exec.Cmd.Dir and never with `git -C`.
// reparentIsAncestor reproduces mergeBaseIsAncestor's exit-0/exit-1/error
// trichotomy for exactly that reason; mergeBaseIsAncestor itself stays
// untouched with every existing caller and is cited as the pattern only.
//
// One deliberate exception is recorded here rather than hidden: §4.3c
// requires the agreement adapter to call the shipped ResolveSyncBase
// UNMODIFIED, and that function reaches DefaultBranchIn, which does emit a
// `-C` argv. That argv belongs to the frozen shipped resolver the spec
// mandates consulting — the same way AC-031 scopes the frozen
// ancestryMergeBase out of this feature's boundary — and never to a
// reparent-emitted rebase, ref-transaction or push argv. Its answer cannot
// change the verdict either: §4.3b stores a full ref or a full OID, and
// neither can ever equal a short default-branch name, so the origin/<default>
// rewrite has nothing to rewrite.
// ============================================================================

// reparentHexToken is §4.3 step 2's candidate-object-id shape. Recognition is
// case-insensitive; the canonical form this feature stores and compares is
// always lowercase.
var reparentHexToken = regexp.MustCompile(`^[0-9a-fA-F]{4,64}$`)

// reparentPseudoRefs is the closed set of tokens that are NOT a reparent
// destination and not a cutoff. A destination that moves whenever Git moves
// it is not a topology decision, which is also why the gitrevisions
// $GIT_DIR/<refname> rung is deliberately not enumerated below.
var reparentPseudoRefs = map[string]bool{
	"HEAD":             true,
	"FETCH_HEAD":       true,
	"ORIG_HEAD":        true,
	"MERGE_HEAD":       true,
	"CHERRY_PICK_HEAD": true,
	"REVERT_HEAD":      true,
	"REBASE_HEAD":      true,
	"AUTO_MERGE":       true,
	"BISECT_HEAD":      true,
}

// reparentPseudoRefDetail is the exact sentence a pseudo-ref token refuses
// with, for a destination and for a cutoff alike.
const reparentPseudoRefDetail = "pseudo refs are not a reparent destination; name a branch, a full ref, or an object id"

// ReparentDestination is ResolveReparentDestination's total output: the one
// source of the published destination facts. The plan, the executor, the CAS
// values, the metadata write and the post-condition all read this one result,
// so none of them can resolve the destination a second, differing way.
type ReparentDestination struct {
	// RequestedToken is exactly what the operator typed.
	RequestedToken string
	// StoredToken is the canonical token written to StackEntry.Base (§4.3b).
	// It is never the short token the operator typed.
	StoredToken string
	// Kind is stack-entry or literal-ref.
	Kind string
	// Ref is the full resolved ref; nil for an object-id destination.
	Ref *string
	// SHA is the pinned destination commit, canonical lowercase.
	SHA string
	// Repo is the normalized repo of a stack-entry parent; nil for a literal.
	Repo *string
	// Resolution is the §4.3b resolution token.
	Resolution string
	// Candidates carries every surviving enumerated candidate ref, sorted;
	// empty when the resolution was unambiguous.
	Candidates []string
	// EntryName is the destination stack entry's logical Name; "" for a
	// literal-ref destination.
	EntryName string
}

// Parent projects the destination into the document's new_parent block. The
// resolver-agreement verdict is filled in separately by the caller that runs
// §4.3c, so this projection never claims an agreement it did not check.
func (d ReparentDestination) Parent() ReparentParent {
	requested := d.RequestedToken
	stored := d.StoredToken
	sha := d.SHA
	parent := ReparentParent{
		RequestedToken: &requested,
		StoredToken:    &stored,
		Kind:           d.Kind,
		Ref:            d.Ref,
		SHA:            &sha,
		Repo:           d.Repo,
		Resolution:     d.Resolution,
		Candidates:     ensureSlice(d.Candidates),
	}
	return parent
}

// ============================================================================
// Primitive probes
// ============================================================================

// reparentIsAncestor reproduces mergeBaseIsAncestor's trichotomy through
// runReparentGit with Cmd.Dir: exit 0 is (true, nil), exit 1 is (false, nil),
// and anything else — including a failure to spawn git at all — is an error a
// caller surfaces as probe-failed. It is the ONLY form in which this feature
// ever emits `git merge-base`.
func reparentIsAncestor(dir, ancestor, descendant string) (bool, error) {
	res, err := runReparentGit(dir, nil, "merge-base", "--is-ancestor", ancestor, descendant)
	if err == nil {
		return true, nil
	}
	if res.ExitCode == 1 {
		return false, nil
	}
	return false, fmt.Errorf("merge-base --is-ancestor %s %s: %w", ancestor, descendant, err)
}

// reparentOIDWidth determines the repository's canonical OID width once per
// run (§4.3a step 1). sha1 means 40 and sha256 means 64; any other or
// unreadable value refuses capability-unsupported, because no other width is
// ever assumed.
func reparentOIDWidth(repoDir string) (int, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--show-object-format")
	if err != nil {
		return 0, reparentRefusal(ReparentRefusalCapabilityUnsupported,
			fmt.Sprintf("git rev-parse --show-object-format failed: %s", reparentGitMessage(res, err)))
	}
	switch format := strings.TrimSpace(string(res.Stdout)); format {
	case "sha1":
		return 40, nil
	case "sha256":
		return 64, nil
	default:
		return 0, reparentRefusal(ReparentRefusalCapabilityUnsupported,
			fmt.Sprintf("unsupported object format %q; reparent supports sha1 and sha256 only", format))
	}
}

// reparentGitMessage renders a failed probe's own words for a refusal detail:
// Git's stderr when it wrote any, else the Go error.
func reparentGitMessage(res reparentGitResult, err error) string {
	if msg := strings.TrimSpace(string(res.Stderr)); msg != "" {
		return msg
	}
	return err.Error()
}

// reparentPeelCommit runs `git rev-parse --verify --quiet --end-of-options
// <spec>^{commit}`. It returns (sha, true, nil) when spec names a commit,
// ("", false, nil) when it does not, and an error only for a probe failure —
// --quiet exits 1 for both "unknown" and "ambiguous", so a caller that needs
// to tell those apart must have disambiguated first (§4.3a).
func reparentPeelCommit(repoDir, spec string) (string, bool, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--verify", "--quiet", "--end-of-options", spec+"^{commit}")
	if err != nil {
		if res.ExitCode == 1 {
			return "", false, nil
		}
		return "", false, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse --verify %s^{commit} failed: %s", spec, reparentGitMessage(res, err)))
	}
	sha := strings.TrimSpace(string(res.Stdout))
	if sha == "" {
		return "", false, nil
	}
	return strings.ToLower(sha), true, nil
}

// reparentRefCandidates is §4.3 step 3's five candidate full refs, in the
// order they are enumerated. The order is part of the contract: it is the
// order a candidate list is built in before sorting for display.
func reparentRefCandidates(token string) [5]string {
	return [5]string{
		"refs/" + token,
		"refs/tags/" + token,
		"refs/heads/" + token,
		"refs/remotes/" + token,
		"refs/remotes/" + token + "/HEAD",
	}
}

// reparentForEachRef runs ONE `git for-each-ref --format=%(refname)`
// invocation over the given patterns and returns every line it printed.
func reparentForEachRef(repoDir string, patterns ...string) ([]string, error) {
	args := append([]string{"for-each-ref", "--format=%(refname)"}, patterns...)
	res, err := runReparentGit(repoDir, nil, args...)
	if err != nil {
		return nil, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git for-each-ref failed: %s", reparentGitMessage(res, err)))
	}
	var out []string
	for _, line := range strings.Split(string(res.Stdout), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, line)
		}
	}
	return out, nil
}

// reparentSurvivingCandidates enumerates the five candidates of §4.3 step 3
// in one for-each-ref call and keeps only lines that are EXACTLY equal to one
// of them, sorted. for-each-ref treats its operands as patterns, so an
// unfiltered result can contain refs the operator never named; this filter is
// the whole reason rev-parse is not used here.
func reparentSurvivingCandidates(repoDir, token string) ([]string, error) {
	candidates := reparentRefCandidates(token)
	lines, err := reparentForEachRef(repoDir, candidates[:]...)
	if err != nil {
		return nil, err
	}
	allowed := make(map[string]bool, len(candidates))
	for _, candidate := range candidates {
		allowed[candidate] = true
	}
	seen := make(map[string]bool, len(lines))
	var surviving []string
	for _, line := range lines {
		if allowed[line] && !seen[line] {
			seen[line] = true
			surviving = append(surviving, line)
		}
	}
	sort.Strings(surviving)
	return surviving, nil
}

// reparentFullRefExists verifies a `^refs/` token exists EXACTLY, by asking
// for-each-ref for that one pattern and requiring the identical string back.
// No enumeration is performed for a full ref.
func reparentFullRefExists(repoDir, token string) (bool, error) {
	lines, err := reparentForEachRef(repoDir, token)
	if err != nil {
		return false, err
	}
	for _, line := range lines {
		if line == token {
			return true, nil
		}
	}
	return false, nil
}

// reparentDisambiguate returns every object id whose name begins with prefix
// (§4.3a step 3). The count deliberately includes every object type: a prefix
// matching one commit and one blob is ambiguous even though a later ^{commit}
// peel could pick the commit, because reparent requires a globally
// unambiguous object spelling.
func reparentDisambiguate(repoDir, prefix string) ([]string, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", "--disambiguate="+strings.ToLower(prefix))
	if err != nil {
		// An empty answer with a non-zero status is Git reporting "no such
		// object", which is a normal answer here, not a probe failure.
		if strings.TrimSpace(string(res.Stdout)) == "" && res.ExitCode > 0 {
			return nil, nil
		}
		return nil, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse --disambiguate=%s failed: %s", prefix, reparentGitMessage(res, err)))
	}
	var out []string
	for _, line := range strings.Split(string(res.Stdout), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			out = append(out, strings.ToLower(line))
		}
	}
	sort.Strings(out)
	return out, nil
}

// ============================================================================
// Literal-token resolution (§4.3, §4.3a, §4.3b)
// ============================================================================

// reparentLiteral is one literal token's resolution.
type reparentLiteral struct {
	Ref         *string
	SHA         string
	Resolution  string
	StoredToken string
	Candidates  []string
}

// resolveReparentLiteral resolves a literal token — a destination's or a
// cutoff's — through the identical namespace enumeration and object-id rules.
//
// ambiguousKind is the caller's own ambiguity kind: a destination refuses
// destination-ambiguous, while a cutoff refuses cutoff-unresolvable for every
// ambiguity it can exhibit (§5.3), because the cutoff is a boundary, not a
// destination, and one kind with a complete candidate list is more useful
// than two kinds with split details.
func resolveReparentLiteral(repoDir, token string, oidWidth int, unresolvableKind, ambiguousKind ReparentRefusalKind) (reparentLiteral, error) {
	if reparentPseudoRefs[token] {
		return reparentLiteral{Resolution: ReparentResolutionUnresolved},
			reparentRefusal(unresolvableKind, reparentPseudoRefDetail)
	}

	// 1. A full ref must exist exactly; no enumeration is performed.
	if strings.HasPrefix(token, "refs/") {
		exists, err := reparentFullRefExists(repoDir, token)
		if err != nil {
			return reparentLiteral{}, err
		}
		if !exists {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved},
				reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not exist", token))
		}
		sha, ok, err := reparentPeelCommit(repoDir, token)
		if err != nil {
			return reparentLiteral{}, err
		}
		if !ok {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved},
				reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not name a commit", token))
		}
		ref := token
		return reparentLiteral{Ref: &ref, SHA: sha, Resolution: ReparentResolutionRefFull, StoredToken: token}, nil
	}

	// 2/3. A hex token may be an object id; §4.3a decides, and falls through
	// to the short-name rung when it is not an object at all. The object
	// rung's own partial facts travel with its refusal: a refused token still
	// publishes a resolution inside the closed domain, and an ambiguous one
	// still publishes what it was ambiguous between.
	if reparentHexToken.MatchString(token) {
		object, isObject, err := resolveReparentObjectID(repoDir, token, oidWidth, unresolvableKind, ambiguousKind)
		if err != nil {
			return object, err
		}
		if isObject {
			// §4.3a step 4: an object id that is ALSO a ref name is
			// ambiguous, whichever rung recognized it.
			surviving, err := reparentSurvivingCandidates(repoDir, token)
			if err != nil {
				return reparentLiteral{}, err
			}
			if len(surviving) > 0 {
				return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: surviving},
					reparentRefusal(ambiguousKind,
						fmt.Sprintf("%q is both object %s and ref %s; name the full object id or the full ref",
							token, object.SHA, strings.Join(surviving, ", ")))
			}
			return object, nil
		}
	}

	// 3. Short name: exactly five candidates, exact-equality filtered.
	surviving, err := reparentSurvivingCandidates(repoDir, token)
	if err != nil {
		return reparentLiteral{}, err
	}
	switch len(surviving) {
	case 0:
		return reparentLiteral{Resolution: ReparentResolutionUnresolved},
			reparentRefusal(unresolvableKind, fmt.Sprintf("%q does not resolve to a ref or an object id", token))
	case 1:
		// resolved below
	default:
		return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: surviving},
			reparentRefusal(ambiguousKind,
				fmt.Sprintf("%q matches %s; re-run with the full ref", token, strings.Join(surviving, ", ")))
	}

	ref := surviving[0]
	sha, ok, err := reparentPeelCommit(repoDir, ref)
	if err != nil {
		return reparentLiteral{}, err
	}
	if !ok {
		return reparentLiteral{Resolution: ReparentResolutionUnresolved, Candidates: surviving},
			reparentRefusal(unresolvableKind, fmt.Sprintf("ref %q does not name a commit", ref))
	}
	return reparentLiteral{
		Ref:         &ref,
		SHA:         sha,
		Resolution:  reparentRefResolution(ref),
		StoredToken: ref,
	}, nil
}

// reparentRefResolution maps a resolved full ref to its §4.3b resolution
// token. The order matters: refs/remotes/ and refs/tags/ and refs/heads/ are
// checked before the refs/<other> catch-all.
func reparentRefResolution(ref string) string {
	switch {
	case strings.HasPrefix(ref, "refs/heads/"):
		return ReparentResolutionRefHead
	case strings.HasPrefix(ref, "refs/tags/"):
		return ReparentResolutionRefTag
	case strings.HasPrefix(ref, "refs/remotes/"):
		return ReparentResolutionRefRemote
	default:
		return ReparentResolutionRefOther
	}
}

// resolveReparentObjectID implements §4.3a steps 2 and 3.
//
// It returns a reparentLiteral in EVERY outcome, so no caller has to
// reconstruct what the rung learned:
//
//   - object id resolved: ({SHA, raw-oid, StoredToken}, true, nil);
//   - not an object at all: (zero literal, false, nil) — the caller falls
//     through to the short-name rung, where the empty resolution is replaced;
//   - multi-match abbreviation: ({ambiguous, sorted candidate OIDs}, false,
//     refusal);
//   - non-committish or unresolvable object: ({unresolved}, false, refusal).
//
// The second result is meaningful only when the error is nil. Publishing the
// partial literal matters because resolution and candidates are closed-domain
// document cells: a refused token must never publish an empty resolution.
func resolveReparentObjectID(repoDir, token string, oidWidth int, unresolvableKind, ambiguousKind ReparentRefusalKind) (reparentLiteral, bool, error) {
	lowered := strings.ToLower(token)

	if len(token) == oidWidth {
		sha, ok, err := reparentPeelCommit(repoDir, lowered)
		if err != nil {
			return reparentLiteral{}, false, err
		}
		if !ok {
			return reparentLiteral{Resolution: ReparentResolutionUnresolved}, false,
				reparentRefusal(unresolvableKind,
					fmt.Sprintf("object %q does not resolve to a commit", token))
		}
		return reparentLiteral{SHA: sha, Resolution: ReparentResolutionRawOID, StoredToken: sha}, true, nil
	}

	matches, err := reparentDisambiguate(repoDir, lowered)
	if err != nil {
		return reparentLiteral{}, false, err
	}
	switch len(matches) {
	case 0:
		// Not an object id: the short-name rung decides.
		return reparentLiteral{}, false, nil
	case 1:
		// resolved below
	default:
		// The candidate list carries the sorted full OIDs the prefix matched,
		// which is what "re-run with the full object id" refers to; a ref
		// ambiguity carries refs in the same cell.
		return reparentLiteral{Resolution: ReparentResolutionAmbiguous, Candidates: matches}, false,
			reparentRefusal(ambiguousKind,
				fmt.Sprintf("%q matches %d objects (%s); name the full object id",
					token, len(matches), strings.Join(matches, ", ")))
	}

	sha, ok, err := reparentPeelCommit(repoDir, matches[0])
	if err != nil {
		return reparentLiteral{}, false, err
	}
	if !ok {
		// A single, unambiguous match that is not a commit: unresolved, with
		// no candidate list, because nothing was ambiguous.
		return reparentLiteral{Resolution: ReparentResolutionUnresolved}, false,
			reparentRefusal(unresolvableKind,
				fmt.Sprintf("object %s does not resolve to a commit", matches[0]))
	}
	return reparentLiteral{SHA: sha, Resolution: ReparentResolutionRawOID, StoredToken: sha}, true, nil
}

// ============================================================================
// ResolveReparentDestination (§4.1, §4.2, §4.3, §4.3b)
// ============================================================================

// ResolveReparentDestination resolves --onto into the single pinned
// destination this run uses everywhere.
//
// kind selects how the token is read: auto is entry-first (a token equal to
// some StackEntry.Name is that entry, otherwise it is a literal), entry
// requires an entry, and ref never consults entry names at all. Storing the
// full ref is what makes --onto-kind ref safe against an entry name that
// happens to match, and what stops ResolveSyncBase's origin/<default> rewrite
// from ever re-interpreting a token this feature chose.
//
// It never performs that rewrite itself: a reparent destination is exactly
// what the operator named, stored canonically.
func ResolveReparentDestination(repoDir string, stack Stack, target StackEntry, token, kind string, oidWidth int) (ReparentDestination, error) {
	trimmed := strings.TrimSpace(token)
	if trimmed == "" {
		return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationUnset, "--onto requires a destination")
	}

	entry, isEntry := reparentLookupEntry(stack, trimmed)
	switch kind {
	case "entry":
		if !isEntry {
			return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationKindMismatch,
				fmt.Sprintf("--onto-kind entry requires a stack entry name; %q is not an entry in this feature's stack.yaml", trimmed))
		}
		return resolveReparentEntryDestination(repoDir, target, entry, trimmed)
	case "ref":
		isEntry = false
	case "auto", "":
		// entry-first, decided by isEntry above
	default:
		return ReparentDestination{}, reparentRefusal(ReparentRefusalDestinationKindMismatch,
			fmt.Sprintf("--onto-kind must be one of: auto, entry, ref (got %q)", kind))
	}

	if isEntry {
		return resolveReparentEntryDestination(repoDir, target, entry, trimmed)
	}

	literal, err := resolveReparentLiteral(repoDir, trimmed, oidWidth,
		ReparentRefusalDestinationUnresolvable, ReparentRefusalDestinationAmbiguous)
	if err != nil {
		// The partially-resolved facts travel with the refusal so an
		// unavailable plan can publish resolution and candidates instead of
		// dropping what the run did learn. resolution is a closed-domain
		// document cell, so a rung that learned nothing at all — a failed
		// read-only probe — still publishes `unresolved` rather than an
		// empty string outside the domain.
		resolution := literal.Resolution
		if resolution == "" {
			resolution = ReparentResolutionUnresolved
		}
		return ReparentDestination{
			RequestedToken: trimmed,
			Kind:           ReparentParentKindLiteralRef,
			Resolution:     resolution,
			Candidates:     literal.Candidates,
		}, err
	}
	return ReparentDestination{
		RequestedToken: trimmed,
		StoredToken:    literal.StoredToken,
		Kind:           ReparentParentKindLiteralRef,
		Ref:            literal.Ref,
		SHA:            literal.SHA,
		Resolution:     literal.Resolution,
		Candidates:     literal.Candidates,
	}, nil
}

// reparentLookupEntry finds an entry by exact Name.
func reparentLookupEntry(stack Stack, name string) (StackEntry, bool) {
	for _, e := range stack.Branches {
		if e.Name == name {
			return e, true
		}
	}
	return StackEntry{}, false
}

// resolveReparentEntryDestination is §4.2: an in-stack parent resolves
// through refs/heads/<parent.GitBranch()>, matching stackBaseRef exactly.
func resolveReparentEntryDestination(repoDir string, target, parent StackEntry, requested string) (ReparentDestination, error) {
	if !SameStackRepo(parent.Repo, target.Repo) {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalCrossRepoClosure, parent.Name,
			fmt.Sprintf("destination entry %q is configured in repo %q but the target is in repo %q", parent.Name, parent.Repo, target.Repo))
	}
	if parent.Archived {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalAffectedArchived, parent.Name,
			fmt.Sprintf("destination entry %q is archived", parent.Name))
	}

	ref := "refs/heads/" + parent.GitBranch()
	exists, err := reparentFullRefExists(repoDir, ref)
	if err != nil {
		return ReparentDestination{}, err
	}
	if !exists {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalDestinationUnresolvable, parent.Name,
			fmt.Sprintf("ref %q does not exist", ref))
	}
	sha, ok, err := reparentPeelCommit(repoDir, ref)
	if err != nil {
		return ReparentDestination{}, err
	}
	if !ok {
		return ReparentDestination{}, reparentEntryRefusal(ReparentRefusalDestinationUnresolvable, parent.Name,
			fmt.Sprintf("ref %q does not name a commit", ref))
	}

	repo := parent.Repo
	return ReparentDestination{
		RequestedToken: requested,
		StoredToken:    parent.Name,
		Kind:           ReparentParentKindStackEntry,
		Ref:            &ref,
		SHA:            sha,
		Repo:           &repo,
		Resolution:     ReparentResolutionEntry,
		EntryName:      parent.Name,
	}, nil
}

// ============================================================================
// Cutoff ladders (§5.1, §5.2, §5.3)
//
// merge-base is never a cutoff. Every rung below either reads a recorded
// boundary, resolves an operator-supplied one, or takes the OLD PARENT's
// pre-image tip and proves it is an ancestor of the row's branch first.
// ============================================================================

// resolveReparentTargetCutoff walks §5.1's closed ladder for the target row.
//
// recordedSHA is the target's LastBaseSHA as the PRE-IMAGE snapshot captured
// it, never a live re-read: a cutoff that changes underneath a run is exactly
// the failure this ladder exists to prevent. suppliedToken is --cutoff's raw
// value, "" when absent.
func resolveReparentTargetCutoff(repoDir string, stack Stack, target StackEntry, recordedSHA, suppliedToken string, oidWidth int) (ReparentPlanCutoff, error) {
	cutoff := ReparentPlanCutoff{
		RecordedState: ReparentCutoffRecordAbsent,
		Provenance:    ReparentCutoffNone,
	}
	if recordedSHA != "" {
		recorded := recordedSHA
		cutoff.RecordedSHA = &recorded
	}
	if suppliedToken != "" {
		supplied := suppliedToken
		cutoff.SuppliedToken = &supplied
	}
	branchRef := "refs/heads/" + target.GitBranch()

	// Rungs 1 and 2: a recorded boundary is authoritative, and an
	// unresolvable one is fatal — a supplied token MUST NOT override it.
	if recordedSHA != "" {
		resolved, ok, err := reparentPeelCommit(repoDir, recordedSHA)
		if err != nil {
			return cutoff, err
		}
		if !ok {
			cutoff.RecordedState = ReparentCutoffRecordUnresolvable
			return cutoff, reparentEntryRefusal(ReparentRefusalCutoffUnresolvable, target.Name,
				fmt.Sprintf("recorded cutoff %s no longer resolves; restore or fetch the missing object before reparenting", recordedSHA))
		}
		cutoff.RecordedState = ReparentCutoffRecordPresent
		cutoff.ResolvedSHA = &resolved
		cutoff.Provenance = ReparentCutoffRecordedBySync

		if suppliedToken != "" {
			literal, err := resolveReparentLiteral(repoDir, suppliedToken, oidWidth,
				ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
			if err != nil {
				return cutoff, reparentAttributeEntry(err, target.Name)
			}
			suppliedSHA := literal.SHA
			cutoff.SuppliedSHA = &suppliedSHA
			if suppliedSHA != resolved {
				conflict := fmt.Sprintf("--cutoff resolves to %s but the recorded boundary is %s", suppliedSHA, resolved)
				cutoff.Conflict = &conflict
				return cutoff, reparentEntryRefusal(ReparentRefusalCutoffConflict, target.Name, conflict)
			}
		}
		return cutoff, nil
	}

	// Rung 3: an operator-supplied boundary, resolved by §5.3.
	if suppliedToken != "" {
		literal, err := resolveReparentLiteral(repoDir, suppliedToken, oidWidth,
			ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
		if err != nil {
			return cutoff, reparentAttributeEntry(err, target.Name)
		}
		suppliedSHA := literal.SHA
		cutoff.SuppliedSHA = &suppliedSHA
		cutoff.ResolvedSHA = &suppliedSHA
		cutoff.Provenance = ReparentCutoffOperatorSupplied
		return cutoff, nil
	}

	// Rung 4: the old parent's pre-image tip, usable only when it resolves
	// AND is an ancestor of the target's branch.
	tip, ok, err := resolveReparentOldParentTip(repoDir, stack, target, oidWidth)
	if err != nil {
		return cutoff, err
	}
	if ok {
		isAncestor, err := reparentIsAncestor(repoDir, tip, branchRef)
		if err != nil {
			return cutoff, reparentEntryRefusal(ReparentRefusalProbeFailed, target.Name, err.Error())
		}
		cutoff.AncestorOfBranch = &isAncestor
		if isAncestor {
			resolved := tip
			cutoff.ResolvedSHA = &resolved
			cutoff.Provenance = ReparentCutoffOldParentTip
			return cutoff, nil
		}
	}

	// Rung 5.
	return cutoff, reparentEntryRefusal(ReparentRefusalCutoffAbsent, target.Name,
		fmt.Sprintf("no replay boundary is recorded for %q; supply --cutoff <ref>, or establish a baseline with: tws sync <feature> --only %s", target.Name, target.Name))
}

// resolveReparentDescendantCutoff walks §5.2's closed ladder. --cutoff never
// applies to a descendant: a descendant MUST use its own snapshotted
// boundary, and the target's old tip is never substituted for it.
func resolveReparentDescendantCutoff(repoDir string, stack Stack, row StackEntry, recordedSHA string, oidWidth int) (ReparentPlanCutoff, error) {
	cutoff := ReparentPlanCutoff{
		RecordedState: ReparentCutoffRecordAbsent,
		Provenance:    ReparentCutoffNone,
	}
	if recordedSHA != "" {
		recorded := recordedSHA
		cutoff.RecordedSHA = &recorded
	}
	branchRef := "refs/heads/" + row.GitBranch()

	if recordedSHA != "" {
		resolved, ok, err := reparentPeelCommit(repoDir, recordedSHA)
		if err != nil {
			return cutoff, err
		}
		if !ok {
			cutoff.RecordedState = ReparentCutoffRecordUnresolvable
			return cutoff, reparentEntryRefusal(ReparentRefusalCutoffUnresolvable, row.Name,
				fmt.Sprintf("recorded cutoff %s for %q no longer resolves; restore or fetch the missing object before reparenting", recordedSHA, row.Name))
		}
		cutoff.RecordedState = ReparentCutoffRecordPresent
		cutoff.ResolvedSHA = &resolved
		cutoff.Provenance = ReparentCutoffRecordedBySync
		return cutoff, nil
	}

	tip, ok, err := resolveReparentOldParentTip(repoDir, stack, row, oidWidth)
	if err != nil {
		return cutoff, err
	}
	if ok {
		isAncestor, err := reparentIsAncestor(repoDir, tip, branchRef)
		if err != nil {
			return cutoff, reparentEntryRefusal(ReparentRefusalProbeFailed, row.Name, err.Error())
		}
		cutoff.AncestorOfBranch = &isAncestor
		if isAncestor {
			resolved := tip
			cutoff.ResolvedSHA = &resolved
			cutoff.Provenance = ReparentCutoffOldParentTip
			return cutoff, nil
		}
	}

	return cutoff, reparentEntryRefusal(ReparentRefusalDescendantCutoffAbsent, row.Name,
		fmt.Sprintf("no replay boundary is recorded for descendant %q; establish descendant baselines first with: tws sync <feature> --from %s", row.Name, row.Name))
}

// resolveReparentOldParentTip resolves an entry's CONFIGURED parent to its
// pre-image commit, applying §4.2's entry rule and §4.3's literal rules to
// the old token. An unresolvable or ambiguous old token is not an error here:
// it simply means this rung produced no boundary and the ladder moves on. A
// genuine probe failure is still returned.
func resolveReparentOldParentTip(repoDir string, stack Stack, entry StackEntry, oidWidth int) (string, bool, error) {
	if entry.Base == "" {
		return "", false, nil
	}
	if parent, found := reparentLookupEntry(stack, entry.Base); found && SameStackRepo(parent.Repo, entry.Repo) {
		return reparentPeelCommit(repoDir, "refs/heads/"+parent.GitBranch())
	}
	literal, err := resolveReparentLiteral(repoDir, entry.Base, oidWidth,
		ReparentRefusalCutoffUnresolvable, ReparentRefusalCutoffUnresolvable)
	if err != nil {
		var refusal *ReparentRefusalError
		if asReparentRefusal(err, &refusal) && refusal.Kind != ReparentRefusalProbeFailed {
			return "", false, nil
		}
		return "", false, err
	}
	return literal.SHA, true, nil
}

// reparentAttributeEntry stamps an entry name onto a document-level reparent
// refusal, so a cutoff refusal raised by the shared literal resolver is
// reported against the row that asked for it.
func reparentAttributeEntry(err error, entry string) error {
	var refusal *ReparentRefusalError
	if !asReparentRefusal(err, &refusal) {
		return err
	}
	if refusal.Entry != nil {
		return err
	}
	name := entry
	return &ReparentRefusalError{Kind: refusal.Kind, Entry: &name, Detail: refusal.Detail, StatePreserved: refusal.StatePreserved}
}

// asReparentRefusal is errors.As for *ReparentRefusalError, kept as one
// helper so every call site spells the assertion identically.
func asReparentRefusal(err error, target **ReparentRefusalError) bool {
	return errors.As(err, target)
}

// ============================================================================
// Resolver agreement (§4.3c)
// ============================================================================

// resolveReparentAgreement confirms that all four base resolvers, given the
// STORED token, agree on the pinned destination commit.
//
// postImage is the stack this run would write — the target's Base already
// replaced by the stored token — because that is the graph the very next
// `tws sync` and `tws stack status` will read. Resolvers 2-4 return ref or
// token spellings rather than a uniformly peeled OID, so each answer is
// normalized with `rev-parse --verify --quiet --end-of-options <answer>^{commit}`
// before comparison. That normalization is load-bearing for annotated tags:
// the checkout resolver's bare rev-parse observes the TAG OBJECT's id, while
// the normalized answer must be the peeled commit.
//
// The shipped resolvers themselves are called unmodified.
func resolveReparentAgreement(repoDir string, postImage Stack, target StackEntry, storedToken, pinnedSHA string) (ReparentResolverAgreement, error) {
	agreement := ReparentResolverAgreement{Checked: true}
	agreed := true

	record := func(name, rawAnswer string, normalized string, ok bool, failure string) {
		verdict := ReparentResolverVerdict{Name: name}
		if ok {
			sha := normalized
			verdict.SHA = &sha
			verdict.Agrees = normalized == pinnedSHA
			if !verdict.Agrees {
				detail := fmt.Sprintf("resolver %s answered %q for stored token %q, which normalizes to %s, not the pinned %s",
					name, rawAnswer, storedToken, normalized, pinnedSHA)
				verdict.Detail = &detail
			}
		} else {
			detail := failure
			verdict.Detail = &detail
		}
		if !verdict.Agrees {
			agreed = false
		}
		agreement.Resolvers = append(agreement.Resolvers, verdict)
	}

	// 1. ResolveReparentDestination — already a peeled OID by construction.
	record(ReparentResolverDestination, storedToken, pinnedSHA, true, "")

	// 2. ResolveSyncBase.
	syncBase := ResolveSyncBase(postImage, target, repoDir)
	if syncBase.Base == "" {
		record(ReparentResolverSyncBase, "", "", false,
			fmt.Sprintf("resolver %s produced no base for stored token %q (kind %s); expected %s",
				ReparentResolverSyncBase, storedToken, syncBase.Kind, pinnedSHA))
	} else {
		normalized, ok, err := reparentPeelCommit(repoDir, syncBase.Base)
		if err != nil {
			return agreement, err
		}
		record(ReparentResolverSyncBase, syncBase.Base, normalized, ok,
			fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve to a commit; expected %s",
				ReparentResolverSyncBase, syncBase.Base, storedToken, pinnedSHA))
	}

	// 3. stackBaseRef.
	baseRef, baseKind := stackBaseRef(postImage, target)
	if baseKind == StackBaseNone || baseRef == "" {
		record(ReparentResolverStackBase, "", "", false,
			fmt.Sprintf("resolver %s produced no base ref for stored token %q; expected %s",
				ReparentResolverStackBase, storedToken, pinnedSHA))
	} else {
		normalized, ok, err := reparentPeelCommit(repoDir, baseRef)
		if err != nil {
			return agreement, err
		}
		record(ReparentResolverStackBase, baseRef, normalized, ok,
			fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve to a commit; expected %s",
				ReparentResolverStackBase, baseRef, storedToken, pinnedSHA))
	}

	// 4. The checkout executor's base pick, through the extracted selector so
	// a future divergence is a compile error rather than a silent mismatch.
	checkoutToken, hasToken := checkoutBaseTokenFor(postImage, target)
	if !hasToken {
		record(ReparentResolverCheckout, "", "", false,
			fmt.Sprintf("resolver %s produced no base token for stored token %q; expected %s",
				ReparentResolverCheckout, storedToken, pinnedSHA))
	} else {
		// The shipped executor resolves its token with a bare rev-parse, so
		// the raw answer is deliberately the unpeeled object id.
		raw, rawOK, err := reparentRevParse(repoDir, checkoutToken)
		if err != nil {
			return agreement, err
		}
		if !rawOK {
			record(ReparentResolverCheckout, checkoutToken, "", false,
				fmt.Sprintf("resolver %s answered %q for stored token %q, which does not resolve; expected %s",
					ReparentResolverCheckout, checkoutToken, storedToken, pinnedSHA))
		} else {
			normalized, ok, err := reparentPeelCommit(repoDir, raw)
			if err != nil {
				return agreement, err
			}
			record(ReparentResolverCheckout, raw, normalized, ok,
				fmt.Sprintf("resolver %s answered %q (%s) for stored token %q, which does not peel to a commit; expected %s",
					ReparentResolverCheckout, checkoutToken, raw, storedToken, pinnedSHA))
		}
	}

	agreement.Agreed = &agreed
	if !agreed {
		for _, verdict := range agreement.Resolvers {
			if verdict.Agrees {
				continue
			}
			detail := fmt.Sprintf("resolver %s disagrees about stored token %q", verdict.Name, storedToken)
			if verdict.Detail != nil {
				detail = *verdict.Detail
			}
			return agreement, reparentRefusal(ReparentRefusalDestinationResolverDivergent, detail)
		}
	}
	return agreement, nil
}

// reparentRevParse runs a bare `git rev-parse <token>` — the exact shape the
// shipped checkout executor uses — and reports whether it resolved. It is
// used only to capture that resolver's RAW answer for the agreement block;
// every comparison is made on the normalized, peeled value.
func reparentRevParse(repoDir, token string) (string, bool, error) {
	res, err := runReparentGit(repoDir, nil, "rev-parse", token)
	if err != nil {
		if res.ExitCode > 0 {
			return "", false, nil
		}
		return "", false, reparentRefusal(ReparentRefusalProbeFailed,
			fmt.Sprintf("git rev-parse %s failed: %s", token, reparentGitMessage(res, err)))
	}
	answer := strings.TrimSpace(string(res.Stdout))
	if answer == "" {
		return "", false, nil
	}
	return strings.ToLower(answer), true, nil
}

package internal

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// Matrix ownership (§17.2): this file owns the destination and cutoff cells.
//
//	T-004 cutoff ladder: recorded / conflict / unresolvable ....... AC-022, AC-023
//	T-005 cutoff ladder: supplied / old-parent-tip / absent ....... AC-024, AC-025, AC-026
//	T-006 non-ancestor cutoff refuses without rebasing ............ AC-027
//	T-007 descendant cutoff snapshot vs live ref ................. AC-028, AC-029
//	T-008 cutoff ambiguity folds to one kind ..................... AC-030
//	T-010 destination kinds, every literal shape ................. AC-015
//	T-011 destination ambiguity, exact-equality filter ........... AC-014
//	T-012 abbreviated OID via --disambiguate ..................... AC-015
//	T-014 pseudo refs rejected, destination and cutoff ........... AC-017
//	T-015 --onto-kind auto/entry/ref matrix ...................... AC-011, AC-012, AC-013
//	T-016 canonical stored token, short token never persisted .... AC-013, AC-020
//	T-017 four-resolver agreement plus injected divergence ....... AC-021
//	T-018 literal-ref root, no --root flag ....................... AC-018
//	T-019 cycle / self / descendant destinations ................. AC-019
//	T-020 default-branch token is not rewritten .................. AC-020
//	T-021 destination ancestor of the old parent warns, still runs  §7.11
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

// reparentRefusalOf asserts err is a reparent refusal of the given kind and
// returns its detail, so a cell can go on to assert the sentence. It returns
// a string rather than the error value so an assertion-only call site is not
// an unchecked error return.
func reparentRefusalOf(t *testing.T, err error, want ReparentRefusalKind) string {
	t.Helper()
	if err == nil {
		t.Fatalf("expected refusal %s, got nil", want)
	}
	var refusal *ReparentRefusalError
	if !errors.As(err, &refusal) {
		t.Fatalf("error %v is not a reparent refusal", err)
	}
	if refusal.Kind != want {
		t.Fatalf("refusal kind = %s (%s), want %s", refusal.Kind, refusal.Detail, want)
	}
	return refusal.Detail
}

// reparentAssertPublishedResolution checks a refused destination still
// publishes closed-domain facts: resolution is a member of the §7.5b/§7.5
// domain (never the empty string), the requested token is preserved, and the
// candidate list is exactly what the run learned.
func reparentAssertPublishedResolution(t *testing.T, dest ReparentDestination, token, wantResolution string, wantCandidates []string) {
	t.Helper()
	domain := map[string]bool{
		ReparentResolutionEntry: true, ReparentResolutionRefFull: true,
		ReparentResolutionRefHead: true, ReparentResolutionRefTag: true,
		ReparentResolutionRefRemote: true, ReparentResolutionRefOther: true,
		ReparentResolutionRawOID: true, ReparentResolutionUnresolved: true,
		ReparentResolutionAmbiguous: true,
	}
	if !domain[dest.Resolution] {
		t.Fatalf("resolution %q is outside the closed domain", dest.Resolution)
	}
	if dest.Resolution != wantResolution {
		t.Fatalf("resolution = %q, want %q", dest.Resolution, wantResolution)
	}
	if dest.RequestedToken != token {
		t.Fatalf("requested token = %q, want %q", dest.RequestedToken, token)
	}
	if len(dest.Candidates) != len(wantCandidates) {
		t.Fatalf("candidates = %v, want %v", dest.Candidates, wantCandidates)
	}
	for i := range wantCandidates {
		if dest.Candidates[i] != wantCandidates[i] {
			t.Fatalf("candidate %d = %q, want %q (sorted)", i, dest.Candidates[i], wantCandidates[i])
		}
	}
	if dest.SHA != "" {
		t.Fatalf("a refused destination must pin no SHA, got %q", dest.SHA)
	}
}

// reparentBulkObjects writes count blobs in ONE git invocation and returns
// their object ids, so an abbreviated-OID collision can be produced
// deterministically without hundreds of process spawns.
func reparentBulkObjects(t *testing.T, repo *reparentRepo, count int) []string {
	t.Helper()
	dir := filepath.Join(repo.Dir, "bulk")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatal(err)
	}
	paths := make([]string, 0, count)
	for i := 0; i < count; i++ {
		name := filepath.Join(dir, fmt.Sprintf("blob-%04d.txt", i))
		if err := os.WriteFile(name, []byte(fmt.Sprintf("bulk object %d\n", i)), 0o644); err != nil {
			t.Fatal(err)
		}
		paths = append(paths, name)
	}
	cmd := exec.Command("git", append([]string{"-C", repo.Dir, "hash-object", "-w"}, paths...)...)
	cmd.Env = append(os.Environ(), "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_COUNT=0", "HOME="+repo.Dir)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("bulk hash-object: %v\n%s", err, out)
	}
	var oids []string
	for _, line := range strings.Split(string(out), "\n") {
		if line = strings.TrimSpace(line); line != "" {
			oids = append(oids, strings.ToLower(line))
		}
	}
	return oids
}

// reparentCollidingPrefix finds a 4-hex prefix shared by at least two objects.
func reparentCollidingPrefix(t *testing.T, oids []string) string {
	t.Helper()
	seen := make(map[string]int, len(oids))
	for _, oid := range oids {
		prefix := oid[:4]
		seen[prefix]++
		if seen[prefix] > 1 {
			return prefix
		}
	}
	t.Skip("no 4-hex object-id collision was produced; the ambiguity cell needs one")
	return ""
}

func reparentWidth(t *testing.T, repo *reparentRepo) int {
	t.Helper()
	width, err := reparentOIDWidth(repo.Dir)
	if err != nil {
		t.Fatalf("reparentOIDWidth: %v", err)
	}
	return width
}

