var reparentInternalCellRe = regexp.MustCompile(`\bT-\d{3}\b`)

var reparentInternalACRe = regexp.MustCompile(`\bAC-\d{2,3}\b`)

// reparentInternalSuiteFiles is every test file of this package that may carry
// a citation. It is derived from the directory, so a new file cannot escape
// the check.
func reparentInternalSuiteFiles(t *testing.T) []string {
	t.Helper()
	entries, err := os.ReadDir(".")
	if err != nil {
		t.Fatal(err)
	}
	var out []string
	for _, e := range entries {
		name := e.Name()
		if e.IsDir() || !strings.HasSuffix(name, "_test.go") || name == "reparent_matrix_test.go" {
			continue
		}
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

// TestReparentInternalMatrix_EveryOwnedCellHasExactlyOneOwner proves the
// package-internal ledger is neither stale nor double-claimed.
func TestReparentInternalMatrix_EveryOwnedCellHasExactlyOneOwner(t *testing.T) {
	claims := map[string][]string{}
	for _, name := range reparentInternalSuiteFiles(t) {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		for _, cell := range uniqueStrings(reparentInternalCellRe.FindAllString(string(data), -1)) {
			claims[cell] = append(claims[cell], name)
		}
	}
	for cell, files := range claims {
		if len(files) != 1 {
			sort.Strings(files)
			t.Errorf("%s is claimed by %d files (%s); exactly one file may own a cell",
				cell, len(files), strings.Join(files, ", "))
		}
		if _, declared := reparentInternalCellOwner[cell]; !declared {
			t.Errorf("%s is cited by %s but is not in this package's ledger; add it, or move the cell to the package that owns it",
				cell, files[0])
		}
	}
	for cell, want := range reparentInternalCellOwner {
		files, ok := claims[cell]
		if !ok {
			t.Errorf("%s is declared owned by %s but is cited nowhere", cell, want)
			continue
		}
		if files[0] != want {
			t.Errorf("%s is owned by %s, but the ledger names %s", cell, files[0], want)
		}
	}
}

// TestReparentInternalMatrix_OwnedFilesCiteAcceptanceCriteria keeps a cell
// from drifting into a file that asserts nothing the spec asked for.
func TestReparentInternalMatrix_OwnedFilesCiteAcceptanceCriteria(t *testing.T) {
	owners := map[string]bool{}
	for _, file := range reparentInternalCellOwner {
		owners[file] = true
	}
	for file := range owners {
		data, err := os.ReadFile(file)
		if err != nil {
			t.Fatal(err)
		}
		if len(reparentInternalACRe.FindAllString(string(data), -1)) == 0 {
			t.Errorf("%s owns at least one matrix cell and must cite at least one AC-nnn", file)
		}
	}
}

// ---------------------------------------------------------------------------
// The measured real-Git leaf budget (§17.3)
// ---------------------------------------------------------------------------

// ReparentInternalLeafBudget is this package's share of §17.3's 120-leaf
// total. The CLI package declares its own share and asserts that the two sum
// to at most the total, so neither package can quietly spend the other's.
// The value is the MEASURED count (56 at the time of writing) plus a small
// margin, so a new cell is a deliberate decision rather than a silent drift.
const ReparentInternalLeafBudget = 57

// reparentInternalLeafNames records the DISTINCT t.Run leaves that built a
// real repository. §17.3 counts leaves, not repositories: "a real-Git cell is
// one t.Run leaf that spawns at least one git process. Sub-cases of a
// table-driven test each count as one leaf." A leaf that builds two
// repositories is still one leaf; a table of ten sub-cases is ten.
var (
	reparentInternalLeafMu    sync.Mutex
	reparentInternalLeafNames = map[string]bool{}
)

func reparentCountGitLeafFor(t *testing.T) {
	t.Helper()
	reparentInternalLeafMu.Lock()
	reparentInternalLeafNames[t.Name()] = true
	reparentInternalLeafMu.Unlock()
}

// ReparentInternalMeasuredLeaves is the count so far.
func ReparentInternalMeasuredLeaves() int {
	reparentInternalLeafMu.Lock()
	defer reparentInternalLeafMu.Unlock()
	return len(reparentInternalLeafNames)
}

// TestMain asserts the measured budget after the whole package has run. A
// partial `-run` selection measures fewer leaves and still passes, because the
// assertion is a ceiling, never an equality.
func TestMain(m *testing.M) {
	code := m.Run()
	if os.Getenv("REPARENT_DUMP_LEAVES") != "" {
		reparentInternalLeafMu.Lock()
		names := make([]string, 0, len(reparentInternalLeafNames))
		for n := range reparentInternalLeafNames {
			names = append(names, n)
		}
		reparentInternalLeafMu.Unlock()
		sort.Strings(names)
		_ = os.WriteFile(os.Getenv("REPARENT_DUMP_LEAVES"), []byte(strings.Join(names, "\n")+"\n"), 0o644)
	}
	if used := ReparentInternalMeasuredLeaves(); used > ReparentInternalLeafBudget {
		println("reparent: package internal spawned", used, "real-Git leaves, over its budget of", ReparentInternalLeafBudget)
		if code == 0 {
			code = 1
		}
	}
	os.Exit(code)
}

func uniqueStrings(in []string) []string {
	seen := map[string]bool{}
	var out []string
	for _, v := range in {
		if seen[v] {
			continue
		}
		seen[v] = true
		out = append(out, v)
	}
	return out
}

