func TestStackStatus_ExternalMaterializationMatrix(t *testing.T) {
	fx := ssNewExternalFixture(t, "auth")
	other := filepath.Join(fx.root, "other")
	if err := os.MkdirAll(other, 0o755); err != nil {
		t.Fatal(err)
