	}

	fine := Stack{Branches: []StackEntry{{Name: "a", Base: "main"}}}
	if _, err := ReparentClosureOrder(fine, "missing"); err == nil {
		t.Fatal("expected an error for an unknown target")
	}

	duplicated := Stack{Branches: []StackEntry{
		{Name: "a", Base: "main"},
